// مولّدة آلياً بواسطة scripts/split-fatwas.mjs — لا تُعدَّل يدوياً.
export default [{"id":64,"question":"سماحة الشيخ رعاكم الله، زوجي توفي في بداية هذا الشهر صفر، وكان قد تحدد موعد زواج ولدي من قبل وفاته والده في شهر ربيع الأول، فهل يجوز لي حضور حفل الزواج، أفيدوني جزاكم الله خيرًا؟","title":"ما أحكام المُعْتَدَّة من وفاة زوجها؟","answer":"الجواب: لا مانع من أن يتزوج في ربيع أول، أقول: لا مانع، الحمد لله، يتزوج، ونسأل الله أن يوفقه، وأنت إذا حضرتِ وأنتِ في البيت لا تخرجي من البيت من دون زينة ولا طِيب، لا بأس تحضرين لكن من دون زينة ولا طيب، وأنت في البيت؛ لأن المحادة تبقى في بيت زوجها ولا تلبس الثياب الجميلة، بل ثياب العادة، ولا تتطيب، ولا تلبس الحلي، ولا تكتحل، حتى تكمل العدة.","link":"https://binbaz.org.sa/fatwas/2980/ما-احكام-المعتدة-من-وفاة-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0039.mp3","categories":["العِدَد"]},{"id":119,"question":"إذا تُوفي زوجٌ عن زوجته قبل أن يدخل بها، هل ترثه؟ وهل تعتدّ ولها المهر؟","title":"حكم من يتوفي عنها زوجها قبل الدخول بها","answer":"الجواب: نعم، إذا عقد عليها ثم مات قبل الدّخول بها ترثه، وعليها العِدَّة، ولها الميراث، ولها مهرها المُسمَّى، وإن لم يكن سمَّى لها مهرًا يكون لها مثل مهر نسائها، كما ثبت في الحديث عن معقل بن سنان الأشجعي، وأفتى به ابنُ مسعودٍ، فإذا مات الزوج قبل أن يدخل بها، وقبل أن يُسمِّي لها مهرًا؛ فلها مهر نسائها، لا وكس، ولا شطط، وعليها العِدَّة، ولها الميراث.","link":"https://binbaz.org.sa/fatwas/3557/حكم-من-يتوفي-عنها-زوجها-قبل-الدخول-بها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0104.mp3","categories":["العِدَد"]},{"id":538,"question":"امرأة توفي عندها زوجها وهي في الرياض ليس عندها أحد، وأخوها مقيم في مكة، فهل يجوز لها السفر إليه والعمرة مع محرم لها؟","title":"حكم سفر المرأة أثناء فترة الحداد","answer":"الجواب: إذا كان عليها خطر؛ ما تستطيع البقاء، ما عندها من يؤنسها؛ فلا حرج، أما إن كان عندها من يؤنسها وما عليها خطر؛ عندها خادمة، عندها أخلّاء، عندها أم الزوج، عندها من يؤنسها ويزيل وحشتها؛ فليس لها حتى تنتهي العدة، أما إذا كان لا مضطرة فلا بأس.\n(دروس شرح بلوغ المرام، كتاب النكاح)","link":"https://binbaz.org.sa/fatwas/6369/حكم-سفر-المراة-اثناء-فترة-الحداد","audio":"https://files.zadapps.info/binbaz.org.sa/maram104 - 02 - .mp3","categories":["العِدَد"]},{"id":552,"question":"المرأة التي لم يدخل بها زوجها هل لها عدة إذا طلقها؟","title":"هل لغير المدخول بها عِدّة؟","answer":"الجواب: إذا كان ما دخل بها ولا خلا بها؛ فما عليها عدة. الله جل وعلا بيّن: يَا أَيُّهَا الَّذِينَ آمَنُوا إِذَا نَكَحْتُمُ الْمُؤْمِنَاتِ ثُمَّ طَلَّقْتُمُوهُنَّ مِنْ قَبْلِ أَنْ تَمَسُّوهُنَّ فَمَا لَكُمْ عَلَيْهِنَّ مِنْ عِدَّةٍ تَعْتَدُّونَهَا [الأحزاب:49] فالخلوة في أصح القولين أنها بمثابة الدخول؛ لأنها مظنة الدخول، الخلوة مظنة الدخول، دخل دخلة كاملة؛ وجبت عليها العدة.\n(دروس شرح بلوغ المرام، كتاب النكاح)","link":"https://binbaz.org.sa/fatwas/6383/هل-لغير-المدخول-بها-عدة","audio":"https://files.zadapps.info/binbaz.org.sa/maram118 - 02 - .mp3","categories":["العِدَد"]},{"id":1390,"question":"بعض الناس في المحادة على زوجها أنها إذا انتهت يُقام لها مأدبة وبعض العزائم؟","title":"حكم عمل مأدبة عند انتهاء المحادة على الزوج","answer":"الجواب:\nما هو بمشروع، ولكنه مباح من باب المباحات؛ لأنها منحبسة مدة طويلة وإذا عزمها أقاربها لا بأس، وإلا ما هو بشرع عبادة، هي أمور عادية مثل القدوم من السفر والشفاء من المرض وأشباه ذلك، شكرًا لله.\nس: ما ينكر ذلك؟\nج: لا ما في إنكار.\nس: ليست نياحة، لا تعتبر نياحة؟\nج: لا،لا.","link":"https://binbaz.org.sa/fatwas/21483/حكم-عمل-مادبة-عند-انتهاء-المحادة-على-الزوج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم المأدبة عند انتهاء الزوجة من المحادة على زوجها.mp3","categories":["العِدَد"]},{"id":1566,"question":"إذا خلعت زوجَها كيف تكون عدَّتُها؟","title":"ما عدة من خالعت زوجها؟","answer":"الجواب:\nوَضْع الحمل، عدتها وَضْع الحمل، جميع المطلقات وجميع المتوفى عنهنَّ والمخلوعات كلهن إذا كُنَّ حُمَّلًا: وَضْع الحمل: وَأُولَاتُ الْأَحْمَالِ أَجَلُهُنَّ أَنْ يَضَعْنَ حَمْلَهُنَّ [الطلاق:4]، الطلاق والخلع والموت جميعًا.\nس: مدة النفاس ما تدخل في العدة؟\nج: لا، ما تدخل، إذا وضعت حملها اليوم؛ حلَّتْ للزوج الجديد، ولو كانت في النفاس.\nس: وإذا كان الحملُ أبْعَدُ الأجلين؟\nج: ولو أبْعَدُ الأجلين، عدتها وَضْعُ الحمل مطلقًا.","link":"https://binbaz.org.sa/fatwas/21669/ما-عدة-من-خالعت-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/عدة من خالعت زوجها.mp3","categories":["الطلاق","العِدَد","الخلع"]},{"id":1575,"question":"النساء البائنة بينونة صغرى أو كبرى عدتهن دائمًا في غير بيت الزوج؟","title":"أين تقضي المطلقة عدتها؟","answer":"الجواب:\nالرجعية في بيت الزوج إذا تيسَّر، أما إذا ما تيسَّر تذهب إلى أهلها. أما البائن فلا،ـ تَحْرُم، ما عادت زوجةً له، إذا طلَّقها ثلاثًا أو خالعها تخرج. فالرجعية إذا صارت عنده يُراجعها، أي أنَّ وجودها عنده من أسباب الرجعة، إذا كان طلَّقها طلقتين بعدما دخل بها.","link":"https://binbaz.org.sa/fatwas/21678/اين-تقضي-المطلقة-عدتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أين تقضي المطلقة عدتها.mp3","categories":["العِدَد"]},{"id":2000,"question":"(المُعْتَدَّة) لو كانت مُعَلِّمة؟","title":"حكم خروج المعتدة للعمل والتحدث بالهاتف","answer":"الجواب:\nتخرج لحاجة، هذا من الحاجات، مدرسة أو طالبة، هذا من الحاجات، أو عليها خصومة تروح المحكمة، أو مرض تروح المستشفى، هذه من الحاجات.\nس: لو كان \"تليفون\" ترد عليه؟\nالشيخ: و\"التليفون\" كذلك.\nس: ولو كان رجلًا؟\nالشيخ: ولو، ولو، تكلم وتُكلم، إذا صار كلامًا ما فيه شر، ما في شيء مثل غيرها.\nس: إذا كانت المُدَرِّسة تستطيع أخذ إجازة من المدرسة؟\nالشيخ: ولو استطاعت، المدة طويلة أربعة أشهر وعشرًا، ما هي بسهل، هذه حاجة من الحاجات، تخرج للحاجة وترجع للبيت مثل ما تخرج إلى السوق لحاجتها، تَتَسبَّب، تُدَوِّر الرزق، تخرج السوق، تشتري حاجة وتبيع حاجة وترجع إلى بيتها، لحاجتها.","link":"https://binbaz.org.sa/fatwas/22116/حكم-خروج-المعتدة-للعمل-والتحدث-بالهاتف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم خروج المرأة المعتدة للعمل والرد على التلفون.mp3","categories":["العِدَد","قضايا المرأة"]},{"id":2001,"question":"بعض النساء اعتادت على لبس الأسود (في العدة)؟","title":"ما حكم لبس الأسود للنساء في العدة؟","answer":"الجواب:\nما هو بلازم، أسود وإلا غيره، شيء ما هو بجميل، أسود أو أصفر أو أحمر، لكن ما يكون فيه جمال، من اللباس العادية.","link":"https://binbaz.org.sa/fatwas/22117/ما-حكم-لبس-الاسود-للنساء-في-العدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم لبس الأسود للنساء في العدة.mp3","categories":["العِدَد","قضايا المرأة"]},{"id":2002,"question":"امرأة تزوجت ابنتها، وزواجها سيكون بعد الإحداد مباشرة، فهل للأم أن تخرج مع ابنتها لأجل التَّقَضي؟","title":"حكم خروج المعتدة لحاجتها ومحادثة الرجال","answer":"الجواب:\nللحاجة ما يخالف، هذه من الحاجات، أقول: تخرج من غير زينة، هذا من الحاجة، مثل ما تشتري لنفسها حاجة تشتري لابنتها حاجة.\nس: هل يجوز أن تحدث الرجال الأجانب من وراء حجاب؟\nالشيخ: ولو من دون حجاب، النساء يتحدثن مع النبي ﷺ ومع الصحابة من دون حجابة، بس تستر وجهها وتستر بدنها ولو ما هو بداخل حجرة.\nس: لا يشترط أن يكون ما يراها؟\nالشيخ: لا ما هو بلزوم، تستتر، تتحجب باللباس بالخمار وغيره وتتحدث، تسأل العالم عن حاجاتها، وتقف عند المحكمة، لكن مستورة.","link":"https://binbaz.org.sa/fatwas/22118/حكم-خروج-المعتدة-لحاجتها-ومحادثة-الرجال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم خروج المرأة المعتدة لحاجتها ومحادثة الرجال.mp3","categories":["العِدَد","قضايا المرأة"]},{"id":2058,"question":"المرأة إذا طُلِّقَتْ في طَلْقِها، وهي تَطْلُق في حملها، كيف تكون عِدَّتُها؟","title":"ما عدة من طلقت وهي في طَلْق الولادة؟","answer":"الجواب:\nما وَلَدَت بعد؟\nس: نعم ما وَلَدَت.\nج: إذا وَلَدَت خرجت من العدة، إذا صار الطلاقُ قبل سقوط الحمل.","link":"https://binbaz.org.sa/fatwas/22176/ما-عدة-من-طلقت-وهي-في-طلق-الولادة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/عدة المطلقة حال طلقها.mp3","categories":["العِدَد"]},{"id":2219,"question":"أقل شيء في الرَّجْعَة من الزوج لزوجته دون الإشهاد؟","title":"بم تثبت رَجْعَةُ المطلقة؟","answer":"الجواب:\nالجماع.\nس: طيب، لو حصلت مُباشرة أو تقبيل فقط؟\nج: لا، الجماع فقط، فإمَّا الجماع أو القول بشاهدين، أما القبلة واللمس فلا يكفي.","link":"https://binbaz.org.sa/fatwas/22342/بم-تثبت-رجعة-المطلقة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/بم تثبت رجعة المطلقة.mp3","categories":["العِدَد","الرجعة","قضايا المرأة"]},{"id":2233,"question":"ليس لها في الرياض إلا أب لها وهو ساكنٌ معها في نفس البيت، وقد طلَّقها زوجُها الطلقة الثالثة، وتقول: أين أعتدّ؟","title":"أين تعتد مَن ليس لها سَكَنٌ غير بيت زوجها؟","answer":"الجواب:\nعند أبيها.\nس: أبوها معها في نفس البيت؟\nج: تعتدّ عند أبيها.\nس: ويخرج الزوج من البيت؟\nج: هو نازلٌ عليهم؟\nس: نعم.\nج: انتهى، ما عادت له زوجة؛ فقد بانت منه بالطّلقة الثالثة، وقوله: لَا تُخْرِجُوهُنَّ مِنْ بُيُوتِهِنَّ وَلَا يَخْرُجْنَ [الطلاق:1] هذا في الرّجعية.\nس: لكن ليس لها مكانٌ آخر، ولا تستطيع الرجوع إلى بلادها؟\nج: هي عند أبيه أم عند أبيها؟\nس: عند أبيها، فأبوها معها.\nج: تبقى في البيت.\nس: يخرج الزوج ويستأجر مكانًا آخر؟\nج: ما هو بلازمٍ، ولكن لا يخلو بها، ولا بأس لو كلَّمته أو سلَّمت عليه، والحمد لله.\nس: تتغطَّى عنه؟\nج: تحتجب عنه.","link":"https://binbaz.org.sa/fatwas/22356/اين-تعتد-من-ليس-لها-سكن-غير-بيت-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/طلقت الطلقة الثانية وليس لها سكن غير منزل زوجها فأين تعدت.mp3","categories":["العِدَد"]},{"id":2283,"question":"مَن طُلقت في عدَّتها طَلقةً غير الطَّلقة الأولى كيف تكون عدَّتُها؟","title":"عدة مَن طُلقت في عدَّتها غير الطَّلقة الأولى","answer":"الجواب:\nمِن الطّلقة الأولى إذا لم يكن وطئها بعد الطلقة الأولى، فإذا طلَّقها طلقةً ثم بعد يوم أو يومين أو أسبوع أو أسبوعين طلَّقها طلقةً ثانيةً فإنها تعتدُّ ابتداءً من الأولى إذا كان إنما هو كلام، أما إذا كان راجعها فعليها أن تعتدَّ من الثانية.","link":"https://binbaz.org.sa/fatwas/22406/عدة-من-طلقت-في-عدتها-غير-الطلقة-الاولى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/عدة من طلقت في عدَّتها طلقةً غير الطلقة الأولى.mp3","categories":["العِدَد"]},{"id":2378,"question":"(بالنسبة للمحادّة) هل الشامبو والأحمر يُستخدم أم لا؟","title":"حكم الصابون والسِّدر والشامبو للمحادّة","answer":"الجواب:\nلا بأس، في حال الإحداد الشامبو يُستعمل، ما هو بطِيب، الشامبو والسِّدْر ليس بطِيب، والصابون كذلك، لكن مس الذي داخله رائحة إذا تُرك من باب الاحتياط حَسَن، وإلا بقية الصابون والأشنان والسدر والشامبو؛ كل هذا لا حرج فيه في حق المحادة.","link":"https://binbaz.org.sa/fatwas/22503/حكم-الصابون-والسدر-والشامبو-للمحادة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/استعمال الصابون والأشنان والسدر والشامبو للمحاداة.mp3","categories":["العِدَد"]},{"id":2379,"question":"سؤال آخر: تقول: هل أشتغل وأمشي في البيت ليلًا أو نهارًا حتى الساعة ثنتين أو ثلاثة والخروج إلى الحوش يجوز أم لا (أي بالنسبة للمحادّة)؟","title":"ما الأمور التي يجب أن تجتنبها المحادة؟","answer":"الجواب:\nالمحادّة مثل غيرها؛ تمشي في البيت محتفية أو منتعلة في البيت، في صحن البيت، في حوش البيت، في حديقة البيت، في السطوح، في القمر أو في الظلمة، مثل غيرها. الأمور الخمس عليها أن تجتنبها المحادّة:\nالأول: عدم الخروج من بيتها، تلزم سكنها الذي مات زوجها وهي ساكنة فيه، تلزمه إلا من حاجة خروجها، مثل: شراء حاجاتها من السوق، خروجها للطبيب، للمحكمة إذا كان هناك خصومة، لا بأس؛ الحاجات.\nالثاني: تكون ملابسها عادية، ما تلبس الجميل، تلبس ملابس عادية.\nالثالث: عدم الطِّيب لا في بدنها ولا في ثيابها، إلا إذا طَهُرت من حيضها فلها أن تَبَخَّر عند طُهرها من الحيض.\nالرابع: عدم الحُلِيّ؛ لا تلبس الحلي، لا ذهب ولا فضة ولا ماس.\nالخامس: عدم الحناء والتّكحل.\nهذه خمسة أشياء:\nالأول: لزومها البيت إلا من حاجة -الذي هي ساكنة فيه يوم مات زوجها- تلزمه، ولها الخروج لحاجتها أو للمحكمة أو للطبيب.\nالثاني: عدم الملابس الجميلة؛ ملابس عادية.\nالثالث: عدم الحلي، لا ذهب ولا فضة ولا ماس؛ حتى تخرج من العدة.\nالرابع: عدم الطيب، بخور أو غيره، إلا إذا طهرت من حيضها تبخرت.\nالخامس: عدم التكحل والحناء ونحوه حتى تنتهي.\nولها أن تفعل ما يفعل الناس سوى ذلك، تغير ثيابها متى شاءت، تروّش متى شاءت، تمشي في البيت في صحن البيت في حوش البيت في حديقة البيت في الصحن، كل ذلك لا بأس به، تكلم من شاءت بالتلفون أو غيره، حاجتها، ترد السلام على مَنْ سلم عليها من الرجال والنساء كل هذا لا بأس.\nس: وكذلك تقول: المغاطيط التي توجد في السراويل، وكذلك المغاطيط التي توضع في الرأس؟\nالشيخ: ما في بأس.","link":"https://binbaz.org.sa/fatwas/22504/ما-الامور التي-يجب-ان-تجتنبها-المحادة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من أحكام المحاداة.mp3","categories":["العِدَد"]},{"id":2702,"question":"امرأة كانت مقيمة في أمريكا مع زوجها وبناتها وعادت إلى وطنها لزيارة الأقارب وتوفي عنها زوجها في وطنها، السؤال أين تقضي أيام العدة: في أمريكا أو في وطنها، علمًا بأنها ترغب أن تقضي أيام العدة في أمريكا لدراسة بناتها، فما رأي سماحتكم في ذلك؟","title":"أين تكون عِدّةُ مَن توفي زوجُها في بلد آخر؟","answer":"الجواب: عليها أن تقضي العدة في بلدها الذي مات زوجها وهي ساكنة فيه، ولا تسافر تقضيها في بلدها.","link":"https://binbaz.org.sa/fatwas/22843/اين-تكون-عدة-من-توفي-زوجها-في-بلد-اخر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/توفي زوجها في وطنها وهي مقيمة في بلاد الغربة فأين تقضي العدة.mp3","categories":["العِدَد"]},{"id":4959,"question":"إحداد المرأة على القريب، ما تخرج المرأة من البيت؟","title":"حكم خروج المرأة من البيت فترة الإحداد","answer":"الجواب: لها أن تخرج، ولها أن تبقى في بيتها، ولها أن تلبس ملابس جميلة ثلاثة أيام.\nس: تعمل في المدرسة؟\nالشيخ: لها الخروج للمدرسة، تخرج لحاجاتها، هذه من الحاجات، تخرج للتدريس، أو موظفة، أو طالبة، هذا من الحاجات، لكن من غير تَجَمُّل، ولا طِيب.","link":"https://binbaz.org.sa/fatwas/27562/حكم-خروج-المراة-من-البيت-فترة-الاحداد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم خروج المرأة من البيت فترة الإحداد؟.mp3","categories":["العِدَد"]},{"id":5111,"question":"سماحة الشيخ رعاكم الله، زوجي توفي في بداية هذا الشهر صفر، وكان قد تحدد موعد زواج ولدي من قبل وفاة والده في شهر ربيع الأول، فهل يجوز لي حضور حفل الزواج، أفيدوني جزاكم الله خيرًا؟","title":"ما حكم خروج المعتدة لوفاة زوجها لحفل زفاف؟","answer":"الجواب: لا مانع من أن يتزوج في ربيع أول، أقول لا مانع الحمد لله يتزوج، ونسأل الله أن يوفقه، وأنت إذا حضرت وأنت في البيت، لا تخرجي من البيت، من دون زينة ولا طيب، لا بأس تحضرين لكن من دون زينة ولا طيب، وأنت في البيت؛ لأن المحادة تبقى في بيت زوجها ولا تلبس الثياب الجميلة بل ثياب العادة، ولا تتطيب، ولا تلبس الحلي، ولا تكتحل حتى تكمل العدة.","link":"https://binbaz.org.sa/fatwas/30019/ما-حكم-خروج-المعتدة-لوفاة-زوجها-لحفل-زفاف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 039.mp3","categories":["العِدَد"]},{"id":5741,"question":"توفي والدي إلى رحمة الله، وترك والدتي وهي امرأة كبيرة، ولها أولاد في الرياض وخارجها، وهي الآن في عدتها، وتريد أن تزورهم، أو تزور غيرهم، فما حكم ذلك؟","title":"حكم خروج المرأة في عدتها لزيارة أولادها","answer":"الجواب:  المحادة التي توفي عنها زوجها تلزم بيتها، ولا تخرج؛ لأن الرسول -عليه الصلاة والسلام- قال: امكثي في بيتك حتى يبلغ الكتاب أجله هذه المحادة تلزم بيتها، ولا تلبس الملابس الجميلة، ولا تطيب، ولا تكتحل، ولا تلبس الحلي، خمس أمور في المحادة ينبغي أن تحفظوها: الأول: لزوم البيت حتى تنتهي العدة. الثاني: عدم لبس الثياب الجميلة، لكن تلبس الثياب غير الجميلة من أسود وأحمر وأخضر وأزرق لكن غير جميلة. الثالث: عدم الحلي من الذهب والفضة والماس واللؤلؤ وغير ذلك، فلا تلبس الحلي والساعة من الحلي؛ لأنها جمال وزينة ينبغي أن تكون في جيبها، أو في محل آخر تستفيد منها. الرابع: عدم الكحل، لا تكتحل ولا تجعل في وجهها من الزينات التي يعتادها النساء اليوم غير الماء والصابون. الخامس: الطيب. كل هذه خمسة أمور، ترك الطيب، ترك الحلي، ترك الثياب الجميلة\"... لكن إذا كان هناك حاجة مثل الطبيب دعت الضرورة للخروج إلى الطبيب للدواء لا بأس، أو ما عندها من يخدمها تخرج لحاجاتها من السوق طعام تأتي به، خضرة تأتي بها ما عندها من يقوم بحاجاتها لا بأس تخرج أما كونها زيارات الأولاد فهذا لا تخرج.","link":"https://binbaz.org.sa/fatwas/1053/حكم-خروج-المراة-في-عدتها-لزيارة-اولادها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_70.mp3","categories":["العِدَد","قضايا المرأة"]},{"id":5798,"question":"........؟","title":"الأحكام المتعلقة بمن توفي عنها زوجها","answer":"الجواب: وهي ساكنة فيه إذا تبقى فيه إذا كان صالحًا، إذا أمكن، أما إذا كان ما أمكن، واستأجر، وأبى أهله، أو خرب، أو ما عندها أحد يؤنسها، تخشى على نفسها تخرج إلى بيت أهله، أو إلى من شاءت، لكن إذا تيسر بقاؤها في البيت لمن مات زوجها وهي ساكنة فهذا هو الواجب لهذا الحديث؛ لأن النبي -عليه الصلاة والسلام- قال: امكثي في بيتك حتى يمضي الكتاب.. حتى تنتهي العدة. الأمر الثاني: اجتنابها ما يجمل وجهها من مساحيق، وكحل، ونحو ذلك. الثالث: اجتنابها الطيب، لا تطيب المحاداة إلا عند غسلها من  الحيض، تأخذ شيئًا من قسط .. من البخور، يعني لا بأس عند طهرها من الحيض، أما أن تطيب بالعود في أي وقت بالعود، أو بالورد، أو بالعنبر لا، تجتنب الطيب حتى تنتهي إلا عند طهرها من الحيض، فلا بأس أن تتعاطى شيئًا من البخور، كالقسط ... أو نحوه من البخور الذي يزيل رائحة الدم، وما يترتب على ذلك. مضى ثلاثة: لزوم البيت، واجتناب ما يجمل وجهها، ويرغب الناس فيها من الكحل، والمساحيق للوجه، الثالث: أن تجتنب الطيب بأنواعه. الرابع: الملابس الجميلة المصبوغة التي تلفت النظر إليها، وتجملها عند الناس، وترغب في خطبتها، والنظر إليها تجتبنها، تلبس الثياب الغير جميلة، إما أسود ما هو بجميلـ أو أزرق ما هو بجميل، أو أخضر ما هو بجميل، أو أحمر ما هو بجميل، المهم أن الملابس الجميلة تجتنبها ولا يختص بالسواد، ما هو بلزوم السواد، أسود أو أزرق أو أخضر أو أحمر أو أصفر، لكن يكون ملابس ما هي بجميلة؛ لأن الرسول ﷺ قال: لا تلبس ثوبًا إلا ثوب .. لأن ثوب ... ذكر العلماء أنه ثوب ما هو بجميل، بخلاف الثياب المصبوغة .. جميل، فهذا تجتنبه المحاداة. والخامس: الحلي بأنواعها من قلائد، أو خواتم، أو أسورة، أو غير ذلك من الحلي، تجتنب الحلي، ولا تلبس الحلي، هذه خمسة أمور تجتنبها المحاداة، وهذا الذي جاءت به الأحاديث خمسة. أما ما يتكلفه بعض الناس، يقولون لها: لا تكلمي بالتلفون، ولا تكلمي أحدًا، فهذا ماله أصل، تكلم من شاءت مثل حال حياته، تكلم من شاءت من غير ريبة.  كذلك كونها تعمل في بيتها لحاجات بيتها، تحلب بقرتها وغنمها، تكنس بيتها، تطبخ طعامها، تمشي في القمر في الليل في السطوح لا بأس به، كل هذا لا بأس به، تخرج للحاجة في النهار، تأتي بخبزها، وحاجاتها إذا كان ما هناك من يكفيها المؤنة، تحتاج إلى الطبيب، تخرج إلى الطبيب في النهار إذا تيسر ذلك، وأمكن؛ لأن هذه حاجات لا بدّ منها، ولا مانع من خروجها للحاجة.  فهذا ما يتعلق بالتعليق على الندوة المباركة التي قام بها الشيخان جزاهما الله خيرًا، وأسأل الله لنا جميعًا التوفيق، والهداية، والمزيد من العلم النافع، والعمل الصالح، وصلى الله وسلم على نبينا محمد، وعلى آله وأصحابه.","link":"https://binbaz.org.sa/fatwas/1128/الاحكام-المتعلقة-بمن-توفي-عنها-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_134.mp3","categories":["العِدَد","قضايا المرأة"]},{"id":5808,"question":"هل تنزع الحلية، ولو كان في ذلك مشقة؟ وهل الإحداد يشمل الطاعنة في السن؟","title":"حكم الإحداد للكبيرة والحلية التي يشق نزعها","answer":"الجواب: نعم الإحداد يعم الشابات، والطاعنة في السن، كلهن عليهن حداد، يعم المدخولة بها، والتي لم يدخل بها، لو عقد على امرأة، ومات قبل الدخول بها؛ لزمها العدة، والإحداد أيضًا بخلاف الطلاق، فالمطلقة إذا كان ما دخل بها؛ ما عليها عدة، لكن المتوفى عنها إذا مات عنها، وقد عقد عليها، ولم يدخل؛ فعليها العدة، وعليها الإحداد، ولها الميراث. فالطاعنة في السن، والشابة كلتاهما سواء في وجوب العدة، والإحداد، كذلك الحلي إذا كان عليها حلي ينزع الحلي، ولو بقي كالأسورة، وضاقت على يدها تقص، وتخرج، لا تبقى بيدها.","link":"https://binbaz.org.sa/fatwas/1140/حكم-الاحداد-للكبيرة-والحلية-التي-يشق-نزعها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_146.mp3","categories":["العِدَد","قضايا المرأة"]},{"id":5897,"question":"هناك بعض القبائل في الحجاز أذكر منها: قبيلة ثقيف، وقبيلة بني مالك، وبعض من قبيلة بني الحارث؛ حيث إن المرأة عندهم لا تحد على زوجها عند وفاته، وما الحكم في ذلك؟","title":"هل يجوز للمرأة ترك الإحداد على زوجها؟","answer":"الجواب: هذا على كل حال من الجهل، يجب أن يزال بالعلم، سواء كان في بني مالك، أو ثقيف، أو غير ذلك، لا بدّ أن يبلغ الدعاة الناس، والقضاة، بأن يوجهوا الناس إلى هذا الشيء الذي يجهلونه، وهو عدم الإحداد، أن المرأة إذا مات زوجها لا تحد عليه. والإحداد هو ترك الزينة، والطيب، والحلي، ونحو ذلك وقت العدة حتى تنتهي العدة، ويبلغن ذلك -إن شاء الله- هذا واجب أن يبلغن أن الرسول ﷺ أمر بالإحداد على الزوجة أربعة أشهر وعشرًا، والإحداد هو ترك ما يدعو إلى نكاحها، ويرغب بها من أنواع المحسنات من ملابس جميلة، والطيب، والحلي، والكحل، وأشباه ذلك، وعليها أن تلزم بيتها وقت العدة؛ حتى تنتهي عدة الوفاة، وإذا  كانت حاملًا حتى تضع الحمل. السؤال: باقي السؤال: كما أن الرجل عندهم يبدل بأخته، أو ابنته في زوجة له، دون أن يدفع طرف أي شيء من النقد، فهل يجوز ذلك؟ وما تعليق سماحتكم على هذا؟ الجواب: هذا يقال له: الشغار، ويسميه بعض الناس نكاح البدل، وهو أن يقول شخص لآخر: زوجني بنتك وأزوجك بنتي، أو أختك، أو بنت أخيك، هذا يسمى نكاح البدل، وهو نكاح الشغار.  وقد نهى النبي ﷺ عن نكاح الشغار في عدة أحاديث، نهى الرسول ﷺ عن نكاح الشغار، وهو أن يقول الرجل للآخر: زوجني بنتك، وأزوجك بنتي، أو زوجني أختك، وأزوجك أختي، أو يقول: زوج ابني، وابنك، أو ابني، وخالك، أو ما أشبه ذلك؛ هذا لا يجوز، هذا منكر يجب الحذر منه؛ حتى ولو سموا مهرًا، الواجب الحذر من ذلك، وألا تكون المرأة مهرًا للأخرى؛ بل هذا يخطبها، وهذا يخطب، فمن ناسبه قبل، ومن لا فلا، أما أن يتشارطا البدل هذا يعطيه بنته، وهذا يعطيه بنته، أو أخته، أو بنت أخيه، يعني موليته، هذا لا يجوز، والنكاح فاسد، ولو سمى مهرًا. وذهب بعض العلماء إلى إنه إذا سمى مهرًا بالمثل؛ صح، ولكنه قول مرجوح، والصواب: أنه لا يجوز تعاطي هذا النكاح  مطلقًا، ولو سمي مهرًا. وقد ثبت عند أحمد، وأبي داود، وغيرهما أن شخصين في المدينة تناكحا شغارًا، وقد سميا مهرًا، فرفع ذلك إلى أمير المؤمنين معاوية  فكتب إلى أمير المدينة: أن يفرق بينهما، وقال: هذا هو الشغار الذي نهى عن النبي -عليه الصلاة والسلام- وكانا قد سميا مهرًا. وأما ما يروى في حديث ابن عمر في تفسير الشغار، وأنه هو الذي ليس فيه مهر، فهذا من كلام نافع الراوي عن ابن عمر، وقال جماعة: هو من كلام مالك بن أنس، الراوي أيضًا. وبكل حال فهذا ليس من كلام النبي ﷺ تفسير الشغار بأنه الخلو من المهر ليس من كلام النبي ﷺ ولكنه من كلام بعض الرواة، وكلام الراوي لا يكون حجة، الحجة في كلام النبي -عليه الصلاة والسلام- والنبي نهى عن الشغار، ولم يفسره بعدم المهر؛ بل فسره بأن يقول هذا: زوجتك أختي، أو بنتي، والآخر يقول كذلك: أو يقول: زوجني وأزوجك، هكذا فسره النبي -عليه الصلاة والسلام- هذا يعم ما إذا كان فيه مهر، أو ما إذا خلا من المهر.","link":"https://binbaz.org.sa/fatwas/1252/هل-يجوز-للمراة-ترك-الاحداد-على-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_248.mp3","categories":["العِدَد","قضايا المرأة"]},{"id":5906,"question":"هناك بعض القبائل في الحجاز أذكر منها: قبيلة ثقيف، وقبيلة بني مالك، وبعض من قبيلة بني الحارث؛ حيث إن المرأة عندهم لا تحد على زوجها عند وفاته، وما الحكم في ذلك؟","title":"هل يجوز للمرأة ترك الإحداد على زوجها؟","answer":"الجواب: هذا على كل حال من الجهل، يجب أن يزال بالعلم، سواء كان في بني مالك، أو ثقيف، أو غير ذلك، لا بدّ أن يبلغ الدعاة الناس، والقضاة، بأن يوجهوا الناس إلى هذا الشيء الذي يجهلونه، وهو عدم الإحداد، أن المرأة إذا مات زوجها لا تحد عليه. والإحداد هو ترك الزينة، والطيب، والحلي، ونحو ذلك وقت العدة حتى تنتهي العدة، ويبلغن ذلك -إن شاء الله- هذا واجب أن يبلغن أن الرسول ﷺ أمر بالإحداد على الزوجة أربعة أشهر وعشرًا، والإحداد هو ترك ما يدعو إلى نكاحها، ويرغب بها من أنواع المحسنات من ملابس جميلة، والطيب، والحلي، والكحل، وأشباه ذلك، وعليها أن تلزم بيتها وقت العدة؛ حتى تنتهي عدة الوفاة، وإذا  كانت حاملًا حتى تضع الحمل. السؤال: باقي السؤال: كما أن الرجل عندهم يبدل بأخته، أو ابنته في زوجة له، دون أن يدفع طرف أي شيء من النقد، فهل يجوز ذلك؟ وما تعليق سماحتكم على هذا؟ الجواب: هذا يقال له: الشغار، ويسميه بعض الناس نكاح البدل، وهو أن يقول شخص لآخر: زوجني بنتك وأزوجك بنتي، أو أختك، أو بنت أخيك، هذا يسمى نكاح البدل، وهو نكاح الشغار.  وقد نهى النبي ﷺ عن نكاح الشغار في عدة أحاديث، نهى الرسول ﷺ عن نكاح الشغار، وهو أن يقول الرجل للآخر: زوجني بنتك، وأزوجك بنتي، أو زوجني أختك، وأزوجك أختي، أو يقول: زوج ابني، وابنك، أو ابني، وخالك، أو ما أشبه ذلك؛ هذا لا يجوز، هذا منكر يجب الحذر منه؛ حتى ولو سموا مهرًا، الواجب الحذر من ذلك، وألا تكون المرأة مهرًا للأخرى؛ بل هذا يخطبها، وهذا يخطب، فمن ناسبه قبل، ومن لا فلا، أما أن يتشارطا البدل هذا يعطيه بنته، وهذا يعطيه بنته، أو أخته، أو بنت أخيه، يعني موليته، هذا لا يجوز، والنكاح فاسد، ولو سمى مهرًا. وذهب بعض العلماء إلى إنه إذا سمى مهرًا بالمثل؛ صح، ولكنه قول مرجوح، والصواب: أنه لا يجوز تعاطي هذا النكاح  مطلقًا، ولو سمي مهرًا. وقد ثبت عند أحمد، وأبي داود، وغيرهما أن شخصين في المدينة تناكحا شغارًا، وقد سميا مهرًا، فرفع ذلك إلى أمير المؤمنين معاوية  فكتب إلى أمير المدينة: أن يفرق بينهما، وقال: هذا هو الشغار الذي نهى عن النبي -عليه الصلاة والسلام- وكانا قد سميا مهرًا. وأما ما يروى في حديث ابن عمر في تفسير الشغار، وأنه هو الذي ليس فيه مهر، فهذا من كلام نافع الراوي عن ابن عمر، وقال جماعة: هو من كلام مالك بن أنس، الراوي أيضًا. وبكل حال فهذا ليس من كلام النبي ﷺ تفسير الشغار بأنه الخلو من المهر ليس من كلام النبي ﷺ ولكنه من كلام بعض الرواة، وكلام الراوي لا يكون حجة، الحجة في كلام النبي -عليه الصلاة والسلام- والنبي نهى عن الشغار، ولم يفسره بعدم المهر؛ بل فسره بأن يقول هذا: زوجتك أختي، أو بنتي، والآخر يقول كذلك: أو يقول: زوجني وأزوجك، هكذا فسره النبي -عليه الصلاة والسلام- هذا يعم ما إذا كان فيه مهر، أو ما إذا خلا من المهر.","link":"https://binbaz.org.sa/fatwas/1252/هل-يجوز-للمراة-ترك-الاحداد-على-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_248.mp3","categories":["العِدَد","قضايا المرأة"]},{"id":5954,"question":"ماذا يلزم المرأة في وقت الحداد على زوجها؟ هل هو ممنوع منها شرب الزعفران بالقهوة، أو التبخر بالعود، أو ما شابه ذلك؟","title":"ما يلزم المرأة وقت الحداد على زوجها","answer":"الجواب: المحادّة جاء في الأحاديث ما ينبغي أن تمتنع منه، المحادّة تطالب بأمور خمسة: الأمر الأول: لزوم بيتها الذي مات زوجها وهي ساكنة فيه، تبقى فيه، وتقيم فيه حتى تنتهي العدة أربعة أشهر، وعشرًا إلا أن تكون حبلى فإنها تخرج عن العدة بوضع الحمل، كما قال تعالى: وَأُولَاتُ الْأَحْمَالِ أَجَلُهُنَّ أَنْ يَضَعْنَ حَمْلَهُنَّ [الطلاق:4] ولها الخروج لحاجة مثل ما عندها خادم، تخرج لحاجتها من إحضار طعام، أو شبه ذلك إذا كان ما عندها من يخدمها، كذلك الخروج لحاجة الطبيب، فهي تمرض، أو البيت انهدم تخرج منه، أو ما عندها مؤنس وتخشى على نفسها؛ فلا بأس بهذا عند الحاجة. الأمر الثاني: ليس لها لبس الجميل من الثياب، لا أصفر، ولا أخضر، ولا غير ذلك، بل تلبس غير الجميل، تلبس من الثياب غير الجميل، سواء كان أسود، أو أخضر، أو أزرق، أو غير ذلك، وأما الجميل فلا تلبسه، والثياب المصبوغة لا تلبس منها ثيابًا جميلة، ولكن تلبس الثياب غير الجميلة، هكذا أمر النبي ﷺ. الثالث: تجنب الحلي من الذهب، والفضة، والماس، والآلئ، وأشباه ذلك، لا تلبس الحلي، والقلائد، والأكسورة، والخواتم، وأشباه ذلك حتى تنتهي. الرابع : الطيب، لا تطيب لا بالبخور، ولا بغيره من الأطياب، إلا إذا حاضت فلها أن تبخر ببعض البخور عند طهرها من الحيض خاصة، وبقية الأطياب لا. الخامس: الاكتحال ليس لها أن تكتحل، ولا ما يكون في معنى الكحل من التجميل للوجه، التجميل الخاص الذي قد يفتن الناس بها، أما التجميل العادي بالماء، والصابون العادي فلا بأس بذلك، لكن الكحل الذي يجمل العينين، وما أشبه الكحل من الأشياء التي تفعلها النساء في الوجه، هذا لا تفعله حال حدادها، هذه الأمور الخمسة ينبغي أن تحفظ للحاجة. أما ما قد يظنه بعض العامة، ويفترونه أيضًا من كونها لا تكلم أحدًا، ومن كونها لا تكلم بالتلفون، ومن كونها لا تغتسل إلا في الأسبوع مرة، ومن كونها لا تمشي في بيتها حافية، ومن كونها تخرج في موضع القمر، وأشباه ذلك من الخرافات، هذه لا أصل لها، تمشي في بيتها حافية، ومنتعلة، تقضي حاجتها في البيت، تطبخ طعامها، وطعام ضيوفها، تمشي في القمر، في السطح، في الحوش، في البيت، كل هذا لا بأس به، تغتسل متى شاءت، تكلم من شاءت كلامًا ليس فيه ريبة، تصافح النساء، تصافح محارمها، لا بأس، أما غير المحارم لا، لكن تصافح محارمها، ونساءها، لا بأس. كذلك تكلم من شاءت، ويكلمها، ويعزيها، ويسألها الحاجة، يسلم عليها بالتلفون، ويسألها عن حاجة، أو تسأله عن حاجة، كل هذا لا بأس به. والزعفران من الطيب لا يستعمل الزعفران، لا يستعمل لا في الثياب، ولا في القهوة، الزعفران نوع من الطيب، والخطبة لا تخطب، وهي في العدة، ولكن لا بأس بالتعريض، أما الخطبة فلان يريدك لا، لكن التعريض مثل: مثلك يرغب فيها أنتِ عزيزة علينا، وما أشبه ذلك، لكن ليس بالتصريح. السؤال: والحناء جزاك الله خيرًا؟ الجواب: الحناء لا تستعمل؛ لأن فيها زينة، وجمال.","link":"https://binbaz.org.sa/fatwas/1329/ما-يلزم-المراة-وقت-الحداد-على-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_298.mp3","categories":["العِدَد","قضايا المرأة"]},{"id":6456,"question":"إذا كان في رجل جلست عنده امرأته ثلاث سنوات، ولم يأتها حيث أنها تكرهه، وبعد مدة طلب والدها ورقة طلاقها، وأعطاه الصداق الذي دفعه، هل عليها عدة بعد الطلاق، علمًا أنها جالسة عند أبوها مدة ثلاث سنوات، ولم يأتها، ولم تحمل، والغرض من ذلك هل عليها عدة؟","title":"عدة المخالعة التي لم يدخل بها زوجها","answer":"الجواب: إذا خالعته بأن كرهته، ولم تستطع البقاء معه، ثم اتفقا على المخالعة، وأعطوه مهره، أو بعض مهره، أو غير ذلك، واتفقا على هذا، وطلقها على المال؛ فإن الصحيح أنه يكفيها حيضة واحدة، لا تلزمها العدة كاملة ثلاث.  المخلوعة ثبت في الحديث أنه -عليه الصلاة والسلام- أذن لها في حيضة واحدة، واكتفى بالحيضة؛ لأنها كالمشترية لنفسها، كالأمة، فلنفسها حيضة واحدة براءة للرحم؛ حتى يعلم أن الرحم بريء ما فيه حمل، ويكفي. وإن اعتدت بثلاث حيض خروجًا من خلاف العلماء؛ كان ذلك أكمل، حتى تتزوج بعد ذلك، وإلا فحيضة واحدة تكفي على الصحيح بالمخالعة، خاصة التي خلعت بالمال، طلقها زوجها على المال بسبب سوء الحال بينهما، فطلقها على مال، فإنها تعتد بحيضة إلا أن تكون حبلى؛ فعدتها وضع الحمل، كما هو معلوم.","link":"https://binbaz.org.sa/fatwas/2175/عدة-المخالعة-التي-لم-يدخل-بها-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_801.mp3","categories":["العِدَد","قضايا المرأة"]},{"id":6517,"question":"وهل عدة المملوكة أم الولد مثل عدة الحرة، أم ماذا ؟","title":"عدة المملوكة وأم الولد","answer":"الجواب: لا، المملوكة لا، الحرة عليها أن تعتد أربعة أشهر وعشرًا، إذا كانت زوجة عليها أربعة أشهر وعشرًا، وإن كانت حبلى حتى تضع، أما أم الولد حين مات عنها سيدها عليها أن تستبرئ بحيضة، إذا كان يطأها في حياته، ما هي مثل الزوجة، أم الولد تعتد بحيضة فقط على الصحيح، وليس لها حكم الزوجات. إذا كان الإنسان تسرى أمته، واستولدها حتى مات عنها، فليس عليها عدة الزوجات، ولكن عليها أن تستبرئ بحيضة، ثم تتزوج بعد ذلك كالإماء، كسائر الإماء المملوكات، أما الزوجة المملوكة فعليها العدة، لكن نصف عدة الحرة إذا كان عنده زوجتان، حرة ومملوكة، فالحرة عليها أربعة أشهر وعشرًا، والمملوكة شهران وخمسة أيام.","link":"https://binbaz.org.sa/fatwas/2249/عدة-المملوكة-وام-الولد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_870.mp3","categories":["العِدَد","قضايا المرأة"]},{"id":6650,"question":"ما حكم الولائم التي توضع بمناسبة خروج الأرملة من الحداد، وهذه ظاهرة في مجتمعنا؟ وهل من تعظيم حق الزوج المتوفي؟","title":"حكم الوليمة التي توضع بمناسبة خروج الأرملة من الحداد","answer":"الجواب: لا نعلم بها بأسًا، تقيم في بيتها المدة أربعة أشهر وعشرًا، أو أكثر من ذلك إن كانت حاملًا، وقد يعتني بها أقاربها، ويعزمونها، ويكرمونها، لا نعلم به بأسًا مثل: إكرام المسافر، وإكرام الذي خرج من السجن، وأشباه ذلك.","link":"https://binbaz.org.sa/fatwas/2532/حكم-الوليمة-التي-توضع-بمناسبة-خروج-الارملة-من-الحداد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1027.mp3","categories":["العِدَد","قضايا المرأة"]},{"id":6655,"question":"ما حكم الولائم التي توضع بمناسبة خروج الأرملة من الحداد، وهذه ظاهرة في مجتمعنا؟ وهل من تعظيم حق الزوج المتوفي؟","title":"حكم الوليمة التي توضع بمناسبة خروج الأرملة من الحداد","answer":"الجواب: لا نعلم بها بأسًا، تقيم في بيتها المدة أربعة أشهر وعشرًا، أو أكثر من ذلك إن كانت حاملًا، وقد يعتني بها أقاربها، ويعزمونها، ويكرمونها، لا نعلم به بأسًا مثل: إكرام المسافر، وإكرام الذي خرج من السجن، وأشباه ذلك.","link":"https://binbaz.org.sa/fatwas/2532/حكم-الوليمة-التي-توضع-بمناسبة-خروج-الارملة-من-الحداد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1027.mp3","categories":["العِدَد","قضايا المرأة"]},{"id":6998,"question":"لي أخت خارج الرياض تبعد حوالي 800 كيلو، وتوفي زوجها الأسبوع الماضي ووالدها، وجميع محارمها بالرياض، ووالد المتوفي شيخ كبير، ولا يملك من نفسه شيئًا، هل يجوز لي أن أحضرها إلى الرياض في مدة العدة؟ وهل للنفاس تأثير في العدة؟","title":"حكم انتقال المرأة من بيتها أثناء العدة للضرورة","answer":"الجواب: إذا كانت على ما ذكرت ما عندها أحد يصونها، ويحميها؛ تنقل إلى الرياض هي والشايب الذي معها، أما إذا كان عندها من يصونها، عندها يعني إخوة لها، أو زوج أمها، أو غيرهم من الناس يصونونها؛ تبقى في محلها؛ حتى تكمل عدتها، أما إذا كانت ما عندها أحد؛ لا تخلى في محل فيه خطر؛ تنقل. والنفاس ما له أثر، إذا كان مات وهي في النفاس؛ تعتد أربعة أشهر وعشرًا، أما إذا كان مات قبل أن تلد، ثم ولدت بعد موته، ولو بيوم، أو ساعة، فتخرج من العدة بالولادة وَأُولَاتُ الْأَحْمَالِ أَجَلُهُنَّ أَنْ يَضَعْنَ حَمْلَهُنَّ [الطلاق:4] متى ولدت، ولو بعد موته بساعة؛ انتهت العدة، لكن إذا مات، وهي في النفاس لا، لا بد من أربعة أشهر، وعشرًا.","link":"https://binbaz.org.sa/fatwas/2900/حكم-انتقال-المراة-من-بيتها-اثناء-العدة-للضرورة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1348.mp3","categories":["العِدَد","قضايا المرأة"]},{"id":7053,"question":"امرأة محاداة تسأل: هل يجوز لها الرد على من يقرع الباب، وكذا التلفون ومشاهدة التلفاز؟","title":"الأحكام المتعلقة بالمرأة التي توفي عنها زوجها","answer":"الجواب:\n\nنعم نعم، المحاداة لها رد الكلام باللسان على الباب، والكلام على الهاتف مع من يكلم لا حرج عليها في ذلك، مثل غيرها من النساء، إذا كان الكلام ليس فيه ريبة؛ ترد عليهم وتكلمهم، إذا ضرب الباب؛ من؟ إذا دق الهاتف؛ من؟ تسأل ماذا يريد إذا كانت تعرفه سألته عن حاله وعن أولاده وما أشبه ذلك، فالمحاداة تراعي أمورًا خمسة -المتوفى عنها يعني:\n\nالأمر الأول: تبقى في بيت زوجها الذي مات، وهي ساكنة فيه، لأن الرسول ﷺ أمر ببقائها في البيت إلا من علة، مثل البيت يطيح، أو مستأجر، وأبوا أن يؤجرونه، أو ما عندها أحد يؤنسها، تخشى على نفسها تذهب إلى أهلها، أما ما دام البيت ... من يؤنسها، وهو صالح؛ تبقى في البيت حتى تنتهي من العدة، ولها الخروج من حاجة، مثل الخروج للطبيب، والخروج لحاجة تأتي بها من السوق، وما أشبه ذلك من الحاجات التي تخرج لها.\n\nالأمر الثاني: لا تلبس الملابس الجميلة، تلبس ملابس ما هي جميلة، لأن الرسول ﷺ نهى عن ثوب العصفر، وعن الملابس الجميلة، تلبس ملابس غير جميلة، أسود أو أخضر أو أزرق أو نحو ذلك، ما هو بجميل.\n\nالأمر الثالث: لا تأتي الطيب، الأطياب لا تطيب إلا إذا كانت تحيض -شابة تحيض- إذا طهرت من الحيض لها أن تستعمل بعض البخور.\n\nالرابع : الحلي، لا تلبس الحلي، لا أسورة، ولا قلائد، ولا خواتم، تترك الحلي؛ لأن الرسول ﷺ نهى عنها.\n\nالخامس: لا تكتحل، ولا تتحنا -لا تضع الحناء- لأنه جمال، فلا تكحل عينها، ولا تتحنا في يديها، ونحو ذلك؛ لأنه من الجمال، وهكذا المكياج ونحوه، تترك هذا الشيء.\n\nهذا خمسة أمور تتجنبها المحاداة.\n\nوما سواها مثل الناس تسمع الإذاعة، مثل إذاعة القرآن المفيدة للناس، إذاعة القرآن، نور على الدرب، ينبغي لكل واحد أن يسمع إذاعة القرآن، ونور على الدرب؛ لأنه مفيد، أما التلفاز فيه خطر، تجنبه أولى وأسلم، لكن من سمع الشيء الطيب، يعني إذاعة القرآن سمعها، أو كندوة مفيدة، أو سمع أخبارًا مهمة؛ فلا يضره، لكن يغلق ما عنده من الأغاني، والملاهي، والمسلسلات الضارة، لا يسمعها، ولا ينظر إليها يغلقها.","link":"https://binbaz.org.sa/fatwas/3020/الاحكام-المتعلقة-بالمراة-التي-توفي-عنها-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1426.mp3","categories":["العِدَد","قضايا المرأة"]},{"id":7062,"question":"ما هي الأشياء المحظورة على المرأة التي مات زوجها في فترة العدة التي هي أربعة أشهر وعشرًا؟","title":"الأحكام المتعلقة بالمرأة المتوفى عنها زوجها","answer":"الجواب:\n\nعليها أن تراعي خمسة أمور، المحادة عليها أن تراعي خمسة أمور في زمن العدة، وهي أربعة أشهر وعشرًا إن كانت غير حامل، أما إن كانت حاملًا فإنها تعتد جميع مدة الحمل حتى تضع الحمل، ولو زاد على أربعة أشهر وعشرًا؛ لأن الله يقول: وَأُولَاتُ الْأَحْمَالِ أَجَلُهُنَّ أَنْ يَضَعْنَ حَمْلَهُنَّ [الطلاق:4] تراعي خمسة أمور:\n\nالأمر الأول: بقاؤها في البيت الذي مات زوجها وهي ساكنة فيه، تبقى فيه حتى تكمل العدة؛ لأن الرسول أمر بعض النساء اللاتي توفي أزواجهن بالمكث في البيت حتى تنتهي، حتى يبلغ الكتاب أجله، لكن لها الخروج لحاجتها، للسوق تشتري من السوق حاجاتها، .. العلاج، تخرج إلى الدرس إن كانت مدرسة، أو طالبة، لحاجة من أهم الحاجات.\n\nالأمر الثاني: تجنب الملابس الجميلة، لا تلبس الملابس الجميلة -المصبوغات الجميلة- تلبس ملابس ما هي جميلة، سوداء أو خضراء أو زرقاء أو غير ذلك، لكن ما هي جميلة ما تلفت الأنظار.\n\nالثالث: عدم الطيب، لا تستعمل الطيب، لا البخور ولا غيره إلا إذا كانت تحيض؛ فإنها عند الطهر لا مانع أن تستعمل شيئًا من القسط، أو البخور على إثر طهرها؛ لأنه جاء النص بذلك.\n\nالرابع: عدم الحلي من الذهب والفضة والماس وأشباهه، لا تلبس الحلي، لا القلائد، ولا الأسورة، ولا نحوها كل ما يسمى حليًا.\n\nالخامس: عدم الكحل ونحوه، كالحناء والمكياج ونحوه، كل هذا تجتنب هذه الأشياء حتى تكمل العدة.\n\nأما كونها تكلم الناس، تكلم من يسلم عليها، أو يكلمها، أو تكلم بالهاتف؛ لا بأس بالتلفون، أو تسلم على أقاربها من النساء اللاتي يزرنها، أو تصافح النساء، أو محارمها كأخيها وعمها أو أقاربها غير المحارم إذا سلموا عليها، أو جيرانها، كل هذا لا بأس به مع مراعاة ما أوجب الله من الحشمة والحجاب وعدم الخلوة، إذا كان الذي سلم عليها غير محرم؛ فلا تكون خلوة، ولا يكون الكشف لما حرم الله، بل تكون محتجبة في وجهها وغيره، وتكون بعيدة عن الخلوة، عندها أحد، فلا تخلو بغير محرم.\n\nالسؤال: تلبس الملابس البيضاء لا بأس؟\n\nالجواب: تلبس ملابس ما فيها جمال، ما فيها فتنة، والبيضاء إذا كانت مخططة ما فيها فتنة، ولا تشبه بالرجال؛ لا بأس، ولها أن تعمل في بيتها مثل .. في بيتها، تطبخ، تكنس بيتها، تصعد إلى السطح، إلى القمر في الليل، في الحوش في الليل، بعض العامة يقولون: لا تخرج للقمر، هذا من جهلهم وغلطهم، لا بأس أن تمشي في القمر في الليل، في سطحها، أو في حوشها، ولا بأس أن تمشي حافية منتعلة، أو حافية لا بأس، لا بأس أن تذهب إلى حديقتها في البيت، المقصود: أنها تعمل كل شيء ما يعمله النساء، ماعدا الخمس هذه الأشياء التي بينت.\n\nالسؤال: إذا لم يكن لها محرم في البيت الذي كانت تسكنه في حياة زوجها؟\n\nالجواب: إذا كان عندها من يؤنسها: أمها، أو خالتها، أو بناتها؛ كفى، والحمد لله.","link":"https://binbaz.org.sa/fatwas/3064/الاحكام-المتعلقة-بالمراة-المتوفى-عنها-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1452.mp3","categories":["العِدَد","قضايا المرأة"]},{"id":7966,"question":"سماحة الشيخ! نبدأ أولاً برسالة أم راشد التي تسأل عن ملابس الحداد، تقول في رسالتها: إلى أصحاب الفضيلة الكرام! أطرح عليكم بعض الأسئلة وأرجو أن أجد الجواب الصحيح: هل للمرأة لبس معين في فترة الحداد كالأسود أو الأخضر مثلاً؟","title":"المشروع في لبس الحداد للمرأة","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: عليها أن تلبس اللباس الذي ما فيه جمال يعني: ليس بجميل حتى لا يفتن الرجال ولا يكون عرضة لفتنتها مثل الأسود الذي ليس بجميل والأخضر الذي ليس بجميل، والأزرق الذي ليس بجميل، لأن الرسول ﷺ قال: ولا تلبس إلا ثوب عصب.\nفالحاصل أنها تلبس اللباس الذي ليس فيه لفت النظر ليس فيه جمال واضح، إما أزرق الذي ليس بجميل، أو أسود ليس بجميل، أو أخضر ليس بجميل نحو ذلك، أو أحمر ليس بجميل.\nالمقدم: إذاً سماحة الشيخ يقال لها: أن تتجنب مثلاً بعض الملابس التي كانت تلبسها على زمانه.\nالشيخ: نعم الذي فيها جمال تتجنبها، تلبس ثياب ما فيها جمال ولا لفت نظر، أسود أو أخضر أو أزرق لكن ليس بجميل، كما تتجنب الطيب والحلي، الحلي من الذهب والفضة وغير ذلك، والكحل، كل هذا ممنوع من المحادة.","link":"https://binbaz.org.sa/fatwas/5480/المشروع-في-لبس-الحداد-للمراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_069/06901.mp3","categories":["العِدَد","قضايا المرأة"]},{"id":8289,"question":"سؤالها الآخر تقول: المعروف بالنسبة للنساء في العراق إذا شخص مات تلبس عليه ثوباً أسوداً لمدة سنة كاملة، وإذا لم تلبس يقولون عليها: بأنها فرحت بموت ذلك الشخص، وكلام الناس لا ينتهي ولا يدعون الناس في حالهم، وأنا علمت أن هذا لا يجوز، فماذا تقولون لو تكرمتم في هذا عسى أن يستفيد الناس ويعملوا؟","title":"لبس المعتدة للثوب الأسود سنة كاملة","answer":"الجواب: هذا الذي ذكرت هو مثلما ذكرت لا يجوز، كونها تحاد سنة كاملة في ثوب أسود هذا لا أصل له، هذا من عمل الجاهلية، كانت الجاهلية تحاد المرأة فيهم إذا مات زوجها سنة كاملة، فأبطل ذلك الإسلام وأخبر النبي ﷺ أن هذا من سنة الجاهلية، وأوجب الله على المرأة بدلاً من ذلك أربعة أشهر وعشراً إذا كانت غير حامل، أما إن كانت حبلى فإنها تنتهي من العدة بوضع الحمل، ولو بعد موت زوجها بساعات أو أيام، أما أن تعتد سنة أو في لباس خاص أسود فقط هذا لا أصل له، بل هو من عمل الجاهلية، فلها أن تلبس الأسود والأصفر والأخضر والأزرق، لكن تكون ملابس غير جميلة تكون عادية لا تلفت النظر؛ لأنه ﷺ نهى المحادة أن تلبس شيئاً من الثياب الجميلة المصبوغة، قال: إلا ثوب عصب، فقال أهل العلم: إن ثوب العصب ليس فيه جمال، فالمشروع لها أن تلبس ثياباً ليس فيها جمال؛ لأنها تعرضها للفتنة، تكون ملابسها ملابس عادية لا تلفت النظر، هذا هو المشروع للمحادة، كما أنه يجب عليها أن تتجنب الطيب مدة العدة، وكذلك الحلية من الذهب والفضة ونحوها كاللؤلؤ والماس وأشباه ذلك مدة العدة، وهكذا تجتنب الكحل في عينيها والحناء كل هذا مما تمنع منه الحادة.\nوالحاصل أن الحادة تؤمر بخمسة أمور:\nالأمر الأول: أنها تبقى في بيت زوجها الذي مات وهي ساكنة فيه حتى تنتهي من العدة؛ لقول النبي ﷺ لمحادة: امكثي في بيتكك حتى يبلغ الكتاب أجله هكذا قال عليه الصلاة والسلام: امكثي في بيتك حتى يبلغ الكتاب أجله، لكن لا بأس أن تخرج لحاجة، لحاجة من السوق تشتريها من طعام وغيره، أو إلى الطبيب لحاجتها إلى الطبيب لا بأس بهذا، أما خروجها لغير ذلك كالزيارات ونحو ذلك فلا، بل تبقى في بيتها، ولا تسافر أيضاً لا لحج ولا غيره حتى تنتهي من عدتها.\nالأمر الثاني: أنها لا تلبس الملابس الجميلة، بل تلبس ملابس عادية ليس فيها جمال يلفت النظر، سواءً كانت سوداء أو خضراء أو زرقاء أو حمراء أو غير ذلك.\nالثالث: عدم الحلي من الذهب والفضة ونحوها كاللؤلؤ والماس وأشباه ذلك، لا تلبس هذا؛ لأن الرسول نهى عن ذلك عليه الصلاة والسلام.\nالرابع: عدم الطيب؛ لأن الرسول ﷺ قال: لا تمس طيباً يعني: المحادة، فلا تمس الطيب سواءً كان من البخور أو غير ذلك دهن العود والورد وأشباه ذلك، إلا إذا كانت تحيض كالشابة فإنها لها أن تتبخر عند طهرها من حيضها كما أمر بهذا النبي ﷺ وأذن فيه.\nوالخامس: الكحل؛ ليس لها أن تكتحل ولا أن تتعاطى الحناء؛ لأنه جمال، فتجتنب ذلك وما أشبهه.\nهذه الأمور الخمسة هي التي يلزم المحادة أن تراعيها وتعتني بها، أما ما سوى ذلك فهي من جنس بقية النساء، لها أن تغتسل متى شاءت تتروش متى شاءت، تغير ثيابها متى شاءت، تستعمل الدواء فيما عندها من مرض في عينيها أو غيره من أدوية، تطبخ حاجتها في البيت، تخدم بيتها، تصعد إلى السطح في الليل إلى القمر ...... القمر، تخرج إلى الحوش وإلى الحديقة في بيتها، كل هذا لا بأس به، تكلم من شاءت من يكلمها من جيرانها أو من غير جيرانها أو من طريق الهاتف كالتلفون أو غيره، كل هذا لا بأس به إذا كان كلاماً ليس فيه ريبة ولا منكر، فهي من جنس بقية النساء. نعم.","link":"https://binbaz.org.sa/fatwas/6102/لبس-المعتدة-للثوب-الاسود-سنة-كاملة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_107/10705.mp3","categories":["البدع والمحدثات","قضايا المرأة","العِدَد"]},{"id":8641,"question":"الأخت السائلة في ختام رسالتها تقول: كيف تحد المرأة التي يموت زوجها، وهل تمنع من الأعمال المنزلية، وتمنع من وضع الزيت في شعرها وما ماثل ذلك؟","title":"أحكام المحادة التي توفي عنها زوجها","answer":"الجواب: المحدة التي مات عنها زوجها تراعي أموراً خمسة:\nالأمر الأول: أن تبقى في البيت، الذي مات زوجها وهي ساكنة فيه إذا كان صالحاً؛ لقول النبي ﷺ للمحادة: امكثي في بيتك حتى يبلغ الكتاب أجله فإذا كان البيت صالحاً بقيت فيه، أما إن كان خراب أو ما عندها أحد يؤنسها وتستوحش فلا حرج عليها في الخروج، أو كان مستأجراً انتهت مدته أو ما أشبه ذلك، لكن لا بأس بخروجها للحاجة، مثل خروجها للطبيب، خروجها لشراء بعض حاجاتها من السوق ما عندها أحد يشتريها لها لا بأس بهذا.\nالأمر الثاني: أن تلبس ملابس ما هي بجميلة، ملابس ما تلفت النظر، أما الملابس الجميلة تجتنبها، ولكن تلبس ملابس غير جميلة، سوداء، أو زرقاء، أو خضراء، أو حمراء ما فيه بأس، أما قول بعض الناس: أنها تلزم السواد هذا غلط لا ما هو بلازم السواد، تلبس ما تيسر من أسود وغيره أزرق وأخضر وأحمر وغير ذلك، لكن تكون ملابس غير جميلة غير لافتة للنظر.\nالأمر الثالث: عدم الطيب لا بالبخور ولا بالأطياب الأخرى إلا إذا كانت تحيض فإذا طهرت تستعمل البخور عند طهرها كما جاء في الحديث الشريف.\nالرابع: عدم الحلي من القلائد والأسورة والخواتم وأشباه ذلك من الذهب والفضة أو الماس أو غير ذلك تجتنب الحلي كلها مدة الإحداد.\nالخامس: الكحل، كحل العينين والحناء في اليد أو في الرجل أو في الرأس، تتجنب الحناء والكحل والمكياج وأشباه ذلك حتى تنتهي من عدتها، هذه أمور خمسة تراعيها.. المحادة وما سواها مثل بقية النساء، لها أن تكلم من شاءت من الرجال في التلفون أو غيره من دون ريبة، لها تكشف رأسها في بيتها عند نسائها وعند أولادها.. لها تخدم في بيتها، لها تصعد إلى السطح وتخرج إلى الحديقة في الفضاء أو في النهار لا بأس لها تتروش متى شاءت في الجمعة وغير الجمعة، لها تغير ثيابها متى شاءت، كل هذه أمور -بحمد الله- واسعة، كثير من العامة يشددون على أنفسهم بغير حجة، بالجهل فينبغي للنساء أن يعرفن هذه الأمور وأن يكن على بصيرة. نعم.\nالمقدم: جزاكم الله خير وبارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6785/احكام-المحادة-التي-توفي-عنها-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_212/21212.mp3","categories":["العِدَد"]},{"id":8644,"question":"الأخت السائلة في ختام رسالتها تقول: كيف تحد المرأة التي يموت زوجها، وهل تمنع من الأعمال المنزلية، وتمنع من وضع الزيت في شعرها وما ماثل ذلك؟","title":"أحكام المحادة التي توفي عنها زوجها","answer":"الجواب: المحدة التي مات عنها زوجها تراعي أموراً خمسة:\nالأمر الأول: أن تبقى في البيت، الذي مات زوجها وهي ساكنة فيه إذا كان صالحاً؛ لقول النبي ﷺ للمحادة: امكثي في بيتك حتى يبلغ الكتاب أجله فإذا كان البيت صالحاً بقيت فيه، أما إن كان خراب أو ما عندها أحد يؤنسها وتستوحش فلا حرج عليها في الخروج، أو كان مستأجراً انتهت مدته أو ما أشبه ذلك، لكن لا بأس بخروجها للحاجة، مثل خروجها للطبيب، خروجها لشراء بعض حاجاتها من السوق ما عندها أحد يشتريها لها لا بأس بهذا.\nالأمر الثاني: أن تلبس ملابس ما هي بجميلة، ملابس ما تلفت النظر، أما الملابس الجميلة تجتنبها، ولكن تلبس ملابس غير جميلة، سوداء، أو زرقاء، أو خضراء، أو حمراء ما فيه بأس، أما قول بعض الناس: أنها تلزم السواد هذا غلط لا ما هو بلازم السواد، تلبس ما تيسر من أسود وغيره أزرق وأخضر وأحمر وغير ذلك، لكن تكون ملابس غير جميلة غير لافتة للنظر.\nالأمر الثالث: عدم الطيب لا بالبخور ولا بالأطياب الأخرى إلا إذا كانت تحيض فإذا طهرت تستعمل البخور عند طهرها كما جاء في الحديث الشريف.\nالرابع: عدم الحلي من القلائد والأسورة والخواتم وأشباه ذلك من الذهب والفضة أو الماس أو غير ذلك تجتنب الحلي كلها مدة الإحداد.\nالخامس: الكحل، كحل العينين والحناء في اليد أو في الرجل أو في الرأس، تتجنب الحناء والكحل والمكياج وأشباه ذلك حتى تنتهي من عدتها، هذه أمور خمسة تراعيها.. المحادة وما سواها مثل بقية النساء، لها أن تكلم من شاءت من الرجال في التلفون أو غيره من دون ريبة، لها تكشف رأسها في بيتها عند نسائها وعند أولادها.. لها تخدم في بيتها، لها تصعد إلى السطح وتخرج إلى الحديقة في الفضاء أو في النهار لا بأس لها تتروش متى شاءت في الجمعة وغير الجمعة، لها تغير ثيابها متى شاءت، كل هذه أمور -بحمد الله- واسعة، كثير من العامة يشددون على أنفسهم بغير حجة، بالجهل فينبغي للنساء أن يعرفن هذه الأمور وأن يكن على بصيرة. نعم.\nالمقدم: جزاكم الله خير وبارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6785/احكام-المحادة-التي-توفي-عنها-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_212/21212.mp3","categories":["العِدَد"]},{"id":8871,"question":"أخونا له سؤال آخر يقول: هل عدة المرأة المتوفى عنها زوجها يقصد منها التأكد من الحمل أو عدمه فقط، وإذا كان الجواب كذلك فما قولكم إذا أمكن التعرف على وجود الحمل أو عدمه في أقل من مدة العدة بواسطة الطب مثلاً؟","title":"العدة وبيان الحكمة منها","answer":"الجواب: العدة مدة شرعها الله عز وجل بعد الطلاق وبعد الوفاة لحكم كثير، لحكم كثيرة ليست مجرد براءة الرحم بل لحكم كثيرة؛ منها براءة الرحم لئلا تجتمع المياه في الرحم تشتبه الأنساب، ومنها احترام الميت وأن يبقى له حرمة في نفس الزوجة، وصيانة لها عن التطلع للرجال من حين الوفاة، كما جعل الله للمطلق كذلك عدة لزوجته معروفة، ثلاث حيض إن كانت تحيض، أو ثلاثة أشهر إن كانت لا تحيض، فالمقصود أن ليست الحكمة فقط مجرد براءة الرحم، بل هي من المقصود وهناك حكم أخرى وأسرار أخرى غير مجرد براءة الرحم، وقد نبه على ذلك العلامة ابن القيم رحمه الله في كتابه إعلام الموقعين، ونبه غيره على ذلك رحمة الله عليهم من أهل العلم.\nفالمقصود أنه ليست الحكمة مجرد العلم ببراءة الرحم، لا، ولهذا يجب على المرأة أن تعتد مطلقاً ولو كان ما دخل بها، إذا مات عنها حتى ولو ما دخل بها إذا عقد عليها ومات عنها قبل أن يدخل بها فإن الأدلة عامة تعمها وتعم غيرها، فعليها أن تعتد أربعة أشهر وعشراً، وإن كان معلوماً أنه ليس في رحمها شيء، فإن التي لم يدخل بها ليس في رحمها شيء من الزوج، وهكذا لو كانت صغيرة عقد عليها وهي صغيرة بنت خمس سنين أو تسع سنين ثم مات عنها وقد علم أنه لم يدخل بها.\nفالحاصل أن العدة عامة للصغيرة والكبيرة والمدخول بها وغير المدخول إذا كانت للوفاة، أما التفصيل فهو في الطلاق في هذا في عدة الحيض، إذا كانت غير مدخول بها لا عدة عليها في الطلاق.\nأما الوفاة فإن العدة ثابتة وواجبة مطلقاً ولو لم يدخل بها ولو علم براءة الرحم. نعم.","link":"https://binbaz.org.sa/fatwas/7027/العدة-وبيان-الحكمة-منها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_138/13810.mp3","categories":["العِدَد"]},{"id":8887,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من مكة المكرمة وباعثها أخونا أبو ياسر صالح علي عثمان ، أخونا له مجموعة من الأسئلة يقول في سؤاله الأول: هل للمبتوتة والحامل والمتوفى عنها زوجها سكن ونفقة في مدة العدة أم لا؟","title":"العدة .. أنواعها وأحكامها","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فإن المعتدات قسمان:\nقسم للزوج رجعة إليها من دون عقد جديد، فهذه لها النفقة مدة العدة وهي التي طلقت طلقة واحدة أو طلقتين وقد دخل بها، يعني: خلا بها أو جامعها، فهذه لها النفقة بالعرف، يعني بالمعروف حتى تنتهي عدتها.\nأما المبتوتة التي طلقها آخر الثلاث ليس له رجعة إليها، وهكذا المفسوخة من زوجها لمسوغ شرعي، والمخلوعة من زوجها لمسوغ شرعي هذه لا نفقة لها؛ لأنها بائن، ليس له رجعة إليها إلا بعقد جديد إذا كان الخلع والفسخ لم يستكمل الثلاث، أما المتوفى عنها فليس لها نفقة؛ لأن فرقتها في حكم البينونة فليس لها نفقة بل ينفق عليها من مالها من الإرث أو غيره، أما الحامل فلها نفقة من أجل الحمل ولو كانت بائنة، لها النفقة المعتادة المعروفة من أجل الحمل، لقوله : وَإِنْ كُنَّ أُولاتِ حَمْلٍ فَأَنْفِقُوا عَلَيْهِنَّ حَتَّى يَضَعْنَ حَمْلَهُنَّ فَإِنْ أَرْضَعْنَ لَكُمْ فَآتُوهُنَّ أُجُورَهُنَّ [الطلاق:6].\nفالحامل ينفق عليها من أجل الحمل، وإذا وضعت ينفق عليها من أجل الرضاع، والأمر في ذلك يرجع إلى المصالحة بين المرأة والزوج أو أهل الزوج إن كان متوفى؛ إن كان مات بعد ذلك.\nالمقصود أن النفقة من أجل الحمل وبعد الوضع من أجل الرضاع، فإن تنازعوا قدرها الحاكم في بلدهم، يرجع فيها إلى المحكمة في بلد الحامل في حال الحمل وفي حال الرضاع إلا أن يصطلحوا، تصطلح المرأة مع الزوج إن كان موجوداً أو مع أهله إن كان مفقوداً. نعم.\nالمقدم: بارك الله فيكم. قولكم سماحة الشيخ: النفقة بالمعروف. ربما تحتاج هذه اللفظة إلى شيء من التفصيل؟\nالشيخ: لقوله : وَعَلَى الْمَوْلُودِ لَهُ رِزْقُهُنَّ وَكِسْوَتُهُنَّ بِالْمَعْرُوفِ [البقرة:233] ، يعني بالمتعارف بين الناس؛ لأنه يختلف، عرف الناس مثلاً في المغرب غير عرف الناس في المشرق، عرف الناس مثلاً في الجزائر غير عرفهم في الرياض، عرفهم في الرياض غير عرفهم في دمشق.. وهكذا، يرجع فيها إلى المتعارف بين الناس في بلادهم، والحاكم يقدرها يعني القاضي عند التنازع وإذا اصطلحوا ولم يحتاجوا إلى القاضي فالحمد لله.","link":"https://binbaz.org.sa/fatwas/7042/العدة-انواعها-واحكامها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_140/14001.mp3","categories":["العِدَد"]},{"id":9001,"question":"هذه رسالة من المواطنة من العراق: خمرية سلمان بني العراق -بغداد- الدورة، مدينة المهدي، تقول الأخت: خمرية في رسالتها:بسم الله الرحمن الرحيم. تحية طيبة. السلام عليكم ورحمة الله وبركاته.إنني امرأة ترملت بعد وفاة زوجي رحمة الله عليه، مما جعلني ألتزم العدة عليه، وبعد التزامي بالعدة وضعت أمامي عدة أسئلة حول العدة، حسب أقوال الجيران والأقارب هي: عدم مشاهدة أي شخص حتى لو كان هذا الشخص طفلاً يبلغ من العمر سنة واحدة، كذلك عدم مشاهدة أي شخص حتى لو كان مشاهدة عفوية أي: من خلف النافذة أو سياج الحديقة، وحسب قولهم أيضاً: أنه عندما أشاهد أي شخص من الأشخاص، يجب علي أن أعيد العدة مرة أخرى، أفيدونا أفادكم الله؟","title":"ما يجب على المحادة وما يباح لها","answer":"الجواب: هذه أقوال لا أساس لها من الصحة، هذه أقوال باطلة من كيس العامة ومن كذبهم وعدم بصيرتهم، فهم يكذبون أشياء ويقولونها ليس عليها حجة ولا برهان، فكل هذا لا أصل له، فالمحادة والمعتدة لها أن تنظر الأطفال وغير الأطفال، تنظر إلى الرجال من دون خلوة ومن دون شهوة، فإذا مر بها الرجل ورأته من النافذة أو في الطريق أو رأت الصبي ولو ابن سبع أو ابن عشر أو أكثر من ذلك كل هذا لا حرج فيه، وليس في هذا بأس، وإنما هذا من كلام العامة الذي لا أصل له، فللمرأة المحادة أن تنظر إلى الرجال نظراً ليس فيه خلوة وليس فيه ريبة ولا شهوة، النظر العام من الطرق ومن النوافذ ونظر الصبيان وكذلك لها أن تسلم على جيرانها وعلى أقاربها من دون مصافحة، تسلم عليهم إذا سلموا عليها، من طريق الهاتف أو من طريق الباب، من دون خلوة لا بأس بذلك، ومن دون ريبة فلها أن تسلم على أقاربها وعلى غير أقاربها، لكن إذا كانوا غير محارم ليس لها أن تصافح أحداً ليس محرماً، وليس لها أن تكشف له بل تكلمهم من رواء حجاب، تكون مستورة الوجه والبدن، تكلم من كلمها تسلم من سلم عليها، من أقارب وجيران وغيرهم، ترد على الهاتف إذا كلم بالهاتف ترد على الهاتف، كل هذا لا حرج فيه والحمد لله.\nوإنما المطلوب منها خمسة أمور:\nالأمر الأول: أن تبقى في البيت الذي مات زوجها وهي ساكناً فيه، إذا كان صالحاً للبقاء فيه تبقى فيه حتى تكمل العدة، أما إن كان خارباً أو أهله طلبوه لأنه مستأجر طلبه أهله تمت المدة، أو ما عندها أحد يؤنسها تستوحش، فلا بأس أن تنتقل إذا لم يتيسر لها من يؤنسها.\nثانياً: ليس لها أن تلبس الملابس الجميلة، تلبس ملابس ما هي بجميلة، لا تلفت النظر كالأسود والأزرق والأخضر ونحوها، هذا هو الواجب عليها، أما الملابس الجميلة تتركها.\nالثالث: تجتنب الطيب الأطياب، من البخور...... العود والعنبر وغيرها من أنواع الأطياب، تجتنب الطيب حتى تنتهي عدتها، إلا إذا طهرت من حيضها إذا كانت تحيض، فلا بأس أن تتعاطى البخور، وقت الطهر من حيضها.\nالرابع: تجنب الحلي من الذهب والفضة والماس، لا تلبس هذه الحلي حتى تنتهي من عدتها.\nالخامس: عدم الكحل، والحناء والمكياج، هذه الزينة تجتنبها أيضاً حتى تنتهي من عدتها، هذه خمسة أمور هي المطلوبة من المحادة، أما ما سواها فهي مثل الناس تكلم من شاءت تنظر إلى الرجال نظراً لا حرج فيه كما تقدم، تصافح محارمها كإخوانها وأخوالها وأعمامها، تكلم من طريق الهاتف من كلمها، إلى غير هذا مما يفعله النساء الأخريات، ما عدا الخمسة التي بينا، والله ولي التوفيق.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/7163/ما-يجب-على-المحادة-وما-يباح-لها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_223/22306.mp3","categories":["العِدَد"]},{"id":9179,"question":"الرسالة التالية أيضًا عن موضوع الطلاق وباعثتها إحدى الأخوات أشارت إلى نفسها بقولها: بنت فلان، وبعثت رسالتها بهذا البريد الذي يسمونه البريد الممتاز، تقول: السلام عليكم ورحمة الله وبركاته، أرجو عرض رسالتي على سماحة الشيخ عبدالعزيز بن باز تقول: إنها فتاة متزوجة وحصل بيني وبين زوجي طلاق للمرة الأخيرة ثم سأل وأفتوه بأنه يجوز والطلاق لم يصح- هكذا تعبر سماحة الشيخ- لأنه في حالة غضب ورجعت مع زوجي واستمرت الحياة بيننا لمدة سنة، ثم عرفت أن الذي يفقد وعيه طلاقه لا يصح وزوجي لم يفقد وعيه، وبعدما عرفت ذهبت إلى أهلي ولم يكتب لي ورقة طلاق، وقال لي زوجي: لا يلزمك ورقة طلاق، ما دام عرفنا أن جلوسنا على غير صح، ثم قال لي: إذا أراد الله ثم تزوجتي وتطلقتي سوف أراجعك، وحصل أن تزوجت فعلًا وطلقت من زوجها الأخير واسترجعها، لكنها تشكو من الطريقة التي اعتدت بها حيث لم تمكث إلا عشرين يومًا في العدة، وترجو من سماحة الشيخ التوجيه جزاكم الله خيرًا؟","title":"حكم زواج المرأة قبل انتهاء عدتها","answer":"الجواب: الواجب ألا يتزوجها إلا بعد العدة، فإذا كان تزوجها وهي في عدة الزوج الثاني فالزواج باطل؛ لأن الله يقول: وَلا تَعْزِمُوا عُقْدَةَ النِّكَاحِ حَتَّى يَبْلُغَ الْكِتَابُ أَجَلَهُ [البقرة:235] يعني: حتى تنتهي من العدة، وهذا أمر أجمع عليه أهل العلم، فإذا تزوجت الزوج الثاني زواجًا شرعيًا ليس بقصد التحليل بل زواجًا شرعيًا، ووطئها الزوج الثاني فليس للزوج الأول أن يتزوجها إلا بعد خروجها من العدة بثلاث حيض إن كانت تحيض، أو بثلاثة أشهر إن كانت لا تحيض.\nوالحاصل أن الزواج هذا باطل إذا كان في العدة، وعليه أن يتجنبها ويصبر حتى تعتد فإذا اعتدت أعاد النكاح من جديد مع التوبة والاستغفار، عليهما التوبة جميعًا من الله سبحانه وتعالى، هذا إذا كانت الطلقة الأخيرة الثالثة لقد وقعت، وأما إن كانت لم تقع؛ لأنه حين الطلاق قد اشتد غضبه شدة واضحة بينة بأسباب النزاع الشديد أو المسابة أو المضاربة فإنها لا تقع على الصحيح ولا يحتاج إلى زواج ثاني.\nلكن مادامت تزوجت فليس له أن ينكحها إلا بعد خروجها من العدة؛ لأن الزوج الثاني له حرمته، وقد تزوجها زواجًا شرعيًا بعد عدتها من الأول، هذا إذا كان الزوج الثاني بعد العدة، يعني بعد خروجها من عدة الأول، فإن زواجه حينئذ صحيح إذا كان ليس بقصد التحليل بل عن رغبة ثم وطئها أيضًا فإنها تحل للأول على القول بوقوع الطلقة الثالثة فإنها تحل له إذا انتهت من العدة، أما زواجها في العدة فلا يصح، وعليه التوبة إلى الله، وعليها التوبة إلى الله، فإذا فرغت من العدة فإنه يتزوجها بعد ذلك، فعليها العدة، إكمال عدة الأول، وعليها إكمال العدة من الثاني الذي وطئها بغير حق، إذا كان وطئها بالنكاح الجديد هذا الفاسد تعتد العدة من الأول وعليها أن تعتد من الثاني عدة شرعية بثلاث حيض أيضًا ثم يتزوجها بعد ذلك.\nوفيه قول آخر: أن عدتها من الثاني لا تلزم لأن الماء ماؤه لو حملت وإنما عليها أن تكمل العدة من الأول هذا أمر معلوم عند أهل العلم، فعليها أن تكمل العدة ...... من الأول ثم إن أكملت العدة من الثاني فحسن وإن تزوجت في عدة الثاني لأن الماء ماؤه فلا بأس زواجًا شرعيًا.\nأما نكاحها في حال عدة الأول فإنه غير صحيح كما تقدم. نعم.\nوعليهما أن يرجعا إلى المحكمة فيما أشكل عليهما، عليهما أن يرجعا إلى المحكمة فيما أشكل عليهما.\nالمقدم: تقول: إنها تعيش الآن مع الزوج الأخير ثمان سنوات رغم ذلك الخلط الذي حصل بينها وبين أزواجها.\nالشيخ: كيف؟\nالمقدم: تقول: إنها تعيش مع الزوج الأخير..\nالشيخ: اقرأ كلامها الأول.\nالمقدم: وحتى الزوج الثاني لم يعلم ما بنفسي وجلست معه يومين وحصل جماع بيننا مرتين وحصل خصام ولكن لم يكن متعمد مني وقال: بالحرام من أهلي وكررها مرة ثانية وجعلت هذه الكلمة عذرًا وطلبت منه الطلاق فلم يرض وخالعته عن طريق المحكمة ثم أكملت العدة ثلاثة أشهر وعشرة أيام ثم رجعت إلى زوجي الأول وأنا الآن عائشة معه ثمان سنوات ورزقنا الله بولد ولم أعرف هذه الأشياء كلها إلا الآن بعدما جلست معه هذه المدة، وأنا الآن في حيرة من أمري، هل جلوسي معه صح أم غير صحيح؟\nالشيخ: عليها أن تراجع المحكمة هي وزوجها حتى تنظر المحكمة في الأمر. نعم.","link":"https://binbaz.org.sa/fatwas/7339/حكم-زواج-المراة-قبل-انتهاء-عدتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_180/18003.mp3","categories":["الطلاق","العِدَد","الرجعة"]},{"id":9608,"question":"وهذه رسالة وردت إلينا من الأخ أبو قرشي سوداني مقيم بجدة، يقول في رسالته: كثير من الناس يطلقون زوجاتهم، وتكون الطلقة رجعية، وعندما يطلقها تذهب فوراً لمنزل أهلها ليلاً أو نهاراً، فهل هذا يجوز؟ وماذا تفعل المرأة بعد طلاقها طلقةً رجعية؟ هل تقعد في بيتها أم أن عليها مفارقة بيت زوجها أفيدونا أفادكم الله؟","title":"حكم خروج المطلقة الرجعية من بيت زوجها في العدة","answer":"الجواب: الواجب على المطلقة طلاقاً رجعياً أن تبقى في البيت عند زوجها؛ لعله يراجعها، وليس له إخراجها، وليس لها الخروج؛ لقول الله سبحانه: يا أيها النَّبِيُّ إِذَا طَلَّقْتُمُ النِّسَاءَ فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ وَأَحْصُوا الْعِدَّةَ وَاتَّقُوا اللَّهَ رَبَّكُمْ لا تُخْرِجُوهُنَّ مِنْ بُيُوتِهِنَّ وَلا يَخْرُجْنَ إِلَّا أَنْ يَأْتِينَ بِفَاحِشَةٍ مُبَيِّنَةٍ [الطلاق:1] فالله سبحانه بين أنهن لا يخرجن ولا يخرجن، هذا هو الواجب على المرأة أن تبقى في البيت حتى تنتهي العدة، وليس لها الخروج، وليس له إخراجها أيضاً.\nأما إذا كانت بائنة طلقها آخر ثلاث؛ فإنها تخرج إلى بيت أهلها، وإن جلست في بيت زوجها وهي مصونة عندها نساء بحيث يعني لا يكون خطراً من جهة صلته بها وهي بائن فلا حرج، إن خرجت فلا بأس فقد طلقت فاطمة بنت قيس واعتدت خارج بيت زوجها، وقال لها النبي ﷺ: إنه ليس لك عليه سكنى كنه ولا نفقة لأنه قد أبانها طلق آخر ثلاث.\nوأما الرجعية فكما تقدم الواجب بقاؤها في البيت، وليس لها الخروج وليس له إخراجها؛ لأن هذا وسيلة إلى رجعته لها، قد قال الله سبحانه بعد ذلك. بعد ما ذكر النهي عن خروجها وإخراجها قال: لا تَدْرِي لَعَلَّ اللَّهَ يُحْدِثُ بَعْدَ ذَلِكَ أَمْرًا [الطلاق:1] والمراد يعني: الرجعة، ربما راجعها وسهل عليه أمر المراجعة؛ لأنها في البيت.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7773/حكم-خروج-المطلقة-الرجعية-من-بيت-زوجها-في-العدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_249/24904.mp3","categories":["الطلاق","العِدَد"]},{"id":9637,"question":"الرسالة التالية وصلت من الأخ الذي رمز إلى اسمه (ب. ب) ويعمل في أبو ظبي وهو من تونس يقول الأخ في رسالته: إنه طلق زوجته ولم يعلمها واجتمعت بها بعد أن طلقتها ثم أرسلتها إلى منزل والديها ثم سافرت حيث أعمل، بعد ذلك أرجعتها هاتفيًا لكنني ما زلت لم أكتب الرجعة وهي الآن بمنزلي، فهل يمكن لي الجماع بها عندما أعود وذلك قبل أن أكتب الرجعة أم لا أفيدونا أفادكم الله؟","title":"صيغ مراجعة المطلقة","answer":"الجواب: مادام الطلاق طلقة واحدة ليس قبلها طلقتان فلك مراجعتها وجماعها مراجعة، ولكن الأفضل أن تكون لك نية عند الجماع نية المراجعة.\nالمقصود أنه يكفي المراجعة والحمد لله وهي زوجتك الآن ولو أشهدت على المراجعة لكان أفضل وأحسن، وإذا نوى الإنسان المراجعة في جماعه كان ذلك كافيًا والحمد لله، هي زوجتك ومضى عليها طلقة وبقي له طلقتان، أما إن كان مضى لها طلقتان فهذه تكون الثالثة ما تصلح. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/7800/صيغ-مراجعة-المطلقة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_193/19315.mp3","categories":["الرجعة","العِدَد"]},{"id":9787,"question":"هذه رسالة وردت إلينا من محمد نصر الدين مصطفى سوداني مقيم باليمن الشمالية مدينة صنعاء، الأخ محمد له عدة أسئلة في رسالته، يقول في أولها: له أخت قد طلقها زوجها قبل ثلاث سنوات، طلقة واحدة، ولهما ابن واحد عمره حوالي تسع سنوات، وهو الوحيد الذي أحياه الله لهم من بين أبنائهم وبناتهم الذين توفاهم الله عز وجل، فيقول: إنني أحاول إرجاع المياه إلى مجاريها والإصلاح بينهم، فهل الصلح جائز في هذه الحالة؟ وهل يجوز أن ترجع المرأة إلى عصمة زوجها وكيف يكون الرجوع أفيدوني أفادكم الله؟","title":"حكم إرجاع المطلقة الرجعية بعد خروجها من العدة","answer":"الجواب: إذا كانت المرأة المذكورة قد طلقت طلقة واحدة فقط ولم يطلقها أكثر من ذلك فله أن يراجعها ما دامت في العدة، فإن كانت قد خرجت من العدة جاز له الرجوع بنكاح جديد بشروطه المعتبرة شرعاً، يعني: يخطبها فإذا رضيت زوجها وليها عليه بالمهر الذي يتراضيان عليه ويكون بحضرة شاهدين.\nأما إن كانت في العدة ما بعد مضى عليها ثلاث حيض بل لا تزال في العدة، فإنه يراجعها من دون عقد، فيقول: اشهد يا فلان وفلان -شاهدين- أني راجعت زوجتي فلانة ويكفي، ولا حاجة إلى عقد ما دامت في العدة، إذا كانت تحيض ولم يأتها ثلاث حيضات فإنها تكون في العدة، فيراجعها بدون عقد، وهكذا إن كانت كبيرة السن قد انقطع عنها الحيض فإن عدتها ثلاثة أشهر، فإذا كانت لم تمر عليها الثلاثة راجعها من دون عقد، أما بعد خروجها من العدة فلا بد من عقد جديد، وذلك مثل بقية الرجال يخطبها إلى وليها وإلى نفسها ومتى وافقت ووافق وليها تراضيا على المهر الذي يرضيها ثم تم العقد، يقول له الولي: زوجتك فلانة بنتي إن كان أبوها موجود أو أخوها، زوجت بنتي أو أختي فلانة، وهو يقول: قبلت هذا الزواج، بحضرة شاهدين عدلين وتم الأمر. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7953/حكم-ارجاع-المطلقة-الرجعية-بعد-خروجها-من-العدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_259/25906.mp3","categories":["الطلاق","العِدَد"]},{"id":9938,"question":"آخر ما في رسالته يقول: ما هي الصفة التي تقال عند إرجاع المطلقة؟","title":"الألفاظ المعتبرة عند مراجعة المطلقة","answer":"الجواب: الكلمة الدالة على إرجاعها تكفي، إذا قال: أنا مراجع زوجتي، راجعت زوجتي، أمسكت زوجتي، رددت زوجتي إلى عصمتي، كلمات تدل على المعنى مثل هذه الكلمات، يشهد شاهدين أفضل يحاول أن يكون عنده شاهدان عدلان فيقول لهما: اشهدا أني راجعت زوجتي أني رددت زوجتي، أني أمسكت زوجتي، أني أعدت زوجتي إلى عصمتي، نحو هذه الكلمات. نعم.\nالمقدم: جزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/8105/الالفاظ-المعتبرة-عند-مراجعة-المطلقة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_199/199011.mp3","categories":["الرجعة","العِدَد"]},{"id":9940,"question":"هذا سؤال ورد من السائل أريتيري الجنسية سحيم هلال محمد، يقول في رسالته: امرأة سافر عنها زوجها وهي حامل فوضعت له ابنًا وهو غائب عنها وكان مريضًا في سفره، والمرأة لا تحصل على مصاريف منه، وبعد مدة طلبت طلاق خلع منه وهو غائب، وطلقها قبل أن يجامعها بعد وضع الحمل، فهل على هذه المرأة عدة لزوجها السابق أم تسقط عنها العدة بسبب عدم الجماع بينهما بعد وضع الحمل، أفيدونا أفادكم الله؟","title":"عدة المطلقة المدخول بها والمخلوعة","answer":"الجواب: المطلقات عليهن العدة ولو كان الزوج قد تركها مدة طويلة لم يجامعها في حال الحمل وبعد الحمل؛ لقول الله : وَالْمُطَلَّقَاتُ يَتَرَبَّصْنَ بِأَنفُسِهِنَّ ثَلاثَةَ قُرُوءٍ [البقرة:228] وهذا يعم جميع المطلقات المدخول بهن، فكل امرأة دخل بها الزوج ثم طلقها فإن عليها العدة ولو كان طلاقه لها بعد الولادة ولم يجامعها بعد ذلك فإنها تعتد لعموم الآية الكريمة وما جاء في معناها، ولكن اختلف العلماء هل المخلوعة تعتد ثلاثًا أم حيضة واحدة، وهذه التي سألت عنها مخلوعة، إذا كانت قدمت له مالًا وأعطته مالًا حتى خلعها فالصواب أنه يكفيها حيضة واحدة؛ لحديث الربيع بنت معوذ لما خالعت زوجها أمرها النبي ﷺ أن تعتد بحيضة، وهكذا جاء في حديث ثابت بن قيس ، فالمقصود أن المخلوعة التي طلقها زوجها على مال إن اعتدت ثلاث حيض هذا أفضل وأحوط، وفيه خروج من خلاف العلماء، وإن اعتدت بحيضة واحدة كفاها ذلك في أصح قولي أهل العلم؛ لما ثبت في هذا من السنة المشار إليها، والله ولي التوفيق. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/8108/عدة-المطلقة-المدخول-بها-والمخلوعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_274/27402.mp3","categories":["العِدَد"]},{"id":9942,"question":"وهذه رسالة وردت من السائل (ع. م. ح) سوداني مقيم في المملكة، يقول في رسالته: حصل أن طلقت زوجتي ومضى بعد الطلاق مدة أربعة أشهر، وراجعت زوجتي بنفس الصداق الأول، وقال لي المأذون: يجوز هذا؛ لأنه طلاق رجعي، لكنني في شك من ذلك، أفيدوني أفادكم الله؟","title":"حكم من طلق طلاقاً رجعياً ثم انقضت العدة وأراد استرجاعها","answer":"الجواب: إذا كان الطلاق الذي وقع منك طلقة واحدة أو طلقتين فقط، وكانت الرجعة في العدة بأن تأخر عنها بعض الحيض حتى راجعتها قبل الحيضة الثالثة فإن الرجعة تصح ولا حاجة إلى عقد نكاح جديد، ولا إلى صداق، لكن بهذين الشرطين:\nالشرط الأول: أن يكون الطلاق الذي وقع منك أقل من ثلاث طلقة أو طلقتين.\nوالشرط الثاني: أن تكون في العدة حين الرجعة، أما إن كان قد مضى عليها ثلاث حيض إذا كانت تحيض فإن الرجعة لا تصح حينئذ، وهكذا لو كانت لا تحيض فإنها لا تصح الرجعة لأنه مضى عليها أكثر من ثلاثة أشهر، وعدة التي لا تحيض كالآيسة والصغيرة التي لا تحيض عدتها ثلاثة أشهر بنص القرآن، فإذا كانت الرجعة منك بعد ثلاثة أشهر وهي لا تحيض أو بعد ثلاث حيض إذا كانت تحيض فالرجعة غير صحيحة، فعليك أن تجدد النكاح وعليك أن تمتنع منها، وعليك التوبة والاستغفار، وعليها كذلك التوبة والاستغفار والندم، وعليكما أن تجددا نكاحاً شرعياً بولي وشاهدين ورضاها، أما إن كانت لا ترضى فلا يصح النكاح لابد من رضاها ولابد من ولي وهو أقرب العصبة، وشاهدين يحضران العقد، وبهذا تحل لك إذا كان الواقع هو ما ذكرت، والخلاصة أنك إن كنت طلقتها طلقة واحدة أو طلقتين وكانت في العدة لم تحض ثلاث حيض فإن الرجعة صحيحة، أما إن كانت قد حاضت ... ثلاث حيض قبل رجعتك أو كان الطلاق الذي وقع منك هو الطلقة الأخيرة الثالثة فإن الرجعة لا تصح، والله ولي التوفيق. \nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/8110/حكم-من-طلق-طلاقا-رجعيا-ثم-انقضت-العدة-واراد-استرجاعها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_274/27403.mp3","categories":["الطلاق","العِدَد"]},{"id":10213,"question":"امرأة عقد عليها رجل ولم يدخل بها، ثم مات الرجل، هل على هذه المرأة عدة؟ وهل لها ميراث؟","title":"ما العدة والإحداد والميراث لمن مات زوجها قبل الدخول؟","answer":"الجواب: نعم، إذا عقد عليها فعليها العدة إذا مات ولها الميراث، وقد ثبت ذلك عن النبي ﷺ من حديث معقل بن يسار، وقد قضى في ذلك ابن مسعود فلما بلغه أن قضيته وافقت قضاء النبي ﷺ فرح بذلك، فإذا عقد الرجل على امرأة ثم مات فإنها ترثه، وتعتد عليه أربعة أشهر وعشرًا، وتحاد عليه، وهذا بخلاف الطلاق، أما إذا طلقها قبل أن يدخل بها وقبل أن يخلو بها فإنه لا عدة عليها، كما قال الله سبحانه: يَا أَيُّهَا الَّذِينَ آمَنُوا إِذَا نَكَحْتُمُ الْمُؤْمِنَاتِ ثُمَّ طَلَّقْتُمُوهُنَّ مِنْ قَبْلِ أَنْ تَمَسُّوهُنَّ فَمَا لَكُمْ عَلَيْهِنَّ مِنْ عِدَّةٍ تَعْتَدُّونَهَا [الأحزاب:49] فالمطلقة قبل الدخول والخلوة ليس عليها عدة، ولكن إذا مات عنها بعد العقد فإن عليها العدة، وهذا من المواضع التي خالف فيها الموت الطلاق، ففي هذا ترث وتعتد وتحاد، وإن كان لم يدخل بها ولم يخل بها، وأما في الطلاق فإنها لا تعتد منه ولها أن تتزوج متى شاءت من حين الطلاق. \nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8382/ما-العدة-والاحداد-والميراث-لمن-مات-زوجها-قبل-الدخول","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_335/33504.mp3","categories":["الفرائض","العِدَد"]},{"id":10424,"question":"من الهياثم في الخرج رسالة من إحدى الأخوات المستمعات تقول أم فهد ، أم فهد تسأل وتقول: إن والدي توفي منذ قرابة الشهر والنصف، والمشكلة تكمن فيما يتناقله الناس عن ماذا يجب على المرأة في فترة الحداد، فمنهم من يقول: إنه لا يجوز أن تمشي المرأة على الأرض بدون حذاء؛ لأنها قد تكون تمشي على كبد المتوفى! وأيضاً يقولون: لا يجوز للمرأة أن تسلم على امرأة متزوجة ويكون زوجها غير محرماً لهذه المرأة التي في الحداد! وأيضاً يقولون: إنه لا يجوز نقل السلام من شخص ما إلى هذه المرأة التي في الحداد، أو أن تنقل هذه المرأة السلام إلى شخص كأن تقول: أبلغوا سلامي إلى فلانة أو فلان يسلم عليك وهكذا! أفيدوني أفادكم الله؛ لأن والدتي في حيرة من أمرها، وتتمنى من الله أن يوفقكم لما فيه خير المسلمين، والسلام عليكم ورحمة الله وبركاته؟","title":"أحكام المرأة المتوفى عنها زوجها","answer":"الجواب: كثير من الناس يقولون عن المحادة أشياء لا أساس لها، ويأتون بخرافات لا أساس لها، وهذه منها، هذه التي ذكرت السائلة منها، فلا بأس أن تنقل السلام، ولا بأس أن يسلم عليها، ولا بأس أن تسلم على زوجة غير محرمها، وعلى من شاءت من الناس، ولا بأس أن تمشي حافية في بيتها، كل ذلك لا بأس لا حرج فيه، والذي يطلب من المحادة أن تلاحظه خمسة أمور ينبغي أن تحفظ، خمسة أمور يطلب من المحادة المتوفى عنها زوجها، يطلب منها أن تراعيها دلت عليها النصوص:\nالأول: أن تبقى في البيت الذي مات زوجها وهي ساكنة فيها تبقى فيه، محادة فيه إذا تيسر ذلك، تبقى في البيت إذا كان البيت ملكاً لزوجها أو مستأجر أو يمكن إكمال العدة فيه تبقى فيه حتى تنتهي العدة؛ لقول النبي صلى الله عليه وسلم لـ فريعة بنت مالك لما مات زوجها: امكثي في بيتك حتى يبلغ الكتاب أجله امكثي يعني: اسكني، في بيتك حتى يبلغ الكتاب أجله يعني: حتى تنتهي العدة، إلا إذا كان هناك مانع، مثل البيت ليس لزوجها، بل مستأجر وتمت المدة ويريده أهله فلا بأس تخرج، أو انهدم البيت، أو ليس عندها من يؤنسها تخاف الجلوس فيه، تخرج إلى أهلها، إلى محل آمن، يعني: تخرج بعذر شرعي وإلا فتبقى في البيت، ولا بأس بخروجها من البيت لحاجة كأن تشتري حاجة من السوق طعام أو غيره من الحاجات، أو تذهب إلى الطبيب.. إلى المستشفى لا بأس، أو تخرج للمحكمة لها دعوى أو وكالة تخرج لا بأس لحاجة.\nالأمر الثاني: أن تكون الملابس غير جميلة ملابس عادية ليست جميلة، تلبس ملابس غير جميلة، لقوله ﷺ للمحادة: ولا تلبس ثوباً مصبوغاً إلا ثوب عصب، قال العلماء معناه: ثوب مصبوغ يعني صبغ جميل يعني فيه جمال فيه.. يلفت النظر، أما ثياب العصب فهي غير جميلة، فإذا كانت الملابس غير جميلة فلا بأس، سواءً كانت سوداء أو غير سوداء، ما هو بلزوم سوداء، سوداء أو خضراء أو حمراء أو صفراء لا بأس، لكن تكون غير جميلة.\nالأمر الثالث: عدم الحلي، لا تلبس الحلي لا الذهب ولا الفضة ولا ولا الماس ولا الخواتيم كلها لا تلبس شيء، وإذا كانت عليها تزيلها؛ لأن الرسول ﷺ نهى عن لبس الحلي للمحادة.\nالرابع: عدم الطيب بالبخور بخور بماء الورد أو العود أو نحوه من الأطياب، إلا إذا كانت تحيض، شابة تحيض إذا طهرت لا بأس أن تتعاطى بعض البخور عند الطهر.\nالخامس: عدم الكحل والحناء، لا تتكحل؛ لأن الرسول ﷺ نهى أن تكحل عينها، أما الدواء لا بأس تداوي عينها بالصبر بالقطور، دواء لا بأس أما الكحل كحل الزينة لا، وكذلك التحني لأنه زينة، فلا تتحنى.\nهذه خمسة أمور تراعيها، والباقي ما عليها شيء، الباقي كونها تلبس ملابس جديدة لكنها ما هي بجميلة، كونها تمشي حافية، كونها تغتسل كل يوم أو كل يوم وراء يوم، كونها تغير ملابسها لا بأس، تروش متى شاءت، تغير ملابسها متى شاءت، تكشف رأسها إذا كان ما عندها أجنبي، تكشف رأسها في حال جلوسها أو في حال نومها، لا بأس، تمشي في خف أو في غير خف، في جوارب أو غير جوارب لا بأس، تذهب إلى السطح إلى القمراء السطوح لا بأس، إلى الحوش إلى الحديقة في البيت لا بأس، كل هذه أمور ما عدا الخمسة المذكورة لا حرج عليها والحمد لله، تسلم في التلفون، تكلم في التلفون حاجاتها، ترد على التلفون، من جاء يسلم عليها بعض أقاربها .... ترد عليهم، لكن لا تخلو بأحد، الزوجة لا تخلو بأجنبي، ترد عليه من دون خلوة مع التستر أيضاً، تسلم على النساء، تصافح، تصاحف محارمها لا بأس أخوها عمها تصافحه، النساء تصافحهن قريبات أو غير قريبات، كل هذا لا بأس به، ما عدا الخمسة الأشياء التي ذكرنا، وفق الله الجميع. نعم.\nالمقدم: اللهم آمين، جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8594/احكام-المراة-المتوفى-عنها-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_317/31702.mp3","categories":["العِدَد"]},{"id":10532,"question":"ننتقل إلى رسالة وصلت من الجزائر من السائلة ج. حكيمة من الجزائر تقول: هل يجوز للمعتدة المتوفى عنها زوجها أن تخرج للضرورة في أيام العدة؟","title":"حكم خروج المعتدة عدة الوفاة أثناء العدة للضرورة","answer":"الجواب: نعم لها أن تخرج لحاجتها، كشراء حاجة من السوق، أو خروج المستشفى للعلاج، أو المحكمة لدعوى عليها، أو لدعوى تدعيها على غيرها، لا بأس، خروجها للحاجة لا حرج في ذلك، لكنها تبقى في البيت حتى تكمل العدة، أما خروجها للحاجة فلا يمنع منه، نعم.","link":"https://binbaz.org.sa/fatwas/8707/حكم-خروج-المعتدة-عدة-الوفاة-اثناء-العدة-للضرورة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_284/28404.mp3","categories":["العِدَد"]},{"id":10561,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين يقول حسين السوداني: -سؤاله مطول بعض الشيء ومشوش أيضاً- يقول: أرسلت رسالة إلى أخي بأن الزوجة طالق، ولم يعرفها أخي بأنها طالق بعد مكاتبة بيني وبينه دامت عشرة شهور، وبعد ذلك أصر أخي على أن أراجعها، وبعد كل هذه المدة وهي معه بالمنزل ولم تعرف بادرت برسالة فيها موافقتي على رجوعها، فقال لزوجتي: كنت طالق والحمد لله رجعتك إلى زوجك، أرجو إفتائي جزاكم الله خيراً، إذ أن بعض الناس يقولون: إن هذا ليس بطلاق وأنا الآن أريد أن أستفسر لأعيش حياة صحيحة؟ جزاكم الله خيراً.","title":"حكم إرجاع المطلقة رجعياً بعد انتهاء عدتها","answer":"الجواب: إذا كان الطلاق طلقة واحدة ما قبلها طلقتان فإنه يقع عليها طلقة واحدة، ولك مراجعتها ما دامت في العدة، فإن كانت قد خرجت من العدة قبل أن تراجعها فلابد من عقد جديد ... جديد، والمدة طويلة التي ذكرت، والظاهر أنها خرجت من العدة، لأن العدة تكون بثلاث حيض فمراجعتها بعد عشرة أشهر يبعد مصادفتها للعدة؛ لأن الغالب أن المرأة ترى الحيض في كل شهر، فتكون قد خرجت من العدة بعد ثلاثة أشهر، وتكون مراجعتها ليست في محلها، وعليك أن تجدد عقداً جديداً بينك وبينها إذا كانت ترغب فيك، وفي إمكانك أن تتصل بالمفتي في البلاد وتشرح له القضية أنت والمرأة ووليها حتى يجري ما يلزم في حقكما، إذ لابد من التفصيل وسؤالها عن متى انتهت عدتها، ومتى صارت منك الرجعة، فالمسألة تحتاج إلى عناية من المفتي لديكم أو المحكمة، ونسأل الله للجميع الهداية والتوفيق.\nالمقدم: آمين جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8735/حكم-ارجاع-المطلقة-رجعيا-بعد-انتهاء-عدتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_322/32205.mp3","categories":["الطلاق","العِدَد","الرجعة"]},{"id":10598,"question":"المستمع أحمد فرج فهد من الأردن بعث برسالة يقول: كنت متزوجاً من امرأة، وحصل مشاكل بيني وبينها، وكثرت من مرة إلى مرة، والمشاكل تعددت إلى أهل زوجتي وأهلي، وقد حصل أن زوجتي سبت أبي وسبتني، وعلى ذلك طلقتها وهي معها أطفال اثنان، وفي فترة العدة ظهر أنها حامل، راجعت نفسي خوفاً من الله ثم راجعتها؛ لأنها حامل ومعها طفلان، لكن أبي عارض ذلك علماً بأني أسكن بيتاً بجانبه، وقد هددني بالرحيل إن لم أطلقها، فبماذا توجهونني جزاكم الله خيراً؟","title":"حكم مراجعة الزوجة دون رضا والد الزوج","answer":"الجواب: عليك أن تراجع المحكمة أنت وأبوك والمرأة ووليها حتى تنظر المحكمة في الواقع، وحتى تفتيكم بما يقتضيه الشرع المطهر، أنت والمرأة ووليها وأبوك جميعاً، تراجعوا المحكمة في البلد بلدكم تشرحون لها القضية، والقاضي ينظر في الأمر إن شاء ويحكم بينكم بما يقتضيه الشرع المطهر، ونسأل الله للجميع التوفيق.\nالمقدم: آمين جزاكم الله خيرا.","link":"https://binbaz.org.sa/fatwas/8765/حكم-مراجعة-الزوجة-دون-رضا-والد-الزوج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_325/32503.mp3","categories":["الرجعة","العِدَد"]},{"id":10846,"question":"سماحة الشيخ ننتقل إلى رسالة أخرى من إحدى الأخوات المستمعات تقول: (ن. م. ط) من الرياض، تقول عن نفسها: أنا فتاة ملتزمة، ومتزوجة -والحمد لله- من سنتين، وأنا حامل الآن، ثم قدر الله لزوجي أن توفي في حادث ما، ماذا يجب علي في مدة الحداد؛ لأن أخواتي في الله كل واحدة منهن تعطيني نصيحة فتقول: لا تستحمي، ولا تكتحلي، ولا تلبسي ملابس غير الأسود، ولا تنظري للقمر، ولا للنجوم، وحين إقامة الصلاة تصلين مع الرجال، ماذا يجب علي بالتفصيل؟ جزاكم الله خيرًا، وهل يجوز أن أسفر عن وجهي أمام شاب عمره ثلاث عشرة سنة؟","title":"الأحكام التي تجب على من توفي عنها زوجها","answer":"الجواب:  المحادة التي مات زوجها تراعي خمسة أمور جاءت بها السنة عن النبي، عليه الصلاة والسلام. الأمر الأول: بقاؤها في البيت الذي مات زوجها وهي ساكنة فيه، تبقى به إذا استطاعت ذلك حتى تنتهي من عدتها بوضع الحمل، أو بمضي أربعة أشهر وعشرًا، ولا بأس أن تخرج لحاجتها، كأن تخرج للطبيب للمستشفى، أو تخرج لخصومة للمحكمة، أو لحاجات تخرج إليها في السوق، ونحو ذلك من حاجاتها، ولا بأس أن تخرج من البيت إذا كان فيه من يؤنسها وتستوحش، لا بأس أن تنتقل عنه إذا لم يكن عندها من يؤنسها، أو كان البيت خربًا لا يحسن أن يبقى فيه، أو ما أشبه ذلك. الثاني: أن لا تلبس الملابس الجميلة، تلبس ملابسًا عادية، ليس فيها ما يلفت النظر، عادية سوداء أو خضراء ما هو بلزوم الأسود، ليس بلازم الأسود، ما تيسر، أخضر أو أسود أو أحمر أو غير ذلك، لكن تكون ملابس عادية، ليس فيها ما يلفت النظر، ويسبب الفتنة. الثالث: عدم الحلي لا ذهبًا ولا فضة ولا ماسًا، لا تلبس الحلي؛ لأنها قد تسبب فتنة وتشوف للأزواج. الرابع: عدم الطيب: أن تتطيب لا ببخور ولا بغيره من الأطياب، حتى تنتهي من العدة، إلا إذا كانت تحيض شابة تحيض كلما طهرت من حيضها تستعمل بعض البخور بعد الطهر من حيضها، ولا بأس بتطييب المنزل، الحجرة والمنزل لا بأس، لكن لا تطيب في نفسها. والخامس: عدم التحكل والمكياج ونحوه والحناء، بل تنظف وجهها وبدنها بغير هذا، كالسدر والصابون ونحو ذلك لا بأس، أما الكحل والمكياج والحناء فلا، والصابون الممسك لو تركته يكون أحسن وإلا ليس بطيب، لكن فيه شيء من الطيب لو ترك من باب: دع ما يريبك لا بأس، هذه الأمور الخمسة هي التي تطلب من المحادة. أما كونها تنظر للقمر أو النجوم لا بأس بهذا، ولا حرج أن تذهب إلى الحديقة حديقة البيت تمشي فيها حافية، أو عليها جوارب لا بأس أو نعال، ولا بأس أن تصعد إلى السطح ولو في القمراء لا حرج في هذا، ولا بأس أن تستحم متى شاءت، يعني: تغتسل متى شاءت، في يوم الجمعة، أو في غير الجمعة متى شاءت، ولو كل يوم لا حرج عليها في ذلك، ولا بأس أن تستعمل مثل الكريمة مثل الشامبو، مثل غيرها مما تحتاج إليه والسدر، ونحو ذلك كل هذا لا حرج في ذلك. والعامة عندهم خرافات كثيرة لا ينبغي الالتفات إليها في هذا، كل هذا لا حرج فيه ..... الصبية الصغار لا حرج أن ينظروا إليها، أما إذا كان مراهقًا فالأحوط التستر عنه، الأحوط؛ لأنه قد يكون بلغ، فالأحوط أن لا تكشف له، وأن تستر عنه، ولا بأس أن تكلم الرجال، أن تسلم عليهم، ترد عليهم السلام من طريق الهاتف التلفون، أو من طريق المباشرة إذا سلموا عليها، أو سألوها عن حاجة، وطلبوا الباب عن حاجة، على وجه ليس فيه ريبة ولا منكر. المقدم: ومن وراء حجاب؟ الشيخ: ومن وراء حجاب، وهي متحجبة لا حرج، كل هذا لا بأس به، أو تكلم بالتلفون أقاربها، أو ترد الهاتف، كل هذا لا بأس به، وأما ما يقوله العامة من تشديد، فهذا لا وجه له. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9031/الاحكام-التي-تجب-على-من-توفي-عنها-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_356/35612.mp3","categories":["العِدَد"]},{"id":10950,"question":"عدة الحامل كم تكون سماحة الشيخ؟ ومتى يجوز للمطلق أن يراجع إذا كانت حاملًا؟","title":"عدة الحامل وكيفية مراجعتها","answer":"الجواب:  عدة الحامل وضع الحمل، كما قال سبحانه: وَأُوْلاتُ الأَحْمَالِ أَجَلُهُنَّ أَنْ يَضَعْنَ حَمْلَهُنَّ [الطلاق:4] في الطلاق، والموت جميعًا، إذا مات عنها، أو طلقها عدتها وضع الحمل، وله أن يراجعها في الطلاق قبل أن تضع الحمل إذا كان الطلاق واحدةً أو ثنتين، أما إن كان الطلاق آخر الثلاث فليس فيه رجعة، إنما الرجعة في الواحدة والثنتين. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9121/عدة-الحامل-وكيفية-مراجعتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_363/36305.mp3","categories":["العِدَد"]},{"id":11205,"question":"هذه السائلة أختكم (ع. د. م) الباحة بلاد زهران، تقول: هل يحرم على المرأة التي في الحداد أن تلبس الساعة في يدها؟ جزاكم الله خيرًا.","title":"حكم لبس المرأة للساعة أثناء الإحداد","answer":"الجواب:  تركها أحوط من باب الاحتياط، من باب قوله ﷺ: دع ما يريبك إلى ما لا يريبك؛ لأنها تشبه الحلي، لبس الساعة في اليد وهي في الإحداد تشبه الحلي، فالأحوط لها تركها؛ لأنها تشبه الخصر وأشباهه مما يلبس في اليد من أسورة وغيرها. نعم.","link":"https://binbaz.org.sa/fatwas/9386/حكم-لبس-المراة-للساعة-اثناء-الاحداد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_291/29105.mp3","categories":["العِدَد"]},{"id":11442,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من المستمع (سيد جلال . م. ش. أحمد ) من القاهرة، أخونا يسأل ويقول: كم عدة المطلقة، وإذا طلقت المرأة، وبعد طلاقها بعدة شهور توفي زوجها، فهل لها نصيب في الميراث؟ علمًا بأن المرأة حامل، وزوجها قد توفي -كما ذكرت- جزاكم الله خيرًا.","title":"حكم أخذ المطلقة من الميراث","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فعدة المطلقة قد أوضحها الله في كتابه حيث قال سبحانه: وَالْمُطَلَّقَاتُ يَتَرَبَّصْنَ بِأَنفُسِهِنَّ ثَلاثَةَ قُرُوءٍ [البقرة:228]، والصحيح أن القروء هي الحيض، هذه عدتها ثلاث حيضات بعد الطلاق، فإذا حاضت ثلاث مرات؛ بانت منه، وخرجت من عصمته، وإذا مات بعد ذلك؛ لا ترثه إذا مات بعد العدة، لا ترثه، سواءً كان الطلاق واحدة، أو طلقتين، أو ثلاثًا، متى صار الموت بعد العدة فإنها لا ترثه. أما إن كانت حاملًا كما ذكر السائل؛ فعدتها وضع الحمل، لقول الله سبحانه وَأُوْلاتُ الأَحْمَالِ أَجَلُهُنَّ أَنْ يَضَعْنَ حَمْلَهُنَّ [الطلاق:4]، فإذا مات وهي حامل؛ ففيه تفصيل: إن كان الطلاق طلقة، أو طلقتين رجعية؛ فلها الميراث. وإن كان الطلاق الطلقة الأخيرة الثالثة، أو الطلاق على عوض؛ فإنها لا ترثه، إذا كان طلقها عوضًا، دفعته إليه، وهو الخلع؛ فإنها تكون بائنة، ولا ترثه، ولو أنها حامل، أو كانت الطلقة الأخيرة الثالثة، قد طلقها طلقتين، وهذه الثالثة التي طلقها الأخيرة؛ فإنها لا ترثه أيضًا؛ لأنهما .... أجنبية، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9624/حكم-اخذ-المطلقة-من-الميراث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_381/38101.mp3","categories":["العِدَد","الفرائض"]},{"id":11558,"question":"تقول: إذا قضت المرأة أشهر الحداد، ولم تنزع الملابس السوداء، وهي مستمرة في ارتدائها، فهل هذا يجوز لها؟","title":"حكم لبس السواد بعد انتهاء زمن الإحداد","answer":"الجواب:  إذا كان من عادتها ذلك؛ فلا بأس، أما إذا كانت تريد الزيادة على ما شرع الله من بقاء الحزن، وبقاء الإحداد هذا لا يجوز، ليس لها أن تزيد عما شرع الله، أما إذا كانت عادتها لبس هذه الملابس، وليس قصدها مخالفة الشرع، ولكنها تحب الملابس السوداء، أو الخضراء التي كانت تلبسها، وإلا فلتطيب وتلبس الحلي غيرت الإحداد، لبست الحلي تطيبت؛ لا حرج في ذلك، أن تلبس ما شاءت عن غير قصد الإحداد، الإحداد انتهى. أما أن تبقى على حالها لا تلبس الجميل ولا تطيب ولا تكتحل تزيد على أربعة أشهر وعشرًا؛ هذا لا يجوز، هذه بدعة ومنكر.","link":"https://binbaz.org.sa/fatwas/9741/حكم-لبس-السواد-بعد-انتهاء-زمن-الاحداد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_297/29707.mp3","categories":["العِدَد","اللباس والزينة"]},{"id":11979,"question":"أختنا تسأل سؤالًا آخر، وتقول: إذا كانت المرأة في حالة حداد، فهل ترد على التليفون، وتخرج لقضاء الحاجات الضرورية؟ وهل هناك لباس معين للمرأة التي في الحداد؟","title":"الأمور التي تلزم المرأة المتوفى عنها زوجها أثناء الإحداد","answer":"الجواب:  نعم، ثبت عن النبي ﷺ أنه أمر المحادة: وهي التي توفي عنها زوجها أن تلزم البيت، تمكث في بيتها إذا تيسر ذلك حتى تكمل العدة أربعة أشهر وعشرًا، إلا أن تكون حاملًا؛ فعدتها وضع الحمل، ولو وضعت بعد الموت بقليل، وعليها ما بينه النبي ﷺ عليها أن تترك الملابس الجميلة، تلبس ملابس عادية، سواء خضراء، أو سوداء، أو حمراء عادية ما يتعين السواد، ملابس عادية، ليس فيها جمال، هذا واحد. والأمر الثاني: لزوم البيت، تبقى في بيتها إلا من حاجة مثل: خروجها لشراء حاجات من السوق، خروجها للمستشفى، وما أشبه ذلك، مدرسة تخرج تدرس، طالبة تخرج للطلب؛ لا حرج، يعني: حاجة، هذه حاجات. الثالث: لا تلبس الحلي الذهب والفضة والماس، قلائد أسورة خواتم تتركها. الرابع: عدم الطيب؛ لا بالبخور، ولا بالأطياب الأخرى، إلا عند طهرها من الحيض؛ لا بأس أن تتعاطى شيئًا عند طهرها من الحيض. الخامس: ترك الكحل وشبهه، يعني: التكحل الذي يزين العين؛ لأن هذا قد يسبب الفتنة، ترك الكحل، ونحوه من أوصف الجمال في وجهها حتى تكمل. هذه خمسة: لزوم المنزل هذا واحد، إلا من حاجة، خروج لحاجاتها، حاجة من السوق تجيبها، حاجة من المستشفى، المحكمة إذا عليها خصومة، مدرسة، طالبة. ثانيًا: عدم الملابس الجميلة، تلبس ملابس عادية، سوداء، وإلا غيرها، وإلا خضراء. الثالث: عدم الحلي، لا ذهب ولا فضة ولا ماس ولا نحوه. الرابع: عدم الطيب، التطيب. الخامس: عدم التكحل. فهذه الأشياء المطلوبة، لكن لها أن تكلم بالتلفون، وتسلم على الناس، ويسلمون عليها من محارم وغيرهم، وترد عليهم السلام، تكلم بالتلفون من شاءت إذا كان الكلام ليس فيه محذور، تكلم أقاربها، تكلم من كلم، ترد على التلفون، تصعد السطح، تخرج إلى الحوش، ما فيه شيء كل هذا لا بأس به. المقدم: الحمد لله. الشيخ: نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم، يسود شائعة بين عوام النساء سماحة الشيخ! أن المحتدة لا ترى القمر، ولا تخرج إلى الحديقة، ولا تستأنس مع جيرانها؟ الشيخ: هذا غلط، لها أن تستأنس مع الجيران إذا جاءها الجيران، زاروها الجيران، تستأنس معهم، وتنبسط معهم لقهوة وغيره، نعم، بالحديث الطيب، تخرج إلى الحديقة، حديقة بيتها، إلى حوش بيتها، إلى السطوح، السطح لحاجاتها في بيتها، وتخرج لحاجاتها الأخرى في السوق، تشتري طعامًا، تشتري حاجات لها، تروح للطبيب، للمحكمة إن كان عليها دعوى، وما أشبهه، مدرسة تخرج تؤدي التدريس، طالبة لا تدع الطلب، يعني حاجة. المقدم: طيب. الشيخ: نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم، إذا شعرت بضيق الصدر -سماحة الشيخ- هل لها أن تخرج للأنس مع جاراتها؟ الجواب: إذا شعرت عليها بذكر الله، عليها بذكر الله، والتسبيح، والتهليل، وقراءة القرآن، وتعزم جيرانها حتى يجلسون عندها يؤنسونها. المقدم: لكن إذا ذهبت هي؟ الشيخ: خروجهم لا، ليس هذا من الحاجات، خروجها لهم للأنس ما هو من الحاجات. المقدم: إذا شعرت هي بضيقة الصدر؛ فعليها أن تستدعي جيرانها، وتذكر الله؟ الشيخ: تجتهد في الذكر، قراءة القرآن وأشغال بيتها. المقدم: بارك الله فيكم، جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10164/الامور-التي-تلزم-المراة-المتوفى-عنها-زوجها-اثناء-الاحداد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_430/43002.mp3","categories":["العِدَد"]},{"id":12352,"question":"المستمع: عبدالمنعم فضل الله مصطفى بعث يسأل ويقول: توفي أحد أقاربي، وترك وراءه زوجته التي لم تكمل السنة من زواجها منه، وفي فترة العدة ظهر فيها الحمل، وبعد فترة من الزمن وضعت، وأنجبت ولدًا، وبعد إتمامها الأربعين بعد الوضع تزوجت مباشرة، فهل هناك غضاضة في ذلك؟","title":"عدة الحامل المتوفى عنها زوجها","answer":"الجواب:  لا حرج في ذلك؛ لأنها تخرج من العدة بوضع الحمل حتى ولو تزوجت في النفاس، لا حرج، لكن لا يقربها الزوج، لا يطؤها حتى تطهر. المقصود: أن العدة انتهت بوضع الحمل، فإن تزوجت في النفاس، أو بعد النفاس؛ فلا حرج ... لكن متى تزوجت في النفاس، فإن العقد صحيح، لكن ليس للزوج أن يطأها حتى تطهر. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10559/عدة-الحامل-المتوفى-عنها-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_399/39917.mp3","categories":["العِدَد"]},{"id":12548,"question":"الأخت السيدة خيرية، تقول: إنه توفي زوجها منذ أشهر، ولها بنات وأولاد كبار متزوجون، وهي قد انقطع عنها العذر الشرعي، فكم تكون عدتها؟ علمًا بأن عمرها ستون عامًا؟","title":"عدة المتوفى عنها زوجها، وما يجب عليها","answer":"الجواب: عدتها مثل غيرها، أربعة أشهر وعشرًا، لأن الله -جل وعلا- قال: وَالَّذِينَ يُتَوَفَّوْنَ مِنْكُمْ وَيَذَرُونَ أَزْوَاجًا يَتَرَبَّصْنَ بِأَنفُسِهِنَّ أَرْبَعَةَ أَشْهُرٍ وَعَشْرًا [البقرة:234] وهذا عام للتي يأتيها الحيض، وللشابة وللكبيرة يعم الجميع، الله -جل وعلا- قال: وَيَذَرُونَ أَزْوَاجًا يَتَرَبَّصْنََ بِأَنفُسِهِنَّ أَرْبَعَةَ أَشْهُرٍ وَعَشْرًا [البقرة:234] والأزواج يعني: الزوجات، فعلى الزوجة أن تربص أربعة أشهر وعشرًا، سواء كانت كبيرة السن، أو شابة تحيض، أو لا تحيض، عليها أن تعتد أربعة أشهر وعشرًا، يعني: مائة وثلاثين يومًا، مطلقًا ولو كانت تحيض، الواجب عليها العدة المذكورة، أربعة أشهر وعشرًا كما قاله الله . وهكذا جاء عن النبي ﷺ أن المتوفى عنها زوجها تعتد أربعة أشهر وعشرًا، كما نص عليه القرآن الكريم، وعليها في هذه العدة؛ الإحداد أيضًا، والإحداد: تجنب الزينة في الملابس ونحوها، لا تلبس الملابس الجميلة، ولا تكتحل، ولا تمس الطيب، ولا تلبس الحلي من الذهب والفضة والماس، ولا الملابس الجميلة حتى تكمل العدة. والخلاصة: تلاحظ خمسة أمور، المعتدة بالموت خمسة أمور تلاحظها: الأول: بقاؤها في بيت زوجها؛ الذي مات وهي ساكنة فيه، تبقى فيه حتى تكمل إذا تيسر ذلك، إذا أمكن ذلك، أما إذا كان لا يمكن؛ لأنه استأجر، وقد انتهت مدته، أو لأنها تستوحش، ما عندها أحد يسكن معها؛ تذهب إلى أهلها، ولا بأس بخروجها عند الحاجة إلى الطبيب، أو إلى المحكمة إن كانت هناك خصومة، أو لحاجتها، لا بأس، وترجع إلى بيتها. الأمر الثاني: تلبس الملابس العادية، التي ليس فيها جمال، ولا فتنة، سوداء أو خضراء أو غير ذلك، لا تختص في السوداء، ولو خضراء ولو صفراء، لكن غير جميلة. الثالث: عدم الطيب، لا بالبخور، ولا بالأطياب الأخرى، إلا إذا طهرت من الحيض، إذا كانت تحيض، إذا طهرت من الحيض، لا بأس أن تستعمل البخور عند طهرها من حيضها. الرابع: عدم الحلي، لا ذهب، ولا فضة، ولا ماس، لا أسورة، ولا قلائد، ولا خواتم، تجتنب هذا حتى تنتهي. الخامس: عدم التكحل والحناء حتى تنتهي من العدة. هذه خمسة أمور على المعتدة من الوفاة أن تلاحظها، وأما باقي الأمور من جنس الناس، لها أن تغير ثيابها متى شاءت، لها أن تغتسل متى شاءت، لها أن تغسل يعني: رأسها بالشامبو، بالسدر لا بأس، لها أن تمشي في حديقة بيتها، في سطوح بيتها، في القمراء، وغير القمراء، لها أن تمشي بالنعال، بالخفين، وغير الخفين، تمشي حافية، لا بأس. لها أن تكلم بالتلفون من تحتاج تكليمه، أو من كلام رجل أو امرأة، إذا كان في كلام مباح، لا بأس أن تكلم بالتلفون من يزهم عليها، إذا كان كلامه مباحًا، أما المغازلة مع الشباب، ومع الأجناب لا يجوز هذا، لا للمعتدة ولا غير المعتدة، حرام على الجميع، أما إذا تكلم يسألها عن شيء، أو يعزيها، أو يدعو لها، أو يسألها عن حاجة؛ لا بأس بذلك، وإن كان غير محرم، إذا كان كلامًا نزيهًا، ليس فيه محرم، أو يسلم عليها، أو لغير ذلك من الحاجات، أو هي تزهم على أحد، على أخيها، على أبيها، على شخص آخر، تسأله عن شيء، عن حاجة لا بأس بهذا، وفق الله الجميع. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10753/عدة-المتوفى-عنها-زوجها-وما-يجب-عليها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_456/45616.mp3","categories":["العِدَد"]},{"id":13103,"question":"ننتقل إلى رسالة السائلة التي رمزت لاسمها بـأم رشيد من اليمن، ومقيمة في مكة، تقول، تذكر: بأنها امرأة أرملة، توفي زوجها، وهي الآن في العدة، تقول: أريد من سماحتكم أن تخبروني ما الحكمة من مشروعية العدة للمتوفى عنها زوجها، وما العبرة من ذلك، مأجورين؟","title":"الحكمة من مشروعية العدة","answer":"الجواب:  الأقرب -والله أعلم- هو حماية المرأة، وصيانتها، أن يلحق بزوجها نسل من غيره، يعني: المرأة جعل الله العدة صيانة لها، وصيانة لزوجها من أن يلحق زوجها ولد ليس منه، فإذا بقيت في العدة حتى تكمل العدة؛ كان هذا من الدلائل على براءة رحمها، وأنها لم تحمل من الرجل إذ لو كان هناك حمل؛ بان في العدة، فإذا ظهر حمل بعد ذلك، اتضح أنه من غير زوجها؛ حتى لا يلحق به شيء من غيره. فالمرأة بعد الطلاق تعتد بثلاث حيض، وإذا كانت لا تحيض بثلاثة أشهر، والمتوفى عنها بأربعة أشهر وعشر إذا كانت غير حامل، فهي من باب إظهار الحزن على الزوج، والتأثر بموته، وصيانة المرأة أيضًا من أن يعتريها شيء يسبب إلحاق زوجها بولد ليس منه؛ لأنها لو تزوجت مبكرة لربما حملت من هذا، وادعت أنه من الأول، فيكون في ذلك إلحاق له بأولاد ليسوا منه. فالمقصود: أن الله -جل وعلا- شرع العدة لمصالح منها: التأثر بفراق الزوج، وأن يبقى فصل بينها وبين الزوج الآخر، ويكون هذا من حق الزوج الأول، ومن حريم نكاحه. ومنها: أن يكون ذلك صيانة لها عن أن يطأها أحد بعد ذلك بعقد بنكاح؛ فتشتبه الأمور في نكاح هذا وحملها. ومنها: أيضًا حماية الزوج الأول من أن يلحق به أولاد من غيره، ففيها مصالح كثيرة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11320/الحكمة-من-مشروعية-العدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_508/50812.mp3","categories":["العِدَد"]},{"id":13104,"question":"السائلة تقول: بأن إمام المسجد الذي بجوارنا أفتاني بأنه لا مانع من الكلام مع أخ زوجي وغيره، وأنا متحجبة الحجاب الشرعي، وهو الذي أمرني بأن أخرج في النهار عندما أكون متضايقة، بحيث أرجع قبل الغروب، ما رأيكم في هذا سماحة الشيخ؟","title":"حكم التحدث مع أخي الزوج، وخروج المعتدة من بيتها","answer":"الجواب:  لا بأس بالكلام مع أخ الزوج، وخال الزوج، وعمه، ونحو ذلك، لا حرج في ذلك مع البعد عن الفتنة، كونها تكلمه في حاجات وهي متحجبة، لا حرج في ذلك، والحمد لله، وكان المسلمون هكذا في عهد النبي ﷺ يكلم الرجل زوجة أخيه، ويكلم الرجل جارته وقريبته غير محرمه في الأمور التي يحتاجون إليها، مع النزاهة، والبعد عن أسباب الريبة. أما خروج المعتدة من بيتها؛ فهذا فيه تفصيل: إذا كان لحاجة، كخروجها إلى المستشفى، أو المحكمة، أو لأسباب أخرى؛ فلا بأس، تشتري حاجة من السوق، أما للنزهة، وسعة البال؛ ترك هذا أولى؛ لأن الرسول ﷺ قال للمعتدة: امكثي في بيتك؛ حتى يبلغ الكتاب أجله عدة الوفاة، يعني كونها تبقى في بيتها، وكذلك عدة الرجعية كونها لا تخرج إلا بإذنه -بإذن زوجها- هذا كله مشروع، واجب على المرأة، لكن خروجها للحاجة مثل: شراء حاجة من السوق .. مثل المستشفى .. مثل المحكمة؛ كل هذا لا بأس به، أما مزاورة الناس، لا، لأنها في العدة، والله قال: لا تُخْرِجُوهُنَّ مِنْ بُيُوتِهِنَّ وَلا يَخْرُجْنَ إِلَّا أَنْ يَأْتِينَ بِفَاحِشَةٍ مُبَيِّنَةٍ [الطلاق:1] إذا كانت عدة الرجعية. وهكذا عدة الوفاة الرسول ﷺ قال للمتوفى عنها: امكثي في بيتك حتى يبلغ الكتاب أجله فتبقى في البيت إلا إذا كان هناك حاجة؛ فلا بأس، حاجة من السوق، تشتري لها طعامًا.. تشتري حاجة لبهائمها .. تذهب المحكمة لأجل دعوى خصومة، تذهب إلى المستشفى لأجل الحاجة الطبية؛ ما في بأس. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11321/حكم-التحدث-مع-اخي-الزوج-وخروج-المعتدة-من-بيتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_508/50813.mp3","categories":["العِدَد","قضايا المرأة"]},{"id":13115,"question":"من اليمن يقول في هذا  سماحة الشيخ! أفتونا في رجل توفي وزوجته حامل، وظل الجنين في بطنها ثلاث سنوات، و متى تنتهي هذه العدة لهذه المرأة؟","title":"ما عدة من ظل الجنين في بطنها أكثر من تسعة أشهر؟","answer":"الجواب:  لا تزال في العدة ما دام الجنين في البطن، ما دام جنينها في بطنها معلوم، فهي لا تزال في العدة، ولو مكث ثلاث سنين، أو أربع سنين، ما دام موجودًا معلومًا أن عندها جنينًا، فعليها أن تتربص؛ لقول الله سبحانه: وَأُوْلاتُ الأَحْمَالِ أَجَلُهُنَّ أَنْ يَضَعْنَ حَمْلَهُنَّ [الطلاق:4] ولم يخصص  والجنين قد يتأخر لأسباب قد يبقى في البطن سنة سنتين أكثر لأسباب اقتضتها حكمة الله -جل وعلا- فعليها أن تصبر حتى تضع الحمل. المقدم: شكر الله لكم -يا سماحة الشيخ- وبارك الله فيكم، وفي علمكم، ونفع بكم المسلمين. الشيخ: وإياكم والمسلمين.","link":"https://binbaz.org.sa/fatwas/11332/ما-عدة-من-ظل-الجنين-في-بطنها-اكثر-من-تسعة-اشهر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_508/50821.mp3","categories":["العِدَد"]},{"id":13382,"question":"السائل (ع. ع. ح) من الرياض يقول: ما حكم خروج المرأة المحادة على زوجها ليلًا أو نهارًا إذا كان يوجد مناسبة لاجتماع الأقارب، كأيام الأعياد، ومناسبات الزواج؟ وما حكم مقابلة هذه المرأة للرجال؟ جزاكم الله خيرًا.","title":"حكم خروج المحادة من بيتها لغير ضرورة","answer":"الجواب: الواجب عليها بقاؤها في البيت حتى تكمل العدة، مثلما قال النبي ﷺ للمتوفى عنها: امكثي في بيتك حتى يبلغ الكتاب أجله ولا تخرج للمناسبات زيارات الناس، هذا هو الواجب عليها، ثم الخروج إلى الناس يفضي إلى تعاطيها الزينة، وتعاطيها الطيب، وهذا محرم، ممنوعة من الطيب والزينة، فعليها أن تلبس ملابس عادية، ليس فيها زينة، وعليها أن تجتنب الطيب، والحلي والكحل، والحناء، فهذا الخروج للمناسبات، والزواجات يفضي إلى الحلي، وإلى الطيب. فالمقصود: ليس لها الخروج إلا للحاجة، مثل: الخروج لحاجاتها من السوق، تجيب حاجة من السوق ... خبزة من السوق.. حاجة من السوق.. تذهب إلى المستشفى عند الحاجة.. إلى المحكمة عند الحاجة لا بأس. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11675/حكم-خروج-المحادة-من-بيتها-لغير-ضرورة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_515/51509.mp3","categories":["العِدَد","قضايا المرأة"]},{"id":13434,"question":"السائل من اليمن ومقيم بالمملكة العربية السعودية يقول: امرأة طلقت من زوجها، ولم يدخل بها، هل لها عدة، أم لا؟","title":"هل المطلقة غير المدخول بها عليها عدة؟","answer":"الجواب: إذا كان الزوج لم يدخل بالزوجة، ولا خلا بها؛ ما عليها عدة؛ لقول الله -جل وعلا-: يَا أَيُّهَا الَّذِينَ آمَنُوا إِذَا نَكَحْتُمُ الْمُؤْمِنَاتِ ثُمَّ طَلَّقْتُمُوهُنَّ مِنْ قَبْلِ أَنْ تَمَسُّوهُنَّ فَمَا لَكُمْ عَلَيْهِنَّ مِنْ عِدَّةٍ تَعْتَدُّونَهَا [الأحزاب:49] هذا محل إجماع بين أهل العلم، إذا عقد عقدًا، ولم يخل، ولم يطأ، ثم طلق؛ فليس عليها عدة. أما إذا مات عنها؛ فعليها العدة.. الموت، إذا مات عنها ولو ما دخل بها، ولا خلا بها؛ عليها عدة الوفاة أربعة أشهر وعشرًا، أما الطلاق إذا طلق، ولم يخل بها، ولم يدخل بها -يعني: لم يطأها- فإنه لا عدة عليها، لها أن تتزوج في الحال بعد طلاقه لها، ليس لها عدة، نعم.  إذا كان لم يدخل بها، ولم يخل بها خلوة خاصة، يعني: يغلق عليهم الباب، خلوة تامة، بحيث يغلق عليهما الباب حتى يتمكن من جماعها لو أراد. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11729/هل-المطلقة-غير-المدخول-بها-عليها-عدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_527/52708.mp3","categories":["العِدَد","قضايا المرأة"]},{"id":13438,"question":"يقول هذا السائل من اليمن: سماحة الشيخ! عندنا عادة يا فضيلة الشيخ وهو أن المرأة المتوفى عنها زوجها إذا كانت في نصف العدة، وشاهدها أحد الرجال الأجانب، أو هي شاهدت أحد الأجانب؛ فإنها تعود من بداية العدة من جديد، فما رأيكم في ذلك، وهل من كلمة يا سماحة الشيخ؟","title":"هل تعيد المعتدة العدة إذا شاهدت أجنبي أو شاهدها؟","answer":"الجواب: هذا خطأ، هذا غلط لا وجه له، لو شاهدها أجنبي، أو شاهدت أجنبيًا فليس عليها إعادة العدة، عليها التكميل فقط، والمشاهدة للأجنبي إذا كان مع الحجاب لا حرج فيه، كونها تشاهده ترد عليه السلام، يسلم عليها كابن عمها، كأحد جيرانها لا بأس، يسلم عليها، يعزيها، يسألها عن حاجة، تسأله عن حاجة، لا حرج في ذلك، ولكن مع الستر، مع الحجاب وعدم الخلوة. وهذا الذي يقوله بعض الناس هي خرافات من خرافات العامة، كونها تعيد العدة من أولها؛ لأنها شاهدت رجلًا، أو كلمته، أو شاهدها؛ كل هذا غلط، وهكذا الصبي لو دخل عليها صبي يكلمها، أو كلمته، ولو كان قد راهق اثنا عشر، أو ثلاثة عشر حول الحلم، لها أن تكلمه، وله أن يكلمها، ولكن الحجاب إنما يجب بعد البلوغ؛ لأن الله يقول: وَإِذَا بَلَغَ الأَطْفَالُ مِنْكُمُ الْحُلُمَ فَلْيَسْتَأْذِنُوا [النور:59] فإذا كان مراهقًا، وظنت أنه قد احتلم، أو قارب الاحتلام، فالحجاب عنه أحوط؛ لأنه مظنة الاحتلام. نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11735/هل-تعيد-المعتدة-العدة-اذا-شاهدت-اجنبي-او-شاهدها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_527/52710.mp3","categories":["العِدَد","قضايا المرأة"]},{"id":13513,"question":"يقول السائل عبدالرحيم في ثاني أسئلته: المرأة المتوفى عنها زوجها، وهي حامل، ثم وضعت، هل عليها عدة؟","title":"هل المتوفى عنها زوجها وهي حامل ثم وضعت، عليها عدة؟","answer":"الجواب: نعم، إذا توفي عنها، أو طلقها وهي حامل؛ عدتها بقية الحمل، فإذا وضعت؛ خرجت العدة، سواء كانت مطلقة، أو مخلوعة، أو مات عنها، عدتها وضع الحمل؛ لقول الله سبحانه: وَأُوْلاتُ الأَحْمَالِ أَجَلُهُنَّ أَنْ يَضَعْنَ حَمْلَهُنَّ [الطلاق:4] هذا يعم المطلقة، والمخلوعة، والمتوفى عنها، متى وضعت الحمل؛ خرجت من عدة زوجها، سواء كان حيًا، أو ميتًا، إذا طلقها، أو خالعها، طلقها على مال، أو مات عنها، متى وضعت؛ خرجت من العدة، نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11826/هل-المتوفى-عنها-زوجها-وهي-حامل-ثم-وضعت-عليها-عدة ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_518/51814.mp3","categories":["العِدَد","قضايا المرأة"]},{"id":13728,"question":"هذه السائلة التي رمزت لاسمها بـ (أ. أ) تقول: امرأة توفي زوجها وهي في العدة، فكانت عازمة على الحج، وقد حجت وهي في العدة، فهل حجها صحيح؟","title":"حكم حج المعتدة","answer":"الجواب: حجها صحيح، لكنها أخطأت، الواجب عليها عدم الخروج، تبقى في بيتها حتى تكمل عدة الوفاة، لكن لو حجت، أو خرجت تأثم، وإن كانت جاهلة؛ نسأل الله أن يعفو عنها، والحج صحيح.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12099/حكم-حج-المعتدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_545/54515.mp3","categories":["العِدَد"]},{"id":13906,"question":"المسألة الأخيرة في رسالة السائل من الجزائر يقول: رجل طلق زوجته ثلاثًا ثم مات عنها وهي ما زالت في عدتها، أتعتد عدة وفاة؟ أم عدة طلاق؟","title":"من طلق زوجته ثم مات ما العدة التي تعتدها؟","answer":"الجواب: هذا يرفع إلى المحكمة والمحكمة تحكم في ذلك، يرفع الأمر للمحكمة في شأن العدة والإرث. نعم.\nالمقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/12300/من-طلق-زوجته-ثم-مات-ما-العدة-التي-تعتدها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_538/53818.mp3","categories":["العِدَد"]},{"id":13909,"question":"المسألة الأخيرة في رسالة السائل من الجزائر يقول: رجل طلق زوجته ثلاثًا ثم مات عنها وهي ما زالت في عدتها، أتعتد عدة وفاة؟ أم عدة طلاق؟","title":"من طلق زوجته ثم مات ما العدة التي تعتدها؟","answer":"الجواب: هذا يرفع إلى المحكمة والمحكمة تحكم في ذلك، يرفع الأمر للمحكمة في شأن العدة والإرث. نعم.\nالمقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/12300/من-طلق-زوجته-ثم-مات-ما-العدة-التي-تعتدها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_538/53818.mp3","categories":["العِدَد"]},{"id":14031,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من السودان، باعثها مستمع من هناك يقول: اسمي محمد علي محمد علي ، أخونا له جمع من الأسئلة؛ ففي أحد أسئلته يقول: إذا توفي زوج المرأة - وكما تعلمون - تقضي حدادًا مدته أربعة أشهر وعشرة أيام في المنزل، وقبل انقضاء المدة خرجت وقابلت أي شيء إن كان حيوان أو إنسان، هل يموت ذلك الشيء؟ وجهونا ووجهوا الناس حول هذه العادات، جزاكم الله خيرًا.","title":"هل يتضرر من تقابله المحادة؟","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فلا شك أن الواجب على المرأة إذا توفي زوجها أن تحد عليه أربعة أشهر وعشرًا كما نص الله على ذلك في كتابه الكريم، وهي مائة وثلاثون يومًا بلياليها، إلا إذا ثبت أن بعض الشهور نقص وصار تسعًا وعشرين فإنه يحسب لها إذا ثبت بالبينة إلا أن تكون حاملًا فإن عدتها وضع الحمل ولو بعد الموت بدقائق أو ساعات لقول الله : وَأُوْلاتُ الأَحْمَالِ أَجَلُهُنَّ أَنْ يَضَعْنَ حَمْلَهُنَّ[الطلاق:4].  ولها الخروج لحاجتها للسوق أو حاجات البيت وكحاجتها إلى الطبيب.. ونحو ذلك من الحاجات التي تدعو إلى خروجها لا بأس مع التحجب والتزام الأدب الشرعي من عدم التعطر كغيرها من النساء في خروجهن يخرجن متسترات غير متعطرات بعيدات عن أسباب الفتنة. أما زعم من قال من العامة: أنها إذا قابلت أحدًا قبل خروجها يموت فهذا قول باطل، هذا لا أساس له بل هو باطل ومن الخرافات التي لا أساس لها، فهي كسائر النساء إذا خرجت لا شيء في ذلك ولا تضر أحدًا، ولكنها تلزم البيت لا تخرج إلا من حاجة، وإذا خرجت للحاجة لا تضر أحدًا لا حيوانًا ولا غيره، وهي عليها أن تراعي خمسة أمور:\nالأمر الأول: بقاؤها في البيت اللي مات زوجها وهي ساكنة فيه تبقى فيه مدة العدة، لقول النبي ﷺ لفريعة بنت مالك لما توفي زوجها: امكثي في بيتك حتى يبلغ الكتاب أجله، لكن لا حرج في خروجها الخروج المعتاد لحاجاتها أو للطبيب أو لدعوى في المحكمة أو نحو ذلك، وإذا خرجت تخرج كسائر النساء المؤمنات متسترة متحجبة تاركة لأسباب الفتنة من التعطر وغيره.\nالأمر الثاني: أن تلبس الملابس العادية التي ليس فيها فتنة، تلبس ملابس عادية ليست جميلة؛ سوداء أو خضراء أو غير ذلك والمهم أن تكون عادية ليس فيها فتنة، ولا يتعين أن تكون سوداء، بل تلبس السوداء وغير السوداء كالخضراء والحمراء ونحو ذلك لكن من الملابس التي ليس فيها فتنة.\nالأمر الثالث: اجتناب الطيب، فعليها أن تبتعد عن الطيب ولا تمس الطيب سواء كان بخورًا أو غيره إلا إذا طهرت من حيضها فلا مانع أن تمس البخور وأن تتبخر كما صحت بذلك السنة عن النبي ﷺ من حديث أم عطية وذلك يختص بطهرها من حيضها وبالبخور.\nالرابع: عدم الحلي، لا تلبس الحلي من الذهب والفضة والماس ونحو ذلك؛ لأن لبس الحلي قد يسبب الفتنة للرجال بها يعني: قد يفتن بها الرجال ويحرصوا على خطبتها وهي في العدة أو على أمر آخر من الشر.\nالأمر الخامس: تجنبها الكحل والحناء، فإن المحادة لا تكتحل ولا تتعاطى الحناء؛ لأن ذلك من أسباب الفتنة ومن الزينة الظاهرة، هذه الأمور الخمسة على المحادة أن تلاحظها وتعتني بها حتى تكمل عدتها، ولا بأس أن تخدم في بيتها وأن تخدم أولادها، وأن تخرج إلى حديقة البيت وسطح البيت في الليل والنهار وفي القمراء وغير القمراء كل ذلك لا بأس به، ولها أن تغير ملابسها متى شاءت وتغتسل متى شاءت ولا يختص ذلك بالجمعة ولا بغيرها بل مثل سائر النساء تغتسل متى شاءت وتغير ثيابها متى شاءت وتغتسل بالماء والسدر لا بأس والشامبو ونحو ذلك، ولا تمس الطيب كما تقدم، وفق الله الجميع. نعم.\nالمقدم: اللهم آمين، جزاكم الله خيرًا، إذًا ليس عليها أن تلتزم بملابس ذات لون معين كما يشير أخونا يقول: إنهم يلزمونها بلبس الملابس البيضاء طوال فترة الحداد؟\nالشيخ: لا، غلط، لا يلزمها لباس معين تلبس السواد والبياض الذي ليس فيه مشابهة للرجال وتلبس الأخضر والأصفر.\nالمقصود تلبس الملابس النسائية التي ليس فيها تشبه بالرجال ولكنها تكون ملابس غير جميلة وغير لافتة للنظر.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12449/هل-يتضرر-من-تقابله-المحادة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_612/61201.mp3","categories":["العِدَد","قضايا المرأة"]},{"id":14055,"question":"تسأل أختنا وتقول: إذا رأى رجل امرأة كاشفة بدون قصد، وهي في فترة حداد على ميت (على زوجها)، فماذا يلحقها في ذلك؟ هل عليها إعادة الحداد؟","title":"ما يلزم المحادة إذا نظر إليها رجل بغير قصد؟","answer":"الجواب: إذا رأى الرجل المرأة وهي سافرة؛ فإنه يغض بصره، ويصرف بصره عنها، وقد سئل النبي ﷺ عن نظر الفجأة فقال: اصرف بصرك، وقال: إن لك الأولى، وليست لك الأخرى، والمعنى: أنه لا حرج عليه في الأولى التي نظرها صدفة لم يقصدها، وإنما صادفها من باب خارجة، أو من باب وهو داخل، أو من طريق؛ فإنه يصرف بصره ولا يتبع النظرة النظرة، بل يغض بصره.\nأما المحادة وغيرها من النساء، فليس عليها شيء في ذلك إذا لم تتبع النظر النظر، بل تغشت واحتجبت، وليس عليها أن تعيد ما مضى من الإحداد، بل تستمر في إحدادها ولا شيء عليها، إلا أنه يلزمها أن تبتعد عن أسباب الفتنة، وأن تحتجب عن الرجال الأجانب، مثل غيرها من النساء سواء بسواء، ليس هذا خاصًا بالمحادة، ولكنها كغيرها من النساء، عليها الاحتجاب والبعد عن أسباب الفتنة، وعليها أن تراعي، المحادة عليها أن تراعي خمسة أمور:\nالأمر الأول: بقاؤها في البيت الذي مات زوجها وهي ساكنة فيه، إذا كان صالحًا تبقى فيه، أما إذا لم يتيسر بقاؤها فيه؛ لخرابه، أو لأن أهله أبوا أن يؤجروه بعدما تمت الأجرة، أو لأنه ليس لديها من يؤنسها فيه بعد موت زوجها تخاف على نفسها؛ تخرج إلى أهلها أو إلى مكان سليم.\nالشرط الثاني: أن تلبس الملابس العادية دون الملابس التي تفتن، فلا تلبس الملابس الجميلة، ولكن تتحرى الملابس التي لا تفتن، وهي الملابس العادية من سوداء أو خضراء أو غيرها، لكن ليس فيها ما يفتن الناس.\nالثالث: اجتناب الحلي من الذهب والفضة والماس ونحو ذلك.\nالرابع: عدم الطيب والبخور وسائر أنواع الطيب؛ لأن الرسول نهى عن ذلك، نهى المحادة عن ذلك عليه الصلاة والسلام.\nالخامس: عدم الكحل والحناء ونحوهما؛ لأن ذلك من أسباب الفتنة أيضًا.\nفهذه الأمور الخمسة يشرع للمحادة العناية بها، بل يجب عليها ذلك، أما ما سوى ذلك فهي مثل بقية النساء، لها أن تغتسل وتتروش متى شاءت، في الجمعة وغيرها، ولها أن تغير ثيابها متى شاءت، ولها أن تكلم من شاءت من النساء والرجال، مباشرة أو من طريق الهاتف، أو من طريق المكاتبة؛ لا حرج في ذلك إذا كانت المكالمة ليس فيها فتنة ولا ريبة، بل تكلم لحاجتها، وترد السلام على من سلم عليها، ونحو ذلك على وجه ليس فيه فتنة وليس فيه شبهة. نعم.\nالمقدم: جزاكم الله خيرًا، سنعود إلى بقية أسئلتك يا أم أحمد في حلقة قادمة إن شاء الله تعالى.","link":"https://binbaz.org.sa/fatwas/12476/ما-يلزم-المحادة-اذا-نظر-اليها-رجل-بغير-قصد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_608/60802.mp3","categories":["العِدَد"]},{"id":14355,"question":"ما المقصود بعدة المرأة؟ مع شرح الحالات التي تعتد فيها المرأة، يا سماحة الشيخ.","title":"المقصود بعدة المرأة وبيان الأحوال التي تعتد فيها","answer":"الجواب: العدة يعني: انحباسها عن الزواج في الأيام التي تنحبس فيها عن التزوج، لا يحل فيها أن تتزوج حتى تنتهي، هذه يقال لها: عدة، سواء كان من طلاق، أو من خلع، أو من موت، تسمى العدة، كما في قوله -جل وعلا-: وَبُعُولَتُهُنَّ أَحَقُّ بِرَدِّهِنَّ [البقرة:228] يعني: في العدة، وقال تعالى: وَالْمُطَلَّقَاتُ يَتَرَبَّصْنَ بِأَنفُسِهِنَّ ثَلاثَةَ قُرُوءٍ [البقرة:228] .... هذه العدة، يقال في اليائسات: وَاللَّائِي يَئِسْنَ مِنَ الْمَحِيضِ مِنْ نِسَائِكُمْ إِنِ ارْتَبْتُمْ فَعِدَّتُهُنَّ ثَلاثَةُ أَشْهُرٍ وَاللَّائِي لَمْ يَحِضْنَ [الطلاق:4] فالعدة: هي التربص بعد الطلاق، أو بعد الموت، أو بعد المخالعة، يقال لها: عدة.\nفالطلاق ثلاث حيض إذا كانت تحيض، أو ثلاثة أشهر إن كانت يائسة لا تحيض أو صغيرة.  والوفاة أربع أشهر وعشر إن لم تكن حاملًا، فإن كانت حاملة فبوضع الحمل.  والخلع مثل المطلقة ثلاث حيض، ويجوز أن تعتد بحيضة واحدة على الصحيح، لكن إذا اعتدت بثلاث حيض يكون أحوط.  والخلع هو أن يطلقها على مال، تعطيه مالًا حتى يطلقها، أو يخالعها، يقال لها: مخلوعة، إذا طلقها على مال دفعته إليه، فإن طلقها بلفظ الطلاق طلقة واحدة، مثل المطلقة تعتد ثلاث حيض، وإن اعتدت بحيضة أجزأت عند جمع من أهل العلم، لكن الأفضل والأحوط ثلاث حيض؛ لأنها اشترت نفسها، فأشبهت الجارية تعتد بحيضة، تشبيه المسبية أو المشتراة تستبرأ بحيضة، فالمخلوعة تشبهها؛ ولهذا جاء في حديث امرأة ثابت بن قيس أن النبي ﷺ أمرها أن تعتد بحيضة لما اختلعت منه، وأعطته ماله، ولكن كونها تعتد بثلاث حيض أولى وأحوط خروجًا من الخلاف، وحرصًا على براءة الرحم، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12828/المقصود-بعدة-المراة-وبيان-الاحوال-التي-تعتد-فيها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_551/55104.mp3","categories":["العِدَد","قضايا المرأة"]},{"id":14954,"question":"سؤاله الثاني تقول: أفيدكم أنه مات زوجي منذ خمسة عشرة سنة، وقد حديت عليه مثلما يفعل النساء عندما يموت أزواجهن، تقول: هذا وأنا بدوية في الصحراء، وعندنا غنم، فكنت أقوم برعيها، وأقوم بالبحث عنها عندما تضيع واحدة منها، وأنا في الحداد، وكان عندنا جيران وعندي أولاد، وكنت دائمًا أرفع الصوت: تعال يا فلان، واذهب يا فلان، وكان بيت أخو زوجي قريب منا، وكانوا يدعونني للقهوة، فأجلس معهم، وأتناول القهوة، فما حكم ذلك؟ وهل يلزمني شيء بعد هذه المدة؟","title":"حكم رفع المعتدة صوتها لنداء أولادها وخروجها للحاجة","answer":"الجواب: أما ما يتعلق بالكلام ونداء الأولاد، فهذا لا بأس به، ولو سمعها الجيران، لا حرج في ذلك، كذلك مسألة رعاية الغنم إذا كانت قريبة من البيت وحول البيت لا تذهب بعيدًا، إنما هي حول البيت؛ فالأمر في هذا واسع -إن شاء الله-، أما كونها تذهب بعيدًا لطلب الضالة والغائبة من الغنم، هذا لا ينبغي للمحادة، المحادة تلزم بيتها، لكن الخروج اليسير لجمع الغنم حول البيت في النهار أمره واسع وسهل فيما يتعلق بالبادية، وكذلك كون بيت أخي زوجها يليها، فربما تزورهم الأمر فيه واسع، ولو أنها جلست في بيتها ولم تذهب كان أحوط؛ لأن الرسول ﷺ قال: امكثي في بيتك حتى يبلغ الكتاب أجله فلو أنها بقيت في البيت، ولم تذهب إلى الجيران في زيارة كان هذا أحوط، ولكن -إن شاء الله- لا يضر ذلك، وليس عليها شيء؛ لكونهم متقاربين ومتجاورين في الصحراء، فهذا لا يضرها شيء، لكنها في المستقبل لو قدر أنها حدت على غيره، أو سئلت عن هذا الشيء من جيرانها، أو نحو ذلك فينبغي للمحادة أن تبقى في بيتها، وأن تلزم بيتها، إلا من حاجة مثل تذهب تشتري حاجة، أو للطبيب أو تأتي بالغنم من المرعى القريب الذي ما فيه ما يسمى سفر وهو قريب من البيت، هذه أمور خفيفة مثل خروجها لحاجتها للسوق تشتري خبزها أو تأتي طعامًا لبيتها، هكذا رد الغنم التي حول البيت، وتجيبهم من المرعى القريب الذي لا يعد سفرًا بل هو قريب، كل هذا لا بأس به -إن شاء الله-. وصوتها كذلك تكلم الرجال، أو ترفع صوتها على أولادها، تعال يا فلان، واذهب يا فلان، كل هذا لا حرج فيه، أما الشيء البعيد الذي تدور الضالة في محل بعيد، قد يتعرض لها خطر، أو قد يعد سفرًا هذا لا. لا يصلح، وعليها التوبة مما فعلت من ذلك إذا كان شيئًا بعيدًا، نعم.","link":"https://binbaz.org.sa/fatwas/13451/حكم-رفع-المعتدة-صوتها-لنداء-اولادها-وخروجها-للحاجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_648/nour_64804.mp3","categories":["العِدَد","قضايا المرأة"]},{"id":15332,"question":"هذا سؤال من السائلة أم خالد، من طريف بالمنطقة الشمالية، تقول: توفي والدي منذ سنتين تقريبًا، ولكن المشكلة في زوجته التي هي والدتي فقد استمر حزنها عليه، ربما إلى هذا الوقت مما جعلها ترفض تغيير اللباس الأسود أو التزين بأي زينة أقلها وضع الكحل في العين أو الحناء، وقد بذلنا كل ما نستطيع في سبيل إقناعها بترك هذا المظهر الحزين، ولكن دون جدوى، فنرجو منكم توضيح المشروع في هذا الموضوع. جزاكم الله خير الجزاء.","title":"حكم إحداد المرأة على زوجها أكثر من العدة","answer":"الجواب: هذا لا يجوز، كونها تبقى على حزنها، أو على لباس الإحداد هذا لا يجوز، الواجب عليها اتباع الشرع، وترك طاعة الشيطان، فكونها تبقى على حالة الإحداد، هذا من طاعة الشيطان، وفيه نوع من السخط للمصيبة والجزع، والواجب عليها عدم ذلك، فالنبي ﷺ حث على الصبر والاحتساب، كما حث الله عليه في كتابه العظيم، قال: وَبَشِّرِ الصَّابِرِينَ ۝ الَّذِينَ إِذَا أَصَابَتْهُمْ مُصِيبَةٌ قَالُوا إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ ۝ أُوْلَئِكَ عَلَيْهِمْ صَلَوَاتٌ مِنْ رَبِّهِمْ وَرَحْمَةٌ وَأُوْلَئِكَ هُمُ الْمُهْتَدُونَ [البقرة:157] الله يقول -جل وعلا-: مَا أَصَابَ مِنْ مُصِيبَةٍ إِلَّا بِإِذْنِ اللَّهِ وَمَنْ يُؤْمِنْ بِاللَّهِ يَهْدِ قَلْبَهُ [التغابن:11] قال بعض السلف: هو الرجل يعني: معناه أو المرأة تصيبه المصيبة، فيعلم أنها من عند الله، فيرضى ويسلم. فالواجب عليها الصبر والاحتساب، وأن تغير من حالها، تلبس الملابس الجميلة، تكحل عينيها، تتطيب، تخرج إلى جيرانها وأقاربها الطيبين، تزور من تحسن زيارته، تترك هذا الأمر الرديء الذي هو طاعة للشيطان، وإظهار للجزع والسخط هذا لا يجوز، فعليكم أن تنصحوها، وأن توجهوها إلى الخير، وأن تخبروها بهذا الكلام الذي سمعتم، أخبروها بهذا الكلام، أو سجلوه، واقرؤوه عليها، سجلوا هذا الكلام واقرؤوه عليها، حتى تستفيد، وحتى تبتعد عن طاعة الشيطان، هدانا الله وإياها صراطه المستقيم.","link":"https://binbaz.org.sa/fatwas/13841/حكم-احداد-المراة-على-زوجها-اكثر-من-العدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_677/nour_67710.mp3","categories":["العِدَد","قضايا المرأة"]},{"id":15340,"question":"سؤاله الثاني يقول: إذا طلق الرجل امرأته طلقة واحدة شرعية، ولم يراجعها قبل أن تنقضي عدتها، ولكنه أراد مراجعتها، فقام وليها بدعوى ومشكلات بغية انتهاء العدة؛ لكيلا أسترجعها إلا بعقد جديد، وينال هدفه من ذلك، فما الحكم؟جزاكم الله خيرًا.","title":"حكم منع ولي المرأة الزوج من مراجعة زوجته","answer":"الجواب: الواجب على الولي أن يساعد على الخير، وألا يقف حجر عثرة في طريق الرجعة، الزوج له أن يراجع ما دامت في العدة، ولم يطلقها إلا طلقة واحدة، أو ثنتين، له أن يراجع، ويشهد شاهدين على الرجعة، شاهدين عدلين على الرجعة، وتثبت له الرجعة، وإن عارضه وليها، وإن أبى عليه وليها، فإنه لا يضره ذلك، فعليه أن يشهد شاهدين عدلين: أني راجعت زوجتي فلانة، ما دامت في العدة، وتبقى زوجة له بهذه المراجعة. وعلى وليها أن يتقي الله، وأن يمكن الرجل من زوجته إذا كانت الزوجة راضية بذلك، أما إن كانت الزوجة آبية، وهناك خصومة، فهذه ترجع إلى المحاكم، تراجع المحكمة هو وزوجته ووليها، والحاكم ينظر في الأسباب التي أوجبت النزاع، أما إذا كانت المرأة راضية، والعدة لم تنته، والطلاق واحدة، أو ثنتين، فإنه يراجعها، ولو لم يرض الولي، ولو لم ترض هي أيضًا، يشهد شاهدين أنه راجعها ما دامت في العدة، والطلاق واحدة، أو ثنتان، له أن يراجع في هذه الحال، وتثبت الرجعة، وإن لم ترض الزوجة، وإن لم يرض الولي، إذا أشهد شاهدين بذلك، أو اعترفت المرأة بذلك، والولي ليس له أن يعارض بغير وجه شرعي، فعليه أن يساعد على الخير، وليس له المعارضة إلا بوجه شرعي، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/13848/حكم-منع-ولي-المراة-الزوج-من-مراجعة-زوجته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_678/nour_67803.mp3","categories":["الرجعة","العِدَد"]},{"id":15590,"question":"هذا سؤال من المستمع إبراهيم بيومي سرور، من جمهورية مصر العربية، يقول: أنا رجل متزوج، وقد حصلت مشكلة مع زوجتي، فقلت لها: علي الطلاق لا تكوني امرأتي من هذه الساعة، ثم سافرت وبعد مضي خمسة أشهر، بعثت لي والدتي برسالة تخبرني فيها بأنها أعادت زوجتي إلى البيت. علمًا أن والدها هو الذي يريد طلاقها، فهل يصح أن أسترجعها بدون عقد جديد، أم لا بد من تجديد العقد؟","title":"حكم استرجاع المطلقة بعد مضي خمسة أشهر","answer":"الجواب: إذا كان الطلاق المذكور هو الطلقة الأولى أو الثانية؛ فلا بأس باسترجاعها في العدة، ما دامت في العدة قبل أن تمر عليها ثلاث حيض، فإن مر عليها ثلاث حيض قبل الرجعة؛ بانت بينونة صغرى، لا يحلها إلا العقد الجديد.  وأما إن كانت الطلقة هذه آخر ثلاث؛ فليس لك مراجعتها إلا بعد زوج حتى تنكح زوجًا غيرك؛ لقول الله سبحانه: فَإِنْ طَلَّقَهَا فَلا تَحِلُّ لَهُ مِنْ بَعْدُ حَتَّى تَنكِحَ زَوْجًا غَيْرَهُ [البقرة:230]. فالمقام مقام تفصيل، ولعل السائل قد فهم ما ذكرنا، فالطلقة المذكورة إن كانت هي الأولى أو الثانية فلا مانع من رجعة الزوجة ما دامت في العدة، لم يمر عليها ثلاث حيض إن كانت تحيض أو ثلاثة أشهر إن كانت لا تحيض، كالآيسة الكبيرة والصغيرة التي لم تحض، فإن عدتها ثلاثة أشهر، وله أن يعيدها بعد العدة بعقد جديد، يعني: بزواج جديد، ومهر جديد إذا كانت الطلقة الواقعة هي الأولى أو الثانية. أما إن كانت الطلقة الواقعة هي الثالثة؛ فإنها تحرمها عليه تحريمًا معلقًا بزواجها شخصًا آخر، ويطؤها، ثم يفارقها بموت أو طلاق، لكن لا بد يكون الزواج شرعيًا أيضًا، الزواج الجديد شرعيًا، فإذا تزوجها محلل لا يجوز ولا تحل، فلا بد أن يكون الزوج الذي ينكحها بعد الطلقة الثالثة زوجًا شرعيًا أراد الرغبة فيها إن ناسبته، ولم يرد تحليلها للسابق، ولا بد أيضًا من كونه يطؤها، فلو طلقها أو مات عنها قبل أن يطأ لم تحل للزوج الأول. ويراعى في هذا ما تقدم إذا كانت الطلقة في طهر جامعها فيه، أو في حيض أو نفاس لم تقع على الصحيح، أما إن كان طلقها وهي حامل، أو في طهر ما جامعها فيه؛ فإن الطلقة تقع سواء كانت أولى أو ثانية أو ثالثة، نعم.\nالمقدم: هو يقول: إن والدته استرجعتها بعد مضي خمسة أشهر، فمعنى هذا إذا كانت من اللواتي لا يحضن، فتكون قد خرجت من العدة.\nالشيخ: إذا كان بعد خمسة أشهر، نعم، قد خرجت من العدة بلا شك يقينًا، أما التي تحيض، فيحتمل أن تكون مرت عليها ثلاث حيض، وهو الغالب، ويحتمل أنها لم تمر عليها الحيضة الثالثة؛ لأن بعض الحيض قد يتأخر، بعض النساء قد يتأخر حيضها عدة أشهر أو سنة، فإذا كان تأخر عليها الحيض أو تأخرت الحيضة الثالثة بعد الأشهر الخمسة؛ فله الرجعة إذا شاء، نعم.\nالمقدم: وإذًا العبرة بالحيض لا بمرور الأشهر أو بعدد الأشهر؟ الشيخ: نعم إذا كانت تحيض فالعبرة بالحيض.\nالمقدم: إذا كانت تحيض.\nالشيخ: العبرة بالحيض، نعم. المقدم: جزاكم الله خير الجزاء.","link":"https://binbaz.org.sa/fatwas/14128/حكم-استرجاع-المطلقة-بعد-مضي-خمسة-اشهر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_704/nour_70404.mp3","categories":["الرجعة","العِدَد"]},{"id":15983,"question":"هذه رسالة من السائلة هيام هشام غولي، من العراق، محافظة البصرة، في الواقع رسالتها مطولة، ولكن لا تتضح الصورة إلا بقراءتها، تقول:طلقني زوجي وأنا في بداية الشهر التاسع من الحمل عند قاضي المحكمة الشرعية في بلدنا، وردد زوجي صيغة الطلاق بعد القاضي، ومن ضمن هذه الصيغة أنه قال: طلقة واحدة رجعية، ثم بعد مضي ثمانية عشر يومًا من الطلاق وضعت حملي البكر، ثم ذهبنا أنا ووالدتي وزوجي إلى الشيخ لترديد صيغة الطلاق ثانية عنده؛ لأننا لا نبقي على عقد المحكمة، أو طلاقها إلا بعد ترديد الصيغة عند الشيخ، بالرغم من أن الصيغتين لا تختلفان جوهريًا عن بعضهما، إلا أن صيغة الشيخ تكون مطولة أكثر من لفظ القاضي، المهم أننا ذهبنا إلى الشيخ، وهو شيخ جليل، لا أشك في نزاهته، وقبل أن يطلقني سألني عما إذا كنت قد وهبت لطليقي شيئًا من مهري المؤجل، فأجبته بنعم، وأنا بالفعل قد فعلت ذلك مقابل استلام الباقي نقدًا، فعندها قال الشيخ: إذًا طلاقكما يكون خلعيًا، وفعلًا طلقني منه خلعيًا، بالرغم من كراهيتنا نحن الزوجين أنا ووالد طفلي لهذا الطلاق الخلعي، ثم صدقنا ورقة الطلاق التي أخذتها من الشيخ داخل المحكمة واعترفت المحكمة بخلعية طلاقنا، واعتبرته بائنًا بينونة صغرى حسبما ورد في مضمون ورقة الطلاق المصدقة. وسؤالي: إن زوجي يرغب في رجوعي له، وأنا كذلك، خاصة وفي رجوعنا حفاظًا على مستقبل ابننا الوحيد، فهل يجوز لي أن أرجع له بالرغم من أن الشيخ طلقنا خلعيًا بعد طلاق المحكمة التي كانت صيغته عبارة عن طلقة واحدة رجعية، مع أن المدة بين الطلاقين كانت ثمانية عشرة يومًا، ولم يرجعني زوجي خلالها، وإنما بقيت مطلقة وملتزمة بالعدة إلى أن وضعت حملي، ثم ذهبنا للشيخ كما بينت سابقًا؟ وإذا كان لا يجوز لي الرجوع لطليقي إلا بعد الزواج بآخر وتطليقي منه، فهل يجوز لي أن يكون هذا الزواج صوريًا فقط، ويستمر لمدة قصيرة بعد العقد، ثم يحدث الطلاق؟ وإذا كان هذا أيضًا لا يجوز فهل يجوز لي أن أرجع لوالد طفلي مباشرة دون التزوج بآخر مقابل إعطائي كفارة أو مقابل صيام أو أي عمل آخر ترشدونا إليه؟أفيدوني -أحسن الله لكم- فمستقبلي وطفلي متوقف على إجابتكم التي أتمنى من الله أن تكون واضحة مبينة كعهدي بإجاباتكم السليمة، ومهما تكن الإجابة فإني لا أجرؤ أن أتعدى حدود الله ، علمًا أنني قد التزمت بالعدة إلى أن وضعت حملي على حسب طلاق المحكمة، ولم ألتزم بالعدة بعد طلاق الشيخ، ولكن عند تصديق ورقة الطلاق المأخوذة من السيد في المحكمة جاء فيها أن علي التزام العدة الشرعية، وحدد تاريخها من تاريخ الطلاق، ولكني لم ألتزم بها، فهل علي كفارة إن وجبت هذه العدة؟","title":"عدة الحامل والفرق بين البينونة الصغرى والكبرى","answer":"الجواب: هذا الطلاق يتعلق بالمحكمة، والمحكمة تنظر في الأمر، وهي أعلم بالواقع، ما دام صدر منها الصك، وتولت النظر في الموضوع فهي التي تراجع في هذا، أنت -أيها السائلة- وزوجك تراجعان المحكمة، وتنظر المحكمة فيما يحل ويحرم، وفيها الكفاية والبركة -إن شاء الله-. ومن المعلوم أن الطلاق إذا كان قبل وضع الحمل، ولم يراجع الزوج فإن المرأة تخرج من العدة بوضع الحمل، متى وضعت الحمل خرجت من العدة، ولم يلحقها طلاق بعد ذلك، إذا كان الزوج لم يراجعها بعد طلاقه الذي وقع منه وهي حبلى، فإذا كان لم يراجعها قبل وضع الحمل فإنها تبين بوضع الحمل، ولا يلحقها طلاق بعد ذلك.\nوبكل حال فالمحكمة تنظر في الأمر، وفيما تراه الكفاية -إن شاء الله-، وإذا أحب الزوج أن يراجعني في ذلك وأنا أحيله إلى المحكمة لنعرف الحقيقة، ثم تكون فتوى على ضوء ذلك مني، أو من المحكمة فلا بأس بذلك، نسأل الله للجميع التوفيق والهداية. المقدم: لكن قول المحكمة أن هذا الطلاق يعتبر بينونة صغرى؟ الشيخ: هذا على كل حال إذا كانت الطلقة واحدة...، على عوض هي بينونة صغرى، إذا طلقها واحدة أو ثنتين على عوض يسميها العلماء بينونة صغرى، يعني: لا يراجعها، ولكن تحل له بعقد جديد، هذا معنى البينونة الصغرى، يعني: ليس له الرجعة بدون عقد، بل لا بد من عقد جديد مثل المرأة التي طلقها واحدة، أو ثنتين، وخرجت من العدة ليس له مراجعتها بعد العدة، ولكن يحل له نكاحها بعقد جديد، فهكذا إذا طلقها على عوض يسمى خلعًا، ويسمى طلاق خلع، وتسمى الفرقة هذه فرقة بينونة صغرى، يعني: يحلها العقد، ولا تحل بالمراجعة فقط، بل لا بد من عقد جديد، ولكن لا تحتاج إلى زوج جديد، بل يكفي العقد الجديد هذا المراد. أما البينونة الكبرى فهذه لا يحلها إلا زوج جديد شرعي، يطأ المرأة، يتزوجها ويطؤها، البينونة الكبرى وهي إذا طلقها الطلقة الأخيرة الثالثة، فإن هذه بينونة كبرى لا تحل لزوجها الأول حتى تنكح زوجًا غيره نكاحًا شرعيًا ليس نكاح تحليل، ويطؤها الزوج الجديد، ثم يفارقها بعد ذلك بموت أو بطلاق، فإذا خرجت من العدة بعد ذلك حلت للزوج الأول بعد هذا النكاح الشرعي الجديد الذي فيه الوطء، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/14594/عدة-الحامل-والفرق-بين-البينونة-الصغرى-والكبرى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_679/nour_67903.mp3","categories":["العِدَد","قضايا المرأة"]},{"id":16162,"question":"من المدينة المنورة رسالة بتوقيع إحدى الأخوات من هناك تقول: المرسلة أم أسامة من المدينة المنورة، تسأل وتقول: هل يحل للزوجة المعتدة على زوجها المتوفى أن تخرج من بيتها في فترة العدة إلى أبنائها، أو بناتها إذا دعوها إليهم، مع الرجوع إلى بيتها في نفس اليوم، وعدم المبيت عندهم؟","title":"حكم زيارة المعتدة عدة وفاة لأولادها","answer":"الجواب: المعتدة من الوفاة وهي المحادة الواجب عليها بقاؤها في البيت الذي مات زوجها وهي ساكنة فيه، لا تخرج إلى الناس للزيارات، لا لأولادها، ولا غيرهم؛ لقول النبي ﷺ للمعتدة: امكثي في بيتك حتى يبلغ الكتاب أجله هكذا أمر المعتدة -عليه الصلاة والسلام- قال لها: امكثي في بيتك حتى يبلغ الكتاب أجله.  لكن خروجها لحاجة مثل المستشفى الطبيب، مثل دعوى عليها خصومة في المحكمة مثل حاجة في السوق تشتري حاجاتها لا بأس، أما أن تزور الناس، تزور أولادها، أو غيرهم هذا لا يصلح تبقى في البيت. لكن لو كان هناك حاجة مهمة مثل مدرسة، مثل طالبة يفوتها العلم؛ فلها الخروج لهذه الحاجات المهمة، كونها طالبة، أو مدرسة، أو موظفة هذه حاجات مهمة، لها أن تخرج، لكن بغير زينة، وفي ثياب عادية ليس فيها جمال، وغير متطيبة، ولا مكتحلة، ولا لابسة حليًا، تلزم الأمور الأخرى؛ لأن المعتدة يلزمها أن تبقى في البيت إلا من حاجة، ويلزمها عدم الطيب، وعدم لبس الحلي، وعدم الملابس الجميلة، وعدم التكحل والحناء. ولو خرجت لحاجة تراعي هذه الأمور: لا تلبس الحلي، ولا تلبس الثياب الجميلة، ولا تكتحل، ولا تتطيب، ولا تفعل الحناء لتجمل يديها، أو في رجليها، أو في رأسها، أو غير ذلك حتى تنتهي بها العدة عدة الوفاة. فإذا خرجت بهذه الحالة لحاجة؛ فلا بأس، وليس لها أن تلبس ملابس جميلة، تلبس ملابسًا عادية في بيتها، وعند خروجها، فإذا كملت المدة -الحمد لله- تلبس ما تعتاده، والحمد لله، نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14854/حكم-زيارة-المعتدة-عدة-وفاة-لاولادها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_805/nour_80509.mp3","categories":["العِدَد","قضايا المرأة"]},{"id":16330,"question":"ما الذي يجوز للمحادة إذا توفي عنها زوجها؟ هل تخرج من بيتها لقضاء حاجتها، وأعمالها مثل زيارة الأقارب، وهل تستطيع الخروج ليلًا، أم نهارًا فقط؟","title":"الأمور التي على المرأة المحاداة مراعاتها","answer":"الجواب: المحادة عليها أن تراعي خمسة أمور: الأمر الأول: بقاؤها في البيت حتى تنتهي عدتها؛ لأن الرسول ﷺ أمر المرأة بذلك، لكن لها الخروج لحاجتها مثل: شراء حاجة من السوق، طعام أو غيره من السوق، أو الذهاب إلى المستشفى للعلاج، أو المحكمة للخصومة، لا بأس بذلك، وهكذا خروجها لكونها مدرسة، أو طالبة لا بأس بذلك، أو مديرة، لكن مع مراعاة الأمور الأربعة الأخرى. الثاني: عدم الملابس الجميلة ملابس عادية. الثالث: عدم الطيب. الرابع: عدم الحلي، لا ذهبًا، ولا فضة، ولا أسورة من ماس، أو غيره. الخامس: عدم التكحل والحناء، فإذا راعت هذه الأمور؛ فلها الخروج لحاجتها من تدريس، أو طلب علم، أو خصومة، أو علاج.. أو نحو ذلك، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/15024/الامور-التي-على-المراة-المحاداة-مراعاتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/%D9%85%D8%A7%20%D9%8A%D8%AC%D9%88%D8%B2%20%D9%84%D9%84%D9%85%D8%AD%D8%A7%D8%AF%D9%91%D8%A9%20%D9%81%D8%B9%D9%84%D9%87.mp3","categories":["العِدَد","قضايا المرأة"]},{"id":16784,"question":"من المستمع محمد محسن أحمد من اليمن رسالة وضمنها سؤالين، في سؤاله الأول يقول: عندنا تقاليد إذا مات الرجل أمروا الزوجة أن تلبس ثيابًا بيضًا مدة أربعة أشهر وعشرة أيام، ولا تلبس ثيابًا سوى الملابس البيض، فهل هذه العادة لها أصل؟ وهل يجوز التمسك بها؟ جزاكم الله خيرًا.","title":"حكم تخصيص ثياب معينة للمعتدة عدة وفاة","answer":"الجواب: هذه العادة باطلة، ولا يجوز التمسك بها، الرسول ﷺ قال: لا تلبس ثوبًا مصبوغًا إلا ثوب عصب وإلا ثوب ليس فيه جمال، تلبس الأسود والأخضر والأحمر والأبيض الذي ليس فيه تشبه بالرجال إذا كان ليس فيه زينة، ولا تشبه بالرجال. أما تخصيص الأبيض، أو الأسود؛ هذا لا دليل عليه، بل يكون بدعة التخصيص، ولكن يجوز لها أن تلبس كل ثوب ليس بجميل، ليس صبغه جميلًا من أخضر، وأسود، وأحمر، وأبيض، وغير ذلك، أما الجميل فلا يجوز لها لبسه؛ لأنه قد يحصل به فتنة، كما أنها لا تختضب بالحناء، ولا تلبس الحلي، ولا تمس الطيب مدة الإحداد أربعة أشهر وعشرًا إن كانت غير حامل.  أما إن كانت حاملة؛ فمدتها وضع الحمل؛ لقوله ﷺ: لا تلبس ثوبًا مصبوغًا إلا ثوب عصب، ولا تكتحل، ولا تمس طيبًا -عليه الصلاة والسلام- ونهى عن لبس الحلي أيضًا، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15536/حكم-تخصيص-ثياب-معينة-للمعتدة-عدة-وفاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_762/nour_76215.mp3","categories":["العِدَد","قضايا المرأة"]},{"id":16942,"question":"هذه رسالة طويلة وصلت من اليمن من مستمع للبرنامج يقول: سماحة الشيخ -حفظكم الله- المرأة عندنا الذي يتوفى عنها زوجها لا تعتد المدة الذي حددها الشرع الإسلامي، ولا تمتنع من وضع الطيب، والكحل، وغير ذلك من الممنوعات، وهذه المرأة هي المسؤولة في الزراعة، وجلب الماء من الآبار، وغيرها من الأعمال، ما توجيه سماحتكم لهم لعلهم يسمعون ذلك؟","title":"أحكام المعتدة عدة وفاة","answer":"الجواب: الواجب على المرأة إذا توفي عنها زوجها أن تعتد أربعة أشهر وعشًرا؛ إذا كانت غير حامل، أربعة أشهر وعشرًا، وأن تجتنب الطيب، والملابس الجميلة، والكحل، ولبس الحلي حتى تكمل العدة كما أمر النبي ﷺ فعليها أن تعتد أربعة أشهر وعشرًا كما قال الله -جل وعلا-: وَالَّذِينَ يُتَوَفَّوْنَ مِنْكُمْ وَيَذَرُونَ أَزْوَاجًا يَتَرَبَّصْنَ بِأَنفُسِهِنَّ أَرْبَعَةَ أَشْهُرٍ وَعَشْرًا [البقرة:234]. هذا هو الواجب على كل امرأة مات عنها زوجها أن تعتد أربعة أشهر وعشرًا، وأن تجتنب أسباب الفتنة: الطيب، والكحل، والحنا، ولبس الحلي من الذهب، والفضة، ونحو ذلك حتى تكمل العدة، والواجب تعليمهن، تعليمهن ذلك، تعليم المتوفى عنها حتى تمتثل الشرع، حتى تعمل بالشرع، سواءٌ كانت في داخل القرية، أو في خارج القرية، في النخيل، في المزارع، في البادية، تتعلم. الواجب على أوليائها أن يعلموها كيف تعتد، سواءٌ كانت في البلد، في المدينة، في القرية، أو في المزرعة الخارجية، أو في البادية، الواجب التعليم، الله يقول -جل وعلا-: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى [المائدة:2] ويقول سبحانه: وَالْعَصْرِ ۝ إِنَّ الإِنسَانَ لَفِي خُسْرٍ ۝ إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَتَوَاصَوْا بِالْحَقِّ وَتَوَاصَوْا بِالصَّبْرِ [العصر:1-3]، ويقول الله سبحانه: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنكَرِ وَيُقِيمُونَ الصَّلاةَ وَيُؤْتُونَ الزَّكَاةَ وَيُطِيعُونَ اللَّهَ وَرَسُولَهُ أُوْلَئِكَ سَيَرْحَمُهُمُ اللَّهُ إِنَّ اللَّهَ عَزِيزٌ حَكِيمٌ [التوبة:71]. هذا الواجب على المؤمنين أن يتراحموا، وأن يأمروا بالمعروف، وأن ينهوا عن المنكر، وأن يتعاونوا على البر والتقوى، وأن يتواصوا بالحق، والصبر عليه، هكذا في كل مكان، الواجب التعاون على البر والتقوى، والتواصي بالحق، والتناصح، والأمر بالمعروف، والنهي عن المنكر، وتعليم الجاهل، تعليم المرأة الجاهلة، وتعليم الرجل الجاهل، وتعليم الشاب، وتعليم غيره، لا بد من التعليم، والتواصي بالحق، والتناصح، هذا هو واجب الجميع، وبذلك يستحق العبد الرضا من الله، والكرامة، وهذا معنى قوله سبحانه: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى [المائدة:2]، وقوله : وَالْعَصْرِ ۝ إِنَّ الإِنسَانَ لَفِي خُسْرٍ ۝ إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَتَوَاصَوْا بِالْحَقِّ وَتَوَاصَوْا بِالصَّبْرِ [العصر:1-3] وقوله -جل وعلا-: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنكَرِ [التوبة:71]. ويقول النبي ﷺ: مثل المؤمنين في توادهم، وتراحمهم، وتعاطفهم مثل الجسد، إذا اشتكى منه عضو تداعى له سائر الجسد بالسهر والحمى ويقول ﷺ: المؤمن للمؤمن كالبنيان يشد بعضه بعضًا، وشبك بين أصابعه ويقول ﷺ: من كان في حاجة أخيه؛ كان الله في حاجته متفق على صحته، ويقول ﷺ: والله في عون العبد ما كان العبد في عون أخيه أخرجه مسلم في الصحيح. فالواجب على جميع المسلمين في كل مكان أن يتعاونوا رجالًا ونساء، على الرجال أن يتعاونوا، وعلى النساء أن يتعاون في طاعة الله ورسوله، في التثقيف في الدين، في التعليم، في الأمر بالمعروف، في النهي عن المنكر، في التواصي بالحق، يعلم العالم الجاهل، المرأة تعلم المرأة، والرجل يعلم المرأة، والمرأة تعلم الرجل، تعليم من الرجال والنساء جميعًا على الوجه الشرعي، فالمرأة تعلم، ولو غير محرمها من وراء حجاب، تنصح وتعلم، والرجل يعلم، ولو غير امرأته، ولو غير نسائه، يعلم النساء من جيرانه، من أقاربه في المسجد، يعلمهن، يشرح لهن أمر الله، يوصيهن بطاعة الله، هكذا إمام المسجد، هكذا الخطيب، لا بد من التواصي بالحق مع الرجال، والنساء، لا بد من التناصح، نسأل الله للجميع الهداية. المقدم: اللهم آمين، جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/15720/احكام-المعتدة-عدة-وفاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_586/58615.mp3","categories":["العِدَد","قضايا المرأة"]},{"id":17244,"question":"من أسئلة هذا السائل من اليمن أبو الفضل، يقول: سماحة الشيخ، ما هو القول الراجح في عدة المتوفى عنها زوجها؟ أقصد هنا الحامل؟ مع بيان أهم الأحكام في الإحداد، حيث إنه يا سماحة الشيخ، وقع تفريطٌ وإفراط في هذا الزمان، والغالب التفريط، فنرجو من سماحتكم التوجيه.","title":"عدة الحامل المتوفى عنها زوجها وأهم أحكام الإحداد","answer":"الجواب: عدة المتوفى عنها: أربعة أشهر وعشرًا، مائة وثلاثون يومًا، إذا كانت غير حامل، أما الحامل؛ عدتها وضع الحمل، الله يقول سبحانه: وَأُوْلاتُ الأَحْمَالِ أَجَلُهُنَّ أَنْ يَضَعْنَ حَمْلَهُنَّ [الطلاق:4] فلو مات اليوم، وولدت غدًا، خرجت من العدة، ولو بعدها بيوم، أو يومين، خرجت من العدة؛ لأن الله سبحانه يقول: وَأُوْلاتُ الأَحْمَالِ أَجَلُهُنَّ أَنْ يَضَعْنَ حَمْلَهُنَّ [الطلاق:4]. وجاءت امرأة يقال لها: سبيعة الأسلمية، إلى النبي ﷺ وأخبرته أن زوجها مات قريبًا، وأنها خرجت من عدته، فأذن لها في ذلك، لما عاب عليها بعض الناس، وأخبرها أن عدتها انتهت من حين وضعت الحمل، هذا هو الحكم الشرعي، متى وضعت الحمل، خرجت من العدة، والمحادة عليها أمورٌ خمسة: عليها أن تلزم البيت الذي مات زوجها وهي ساكنة فيه. وعليها ألا تلبس الملابس الجميلة، ملابس عادية. الثالث: عليها أن تجتنب الطيب. الرابع: أن تجتنب الحلي من الذهب، والفضة، ونحوها، الزينة. الخامس: عدم الكحل، هذا هو واجب المحادة. نعم. المقدم: أحسن الله إليكم، وبارك فيكم.","link":"https://binbaz.org.sa/fatwas/16076/عدة-الحامل-المتوفى-عنها-زوجها-واهم-احكام-الاحداد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_591/59121.mp3","categories":["العِدَد","قضايا المرأة"]},{"id":17266,"question":"هذا السائل أخوكم في الله رمز لاسمه بهذا الرمز (ع. م. س) يقول: أرجو من سماحة الشيخ أن يشرح لنا بعض الأمور التي غفلت عنها كثير من نساء هذا الزمان، وهو أن الرجل إذا طلق زوجته لا يجوز لها شرعًا أن تخرج من البيت إلا بعد الانتهاء من العدة، أقصد طلقة واحدة، وجزاكم الله خيرًا.","title":"حكم خروج المطلقة رجعيًّا من بيت زوجها","answer":"الجواب: نعم الواجب على المرأة ألا تخرج إذا طلقها طلقة رجعية طلقة واحدة، أو طلقتين؛ لقوله -جل وعلا-: يا أيها النَّبِيُّ إِذَا طَلَّقْتُمُ النِّسَاءَ فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ وَأَحْصُوا الْعِدَّةَ وَاتَّقُوا اللَّهَ رَبَّكُمْ لا تُخْرِجُوهُنَّ مِنْ بُيُوتِهِنَّ وَلا يَخْرُجْنَ إِلَّا أَنْ يَأْتِينَ بِفَاحِشَةٍ مُبَيِّنَةٍ [الطلاق:1] إذا كان بقاؤها يؤذيه؛ لأنها سليطة اللسان، تؤذي أهل بيته، فلا بأس بخروجها، أما إذا كانت عاقلة، وطيبة لا تؤذي؛ فالواجب عليها البقاء في البيت؛ لعله يتراجع .. لعله يهون، يرجعها، فلا يخرجها، ولا تخرج، إذا كان الطلاق طلقة، أو طلقتين، طلاقًا رجعيًا، أما إذا كان بائنًا الطلقة الثالثة؛ فإنها تخرج، لا بأس؛ لأنه لا سبيل له عليها. نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/16105/حكم-خروج-المطلقة-رجعيا-من-بيت-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_592/59216.mp3","categories":["العِدَد","قضايا المرأة"]},{"id":17279,"question":"من أسئلتها يا سماحة الشيخ، تقول، يقول هذا السائل من اليمن أحمد عبده: امرأة مات زوجها، وكان من الصعب عليها أن تعتد أربعة أشهر وعشرًا؛ نظرًا لأنها تقوم بأعمال شاقة في المنزل وخارج المنزل، فما الحل في ذلك مأجورين؟","title":"حكم خروج المعتدة إلى العمل","answer":"الجواب: عليها أن تعتد أربعة أشهر وعشرًا، وتلزم الإحداد، وتعمل الأعمال التي تضطر إليها، إن كانت موظفة تذهب إلى وظيفتها، إن كانت مدرسة تذهب إلى التدريس وترجع، تلزم بيتها حتى تكمل أربعة أشهر وعشرًا، ولا بأس أن تذهب لحاجتها، أو وظيفتها، أو عملها إذا كان لها عمل في البيع والشراء في السوق، تخرج لكن متسترة، ولا تلمس الطيب، ولا الكحل، ولا الحناء، ولا تلبس الحلي، ولكن تخرج في ثياب عادية؛ لحاجتها، يجوز لها الخروج لحاجتها في بيعها وشرائها ووظيفتها التدريس، أو غيره، لا حرج في ذلك. المقدم: حفظكم الله تكون بذلك يا شيخ متجنبة للزينة في لباسها؟ الجواب: تتجنب الزينة والطيب والحلي والكحل ونحو ذلك، ممنوعة؛ لأن الحادة ممنوعة من خمسة أشياء: الأول: الخروج من دون حاجة، تلزم البيت إذا تيسر لها بيت زوجها، تلزمه الذي مات وهي ساكنة فيه، أما إذا كان بالكراء وأخرجت معذورة، لكن إذا كان البيت له، أو سمح المؤجرون، وبقيت فيه تبقى فيه حتى تكمل العدة. الثاني: عدم الملابس الجميلة، ملابس عادية. الثالث: عدم الطيب والحناء ونحوه. الرابع: عدم الحلي من الذهب والفضة. الخامس: عدم الكحل. أما خروجها لحاجتها لا بأس، وظيفتها تخرج لها: مدرسة، طالبة، تبيع في السوق لحاجتها، لا بأس. المقدم: هل للمحادة يا شيخ أن تنتقل من قرية إلى أخرى؟ الشيخ: نعم. المقدم: هل لها أن تسافر يا شيخ؟ الجواب: ليس لها السفر. المقدم: ليس لها السفر. الشيخ: تلزم البيت. المقدم: طيب. الشيخ: وتبيت فيه. المقدم: حفظكم الله.","link":"https://binbaz.org.sa/fatwas/16120/حكم-خروج-المعتدة-الى-العمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_593/59302.mp3","categories":["العِدَد","قضايا المرأة"]},{"id":17472,"question":"هل يجوز لها أن تحد على أقاربها ثلاثة أيام كالأب، والأم، وغيرهم؟","title":"حكم إحداد المرأة على أقاربها ثلاثة أيام","answer":"الجواب: لها ذلك، ثلاثة أيام لا بأس، يعني: تترك الزينة، تترك الطيب، مثلما جاء في الحديث: لا تحد امرأة على ميت فوق ثلاث دل على أن الثلاث جائزة، على أخيها، على أخي أبيها.. على عمها.. على ولدها، لا بأس. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16367/حكم-احداد-المراة-على-اقاربها-ثلاثة-ايام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_773/nour_77304.mp3","categories":["العِدَد","قضايا المرأة"]},{"id":18030,"question":"تسأل أختنا من السودان فتقول: الإحداد في مجتمعنا السوداني:أولاً: لزوم المرأة المعتدة، وافتراشها للأرض طوال المدة المقررة لها.ثانيًا: مواجهة حائط الغرفة.ثالثًا: امتناعها عن الكلام، وخاصة عند شروق الشمس وعند الغروب، في فترة يطلق عليها النساء زمن الحضانة.رابعًا: امتناعها عن الاستحمام وغسل الثياب.فهل هذا من الدين في شيء، ونسبة لكثرة النساء اللائي يتقيدن بهذه الظاهرة؟ أرجو من سماحة الشيخ أن يوجه الجميع، جزاكم الله خيرًا.","title":"من بدع الإحداد المخالفة للشرع","answer":"الجواب: كل هذا لا أصل له في الشرع، الواجب امتثال الشرع، والتقيد بالشرع المطهر، فالمحادة عليها أن تبقى في البيت الذي مات زوجها وهي ساكنة فيه، تبقى المدة أربعة أشهر وعشرًا، إن كانت غير حبلى، أما إن كانت حبلى؛ فإنها تبقى العدة، حتى تضع الحمل، والواجب عليها ترك الطيب والحلي والملابس الجميلة والكحل والحناء، هذه الأشياء التي ترغب فيها وتجعلها محل نظر، هذه يجب تركها، كما جاءت بذلك الأحاديث عن رسول الله عليه الصلاة والسلام. أما ما ذكرته السائلة من كونها تفترش الأرض، ولا تجلس على بساط، هذا لا أصل له، هذا باطل وهذا تعنت وتكلف، كذلك استقبالها الحائط، هذا غلط -أيضًا- تستقبل ما شاءت مثل غيرها من النساء، كذلك كونها -أيش الثالث؟ المقدم: كونها تمتنع عن كلام الناس. الشيخ: كذلك امتناعها عن كلام الناس، هذا غلط -أيضًا- تكلم من شاءت مثل غيرها من النساء، تكلم أقاربها .. تكلم أولادها .. تكلم جيرانها .. تكلم من استأذن عليها بالكلام الذي ليس فيه محذور، لكن لا تخلو بأحد من الرجال مثل غيرها من النساء، أما الكلام فلا بأس مع محارمها وغيرهم في مصالحها وشئونها، على وجه لا ريبة فيه. نعم. الرابع. المقدم: كونها تلتزم الصمت -أيضًا- عند الشروق وعند الغروب في فترة يسمونها الحضانة؟ الشيخ: كذلك هذا باطل، ليس عليها التزام الصمت عند الشروق والغروب، بل تكلم في جميع النهار، وفي جميع الليل، هذه الأشياء الأربعة كلها لا أصل لها ولا أساس لها، بل يجب على المسلمة تجنب ذلك، وأن لا تخضع للبدع والخرافات التي أحدثها الناس، وإنما عليها ما أمرها به الشارع عليه الصلاة والسلام من تجنب الملابس الجميلة، ومن ترك الطيب والحلي؛ لأنها تلفت النظر، وتسبب رغبة الرجال فيها، وهكذا ليس لها أن تكحل عينيها، ولا أن تستعمل الحناء؛ لأن هذا يسبب الفتنة بها، مع بقائها في بيت زوجها إذا تيسر ذلك الذي مات زوجها وهي ساكنة فيه، إذا تيسر، أما إذا خرب البيت أو كان مستأجرًا ولم يسمح أن يقوم بتأجيره، أو كانت وحدها تستوحش، ما عندها من يؤنسها تنتقل إلى بيت أهلها، كل هذا لا بأس به، نسأل الله للجميع التوفيق. نعم. المقدم: اللهم آمين، جزاكم الله خيرًا. نقطة مهمة سماحة الشيخ لو تكرمتم، كونها تمتنع عن الاستحمام وغسل الثياب؟ الشيخ: كذلك هذا أيضًا غلط، لها أن تستحم متى شاءت من ليل أو نهار، في أي يوم، يوم الجمعة وفي غيره، ولها أن تمتشط متى شاءت، لكن من دون طيب، ولها أن تغسل الثياب: ثيابها أو ثياب أولادها، كل هذا لا بأس به، كل هذا التكلف لا أصل له، نعوذ بالله من طاعة الشيطان. نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17058/من-بدع-الاحداد-المخالفة-للشرع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_599/59906.mp3","categories":["العِدَد","البدع والمحدثات"]},{"id":18577,"question":"هذا السائل، أختكم في الله أم محمد من الشارقة الإمارات العربية المتحدة، تقول: هل الحداد هو آخر حقوق الزوج؟ وهل تأتي به المرأة بعد وفاة الزوج مباشرة؟","title":"حكم إحداد الزوجة على زوجها","answer":"الجواب: نعم، هذا حق من حقوقه عليها، تأتي به بعد موته أربعة أشهر وعشرًا، إلا إذا كانت حاملاً فبوضع الحمل تجتنب الملابس الجميلة، والطيب والحلي والكحل، حتى تمضي أربعة أشهر وعشرًا، هذا من حقه عليها، إلا أن تكون حبلى فينتهي الإحداد بوضع الحمل؛ لقوله -جل وعلا-: وَأُوْلاتُ الأَحْمَالِ أَجَلُهُنَّ أَنْ يَضَعْنَ حَمْلَهُنَّ [الطلاق:4].  ومن حقه عليها بعد ذلك الدعاء له بالمغفرة والرحمة، وذكر أعماله الطيبة، والكف عن عرضه وعن غيبته، هذا من حقه عليها بعد الموت، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/17690/حكم-احداد-الزوجة-على-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_918/nour_91807.mp3","categories":["العِدَد","قضايا المرأة"]},{"id":18934,"question":"رسالة وصلت إلى البرنامج من زنجبار، تنزانيا، وباعثها أحد الإخوة من هناك وقع في نهاية رسالته، أخونا يقول: أرجو من سماحتكم أن تجيبوا على أسئلتي التالية:ما حكم المرأة التي ولدت، ثم توفي زوجها في نفس اليوم؟ هل عدتها أربعة أشهر وعشرًا أم تقضي أيام النفاس، ثم يمكن الزواج من آخر؟","title":"عدة المرأة التي توفي عنها زوجها عقب ولادتها","answer":"الجواب: إذا مات الرجل بعد الولادة، هذا عليها العدة بعد ذلك، أما إذا مات وهي حبلى، ثم ولدت بعد وفاته، ولو بساعة، ولو بدقائق، فإنها تخرج من العدة؛ لأن الله -جل وعلا- قال: وَأُوْلاتُ الأَحْمَالِ أَجَلُهُنَّ أَنْ يَضَعْنَ حَمْلَهُنَّ [الطلاق:4] فإذا كانت ولادتها بعد وفاته ولو بخمس دقائق، ولو بعشر دقائق، فإنها تخرج بذلك من عدته، وليس عليها عدة بعد ذلك، ولها أن تتزوج بعد وضع الحمل، ولو في مدة النفاس، لكن الزوج لا يطؤها حتى تطهر، كما أنها لها أن تتزوج وهي في الحيض إذا كانت في غير عدة، ولكن ليس للزوج أن يقربها حتى تطهر. فالخلاصة: أن المرأة إذا وضعت حملها بعد وفاة زوجها ولو بقليل، ولو بدقائق، فإنها تخرج من العدة بوضع الحمل؛ لقول الله سبحانه: وَأُوْلاتُ الأَحْمَالِ أَجَلُهُنَّ أَنْ يَضَعْنَ حَمْلَهُنَّ [الطلاق:4] ولذا في الصحيحين من حديث سبيعة الأسلمية: \"أنها وضعت بعد وفاة زوجها بليال، فاستفتت النبي ﷺ فأفتاها: بأنها قد حلت من زوجها بوضعها الحمل\"، نعم.","link":"https://binbaz.org.sa/fatwas/18069/عدة-المراة-التي-توفي-عنها-زوجها-عقب-ولادتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_924/nour_92402.mp3","categories":["العِدَد"]},{"id":19571,"question":"تقول يا سماحة الشيخ: ما معنى كلمة المعصفر في حديث النهي عن لبس الثوب المعصفر بالنسبة للرجال، وهل يشمل جميع الملابس الحمراء للرجال، سواء كانوا كبارًا أو صغارًا؟","title":"حكم لبس المحادة الثوب المعصفر","answer":"الجواب: هذا تنهى عنه المرأة في حال الإحداد، ولا تلبس ثوب معصفر، المعصفر: هو المصبوغ بصبغ يكون جميلًا، يكون به جميلًا فلا تلبس الثوب المصبوغ صبغًا يجمله، أما إذا كان ثوبًا ليس فيه جمال فلا يضر هذا بالنسبة إلى المحادة، تلبس ثيابًا ليس فيها جمال. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18843/حكم-لبس-المحادة-الثوب-المعصفر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_947/nour_94725.mp3","categories":["اللباس والزينة","العِدَد"]},{"id":19698,"question":"امرأة طلَّقها زوجُها ولم تعلم، وكانت في بيت أهلها سنتين، وقد اتَّصل بهم شخصٌ يُخبرهم بطلاقها، وكانت مسافرةً مع أهلها بعد وقتٍ وجيزٍ من الاتصال، ثم سافرت ومكثت أربعة أيام في مدينةٍ أخرى، ثم عادت، فما الحكم في عدَّتها والحالة هذه؟","title":"متى تبدأ عدة المطلقة ومتى تنتهي","answer":"الجواب: إذا ثبت الطلاقُ فعدَّتها تنتهي بثلاث حيض إذا كانت تحيض، أو بثلاثة أشهر إن كانت آيسةً لا تحيض، أو صغيرةً لا تحيض، أو بوضع الحمل إن كانت حبلى، من حين وقع الطلاق، إذا ثبت ببينةٍ أو بإقرار الزوج أنه طلَّقها في يوم كذا، في شهر كذا، فالعمدة على ذلك؛ لأنه أعلم بالواقع، وعليه إثمٌ، عليه أن يتوب إلى الله في تأخير إبلاغها وحبسها هذا الحبس الطويل، فعليه نفقتها وقت العدَّة، أما ما زاد عن العدَّة فهذا يُرجع فيه إلى المحكمة إن طالبوه بالزيادة بحبسه إيَّاها. المقصود أنَّ الواجب عليه أن يُبين من حين طلَّق، وأن لا يكذب كذلك، وأن لا يحبسها، وعليه أن يُطالَب بما يستحقّ من العقوبة؛ لأنه وجد مثل هذا العمل، فلأوليائها ولها أن تُطالب بحقِّ هذا الحبس من عقوبةٍ وتعزيرٍ ونفقةٍ وغير ذلك، والله المستعان.","link":"https://binbaz.org.sa/fatwas/20541/متى-تبدا-عدة-المطلقة-ومتى-تنتهي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0506%D9%81%D8%AA%D8%A7%D9%88%D9%89%20%D8%A7%D9%84%D9%85%D8%AD%D8%A7%D8%B6%D8%B1%D8%A7%D8%AA%20%D9%84%D9%84%D8%B4%D9%8A%D8%AE%20%D8%B9%D8%A8%D8%AF%D8%A7%D9%84%D8%B9%D8%B2%D9%8A%D8%B2%20%D8%A8%D9%86%20%D8%A8%D8%A7%D8%B2%20%D8%B1%D8%AD%D9%85%D9%87%20%D8%A7%D9%84%D9%84%D9%87.mp3","categories":["العِدَد"]}]
